  `company_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '物流公司id',
  `company_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司logo',
  `url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司网址',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `express_no_kdniao` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '快递鸟编码',
  `express_no_kd100_free` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '快递100编码',
  `express_no_kd100` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '快递100编码',
  `express_no_cainiao` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '菜鸟物流接口编码',
  `express_no_ext` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '快递查询接口编码',
  `content_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '打印内容',
  `background_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '背景图',
  `font_size` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印字体',
  `width` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '宽度',
  `height` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '高度',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `scale` decimal(10, 2) NOT NULL DEFAULT 1.00 COMMENT '真实尺寸（mm）与显示尺寸（px）的比例',
  `is_electronicsheet` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否支持电子面单（0不支持  1支持）',
  `print_style` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '电子面单打印风格',
  PRIMARY KEY (`company_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 AVG_ROW_LENGTH = 8192 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统物流公司表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_company
-- ----------------------------

-- ----------------------------
-- Table structure for express_company_shop
-- ----------------------------
DROP TABLE IF EXISTS `express_company_shop`;
CREATE TABLE `express_company_shop`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `company_id` int(11) NOT NULL DEFAULT 0 COMMENT '物流公司id',
  `content_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '打印内容',
  `background_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '背景图',
  `font_size` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印字体',
  `width` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '宽度',
  `height` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '高度',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `scale` decimal(10, 2) NOT NULL DEFAULT 1.00 COMMENT '真实尺寸（mm）与显示尺寸（px）的比例',
  `company_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'logo',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺物流公司' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_company_shop
-- ----------------------------

-- ----------------------------
-- Table structure for express_delivery_package
-- ----------------------------
DROP TABLE IF EXISTS `express_delivery_package`;
CREATE TABLE `express_delivery_package`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_goods_id_array` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单项商品组合列表',
  `goods_id_array` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品组合列表',
  `package_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '包裹名称  （包裹- 1 包裹 - 2）',
  `delivery_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '发货方式1 需要物流 0无需物流',
  `express_company_id` int(11) NOT NULL DEFAULT 0 COMMENT '快递公司id',
  `express_company_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `delivery_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '运单编号',
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名称',
  `express_company_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发货公司图片',
  `type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发货方式（manual 手动发货  electronicsheet 电子面单发货）',
  `template_id` int(11) NOT NULL DEFAULT 0 COMMENT '电子面单模板id',
  `template_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '电子面单模板名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_express_delivery_package_order_id`(`order_id`) USING BTREE,
  INDEX `IDX_express_delivery_package_site_id`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品订单物流信息表（多次发货）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_delivery_package
-- ----------------------------

-- ----------------------------
-- Table structure for express_electronicsheet
-- ----------------------------
DROP TABLE IF EXISTS `express_electronicsheet`;
CREATE TABLE `express_electronicsheet`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `template_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `company_id` int(1) NOT NULL DEFAULT 0 COMMENT '物流公司id',
  `company_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `express_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '编码',
  `customer_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'CustomerName',
  `customer_pwd` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'CustomerPwd',
  `send_site` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'SendSite',
  `send_staff` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'SendStaff',
  `month_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'MonthCode',
  `postage_payment_method` tinyint(3) NOT NULL DEFAULT 0 COMMENT '邮费支付方式（1现付 2到付 3月结）',
  `is_notice` tinyint(3) NOT NULL DEFAULT 0 COMMENT '快递员上门揽件（0否 1是）',
  `status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '状态（0正常 -1不使用）',
  `is_default` tinyint(3) NOT NULL DEFAULT 0 COMMENT '是否默认（0否 1是）',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `print_style` int(11) NOT NULL DEFAULT 0 COMMENT '模板风格',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '电子面单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_electronicsheet
-- ----------------------------

-- ----------------------------
-- Table structure for express_template
-- ----------------------------
DROP TABLE IF EXISTS `express_template`;
CREATE TABLE `express_template`  (
  `template_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家店铺id',
  `template_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `fee_type` int(11) NOT NULL DEFAULT 0 COMMENT '运费计算方式1.重量2体积3按件',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `is_default` int(11) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `surplus_area_ids` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '剩余地址id',
  PRIMARY KEY (`template_id`) USING BTREE,
  INDEX `IDX_express_template_is_default`(`is_default`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '运费模板' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_template
-- ----------------------------

-- ----------------------------
-- Table structure for express_template_item
-- ----------------------------
DROP TABLE IF EXISTS `express_template_item`;
CREATE TABLE `express_template_item`  (
  `item_id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板id',
  `area_ids` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '地址id序列',
  `area_names` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '地址名称序列',
  `snum` int(11) NOT NULL DEFAULT 0 COMMENT '起步计算标准',
  `sprice` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '起步计算价格',
  `xnum` int(11) NOT NULL DEFAULT 0 COMMENT '续步计算标准',
  `xprice` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '续步计算价格',
  `fee_type` int(11) NOT NULL DEFAULT 1 COMMENT '运费计算方式',
  PRIMARY KEY (`item_id`) USING BTREE,
  INDEX `IDX_express_template_item_fee_type`(`fee_type`) USING BTREE,
  INDEX `IDX_express_template_item_template_id`(`template_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '运费模板细节' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of express_template_item
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao`;
CREATE TABLE `fenxiao`  (
  `fenxiao_id` int(11) NOT NULL AUTO_INCREMENT,
  `fenxiao_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分销商编号',
  `fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分销店铺名',
  `mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '联系电话',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员ID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销商等级id',
  `level_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `parent` int(11) NOT NULL DEFAULT 0 COMMENT '上级ID',
  `grand_parent` int(11) NOT NULL DEFAULT 0 COMMENT '上上级id',
  `account` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当前佣金',
  `account_withdraw` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已提现佣金',
  `account_withdraw_apply` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现中佣金',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态（1已审核 2拒绝 -1已冻结）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '成为经分销商时间',
  `lock_time` int(11) NOT NULL DEFAULT 0 COMMENT '冻结时间',
  `one_fenxiao_order_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级分销订单总数',
  `one_fenxiao_order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级分销订单总额',
  `one_child_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级下线人数',
  `one_child_fenxiao_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级下线分销商',
  `two_child_fenxiao_num` int(11) NOT NULL DEFAULT 0 COMMENT '二级下线分销商',
  `total_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计佣金',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '会员注销',
  PRIMARY KEY (`fenxiao_id`) USING BTREE,
  INDEX `IDX_fenxiao_audit_time`(`audit_time`) USING BTREE,
  INDEX `IDX_fenxiao_create_time`(`create_time`) USING BTREE,
  INDEX `IDX_fenxiao_grand_parent`(`grand_parent`) USING BTREE,
  INDEX `IDX_fenxiao_level_id`(`level_id`) USING BTREE,
  INDEX `IDX_fenxiao_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_fenxiao_parent`(`parent`) USING BTREE,
  INDEX `IDX_fenxiao_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_account
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_account`;
CREATE TABLE `fenxiao_account`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账单编号',
  `fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销商ID',
  `fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '费用',
  `type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '类型（withdraw提现 order订单结算）',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_account
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_apply
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_apply`;
CREATE TABLE `fenxiao_apply`  (
  `apply_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分销商店铺名',
  `parent` int(11) NOT NULL DEFAULT 0 COMMENT '上级分销商ID',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员ID',
  `mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '联系电话',
  `nickname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户头像',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请等级',
  `level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `order_complete_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单完成-消费金额',
  `order_complete_num` int(10) NOT NULL DEFAULT 0 COMMENT '订单完成-消费次数',
  `reg_time` int(11) NOT NULL DEFAULT 0 COMMENT '注册时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `update_time` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '申请状态（1申请中  2通过 -1拒绝）',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_apply
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_goods
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_goods`;
CREATE TABLE `fenxiao_goods`  (
  `fenxiao_goods_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `one_rate` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '一级佣金',
  `two_rate` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '二级佣金',
  `three_rate` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '三级佣金',
  `state` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与',
  PRIMARY KEY (`fenxiao_goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_goods
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_goods_collect
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_goods_collect`;
CREATE TABLE `fenxiao_goods_collect`  (
  `collect_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销商id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuid',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '收藏时间',
  `site_id` int(10) NOT NULL DEFAULT 0 COMMENT '站点id',
  PRIMARY KEY (`collect_id`) USING BTREE,
  INDEX `IDX_fenxiao_goods_collect_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_fenxiao_goods_collect_sku_id`(`sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商关注商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_goods_collect
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_goods_sku
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_goods_sku`;
CREATE TABLE `fenxiao_goods_sku`  (
  `goods_sku_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销等级ID',
  `one_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金比例',
  `one_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金金额',
  `two_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金比例',
  `two_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金金额',
  `three_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三级佣金比例',
  `three_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三级佣金金额',
  PRIMARY KEY (`goods_sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商品sku表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_goods_sku
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_level
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_level`;
CREATE TABLE `fenxiao_level`  (
  `level_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `level_num` int(11) NOT NULL DEFAULT 0 COMMENT '等级权重',
  `level_name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `one_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金比例',
  `two_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金比例',
  `three_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三级佣金比例',
  `upgrade_type` tinyint(3) NOT NULL DEFAULT 0 COMMENT '升级方式（0满足任意条件  1满足全部条件）',
  `fenxiao_order_num` int(11) NOT NULL DEFAULT 0 COMMENT '订单总数',
  `fenxiao_order_meney` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '订单总金额',
  `one_fenxiao_order_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级分销订单总数',
  `one_fenxiao_order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级分销订单总额',
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '自购订单总数',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '自购订单总额',
  `child_num` int(11) NOT NULL DEFAULT 0 COMMENT '下线人数',
  `child_fenxiao_num` int(11) NOT NULL DEFAULT 0 COMMENT '下线分销商人数',
  `one_child_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级下线人数',
  `one_child_fenxiao_num` int(11) NOT NULL DEFAULT 0 COMMENT '一级下线分销商',
  `status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '状态（0关闭 1启用）',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `is_default` int(1) NOT NULL DEFAULT 0 COMMENT '是否是默认等级',
  PRIMARY KEY (`level_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销等级配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_level
-- ----------------------------

-- ----------------------------
-- Table structure for fenxiao_money
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_money`;
CREATE TABLE `fenxiao_money`  (
  `fenxiao_order_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单ID',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单项ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品卖价',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '商品数量',
  `real_goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人ID',
  `member_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人名称',
  `member_mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人电话',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人详细地址',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总佣金',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销总比率',
  `one_fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '一级分销商ID',
  `one_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级分销比例',
  `one_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级分销佣金',
  `one_fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '一级分销商名',
  `two_fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '二级分销商ID',
  `two_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '二级分销比例',
  `two_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '二级分销佣金',
  `two_fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '二级分销商名',
  `three_fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '三级分销商ID',
  `three_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三级分销比例',
  `three_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三级分销佣金',
  `three_fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '三级分销商名',
  `is_settlement` tinyint(3) NOT NULL DEFAULT 0 COMMENT '是否结算',
  `is_refund` tinyint(3) NOT NULL DEFAULT 0 COMMENT '是否退款',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `member_level` int(11) NOT NULL DEFAULT 0 COMMENT '用户等级',
  `member_level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员等级名称',
  `one_member_level` int(11) NULL DEFAULT 0,
  `one_member_level_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `one_member_id` int(11) NULL DEFAULT 0,
  `one_rate_point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '消费积分比例',
  `one_commission_point` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一级消费积分',
  `two_member_id` int(11) NULL DEFAULT 0 COMMENT '上级member_id',
  `staff_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '员工比例',
  `staff_member_id` int(11) NULL DEFAULT 0 COMMENT '员工member_id',
  `staff_commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '员工分销佣金',
  `site2_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台分商家比例',
  `site2_id` int(11) NULL DEFAULT 0 COMMENT '商家ID',
  `site2_commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商家分销佣金',
  `city_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商会比例',
  `city_id` int(11) NULL DEFAULT 0 COMMENT '商会ID',
  `city_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '商会名称',
  `city_commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商会分销佣金',
  `site_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商家比例',
  `fenxiao_site_id` int(11) NULL DEFAULT 0 COMMENT '商家ID',
  `site_commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商家分销佣金',
  `pt_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台比例',
  `pt_commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台分销佣金',
  `two_member_level` int(11) NULL DEFAULT 0 COMMENT '上级会员等级',
  `two_member_level_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  PRIMARY KEY (`fenxiao_order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '返余额，积分' ROW_FORMAT = Dynamic;

