-- ----------------------------
-- Table structure for fenxiao_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `fenxiao_withdraw`;
CREATE TABLE `fenxiao_withdraw`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `withdraw_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现流水号',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销商id',
  `fenxiao_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `withdraw_type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现类型（weixin-微信 alipay-支付宝 balance-余额 bank银行卡）',
  `bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现银行名称',
  `account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现银行账号',
  `realname` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现账户姓名',
  `mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现金额',
  `withdraw_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现手续费率',
  `withdraw_rate_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现手续费金额',
  `real_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际到账金额',
  `status` smallint(6) NOT NULL DEFAULT 1 COMMENT '当前状态 1待审核 2已审核 -1 已拒绝',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请日期',
  `payment_time` int(11) NOT NULL DEFAULT 0 COMMENT '到账日期',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改日期',
  `transfer_type` int(11) NOT NULL DEFAULT 1 COMMENT '转账方式   1 线下转账  2线上转账',
  `transfer_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转账银行名称',
  `transfer_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转账备注',
  `transfer_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转账流水号',
  `transfer_account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转账银行账号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员余额提现记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fenxiao_withdraw
-- ----------------------------

-- ----------------------------
-- Table structure for goods
-- ----------------------------
DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods`  (
  `goods_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `goods_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品种类1.实物商品2.虚拟商品3.卡券商品',
  `goods_class_name` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品种类',
  `goods_attr_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品类型id',
  `goods_attr_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属店铺名称',
  `goods_image` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品主图路径',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属分站id',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  `brand_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属品牌名称',
  `goods_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品详情',
  `is_own` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `goods_state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '商品状态（1.正常0下架）',
  `category_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品分类id,逗号隔开',
  `category_json` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类json字符串',
  `verify_state` int(11) NOT NULL DEFAULT 1 COMMENT '审核状态（1 已审核 0 待审核 10 违规下架 -1 审核中 -2 审核失败）',
  `verify_state_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品违规或审核失败说明',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格（取第一个sku）',
  `market_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '划线价格（取第一个sku）',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价（取第一个sku）',
  `goods_stock` int(11) NOT NULL DEFAULT 0 COMMENT '商品库存（总和）',
  `goods_stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT '库存预警',
  `is_virtual` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否虚拟类商品（0实物1.虚拟）',
  `virtual_indate` int(11) NOT NULL DEFAULT 1 COMMENT '虚拟商品有效期',
  `is_free_shipping` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否免邮',
  `shipping_template` int(11) NOT NULL DEFAULT 0 COMMENT '指定运费模板',
  `goods_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品规格格式',
  `goods_attr_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品属性格式',
  `is_delete` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已经删除',
  `introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '促销语',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键词',
  `unit` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '权重（平台排序 ）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `video_url` varchar(555) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '视频',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分佣比率(按照分类)',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `goods_shop_category_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店内分类id,逗号隔开',
  `evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '评价数',
  `evaluate_shaitu` int(11) NOT NULL DEFAULT 0 COMMENT '评价晒图数',
  `evaluate_shipin` int(11) NOT NULL DEFAULT 0 COMMENT '评价视频数',
  `evaluate_zhuiping` int(11) NOT NULL DEFAULT 0 COMMENT '评价追评数',
  `evaluate_haoping` int(11) NOT NULL DEFAULT 0 COMMENT '评价好评数',
  `evaluate_zhongping` int(11) NOT NULL DEFAULT 0 COMMENT '评价中评数',
  `evaluate_chaping` int(11) NOT NULL DEFAULT 0 COMMENT '评价差评数',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '参与分销（0不参与 1参与）',
  `fenxiao_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '分销佣金类型（1默认  2自行设置）',
  `supplier_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `max_buy` int(11) NOT NULL DEFAULT 0 COMMENT '限购',
  `min_buy` int(11) NOT NULL DEFAULT 0 COMMENT '起购数',
  `timer_on` int(11) NOT NULL DEFAULT 0 COMMENT '定时上架',
  `timer_off` int(11) NOT NULL DEFAULT 0 COMMENT '定时下架',
  `supply_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联供应商商品id',
  `discount_config` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优惠设置（0默认 1自定义）',
  `discount_method` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠方式（discount打折 manjian 满减 fixed_price 指定价格）',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `promotion_addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '当前参与的营销活动，逗号分隔（限时折扣、团购、拼团、秒杀、专题活动）',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品分类',
  `recommend_way` int(11) NOT NULL DEFAULT 0 COMMENT '推荐方式，1：新品，2：精品，3；推荐',
  `is_consume_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与会员等级折扣',
  `member_price` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员价',
  `goods_type` tinyint(4) NULL DEFAULT 0 COMMENT '商品类型:0=普通商品,1=福利品',
  `point` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '积分商品所属积分',
  `is_admin` tinyint(4) NULL DEFAULT 0 COMMENT '是否总后台添加商品',
  PRIMARY KEY (`goods_id`) USING BTREE,
  INDEX `IDX_goods_brand_id`(`brand_id`) USING BTREE,
  INDEX `IDX_goods_category_id`(`category_id`) USING BTREE,
  INDEX `IDX_goods_goods_class`(`goods_class`) USING BTREE,
  INDEX `IDX_goods_is_delete`(`is_delete`) USING BTREE,
  INDEX `IDX_goods_is_own_shop`(`is_own`) USING BTREE,
  INDEX `IDX_goods_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_goods_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_goods_sort`(`sort`) USING BTREE,
  INDEX `IDX_goods_website_id`(`website_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 340 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods
-- ----------------------------

-- ----------------------------
-- Table structure for goods_attr_class
-- ----------------------------
DROP TABLE IF EXISTS `goods_attr_class`;
CREATE TABLE `goods_attr_class`  (
  `class_id` int(11) NOT NULL AUTO_INCREMENT,
  `class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号',
  PRIMARY KEY (`class_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = ' 商品类型' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_attr_class
-- ----------------------------

-- ----------------------------
-- Table structure for goods_attr_class_brand
-- ----------------------------
DROP TABLE IF EXISTS `goods_attr_class_brand`;
CREATE TABLE `goods_attr_class_brand`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品类型id',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品类型品牌关联' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_attr_class_brand
-- ----------------------------

-- ----------------------------
-- Table structure for goods_attr_index
-- ----------------------------
DROP TABLE IF EXISTS `goods_attr_index`;
CREATE TABLE `goods_attr_index`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuid',
  `attr_id` int(11) NOT NULL DEFAULT 0 COMMENT '属性id',
  `attr_value_id` int(11) NOT NULL DEFAULT 0 COMMENT '属性值id',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '属性类型',
  `app_module` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'shop' COMMENT '模块端口',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品属性关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_attr_index
-- ----------------------------

-- ----------------------------
-- Table structure for goods_attribute
-- ----------------------------
DROP TABLE IF EXISTS `goods_attribute`;
CREATE TABLE `goods_attribute`  (
  `attr_id` int(11) NOT NULL AUTO_INCREMENT,
  `attr_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '属性名称',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品类型id',
  `attr_class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '属性排序号',
  `is_query` int(11) NOT NULL DEFAULT 0 COMMENT '是否参与筛选',
  `is_spec` int(11) NOT NULL DEFAULT 0 COMMENT '是否是规格属性',
  `attr_value_list` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '属性值列表（\',\'隔开注意键值对）',
  `attr_value_format` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '属性值格式json',
  `attr_type` int(11) NOT NULL DEFAULT 0 COMMENT '属性类型  （1.单选 2.多选3. 输入 注意输入不参与筛选）',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  PRIMARY KEY (`attr_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品属性' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_attribute
-- ----------------------------

-- ----------------------------
-- Table structure for goods_attribute_value
-- ----------------------------
DROP TABLE IF EXISTS `goods_attribute_value`;
CREATE TABLE `goods_attribute_value`  (
  `attr_value_id` int(11) NOT NULL AUTO_INCREMENT,
  `attr_value_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '属性值名称',
  `attr_id` int(11) NOT NULL DEFAULT 0 COMMENT '属性id',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '类型id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`attr_value_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品属性值表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_attribute_value
-- ----------------------------

-- ----------------------------
-- Table structure for goods_brand
-- ----------------------------
DROP TABLE IF EXISTS `goods_brand`;
CREATE TABLE `goods_brand`  (
  `brand_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '索引ID',
  `brand_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '品牌名称',
  `brand_initial` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '品牌首字母',
  `image_url` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `is_recommend` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否推荐',
  PRIMARY KEY (`brand_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品品牌表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_brand
-- ----------------------------

-- ----------------------------
-- Table structure for goods_browse
-- ----------------------------
DROP TABLE IF EXISTS `goods_browse`;
CREATE TABLE `goods_browse`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '浏览人',
  `browse_time` int(11) NOT NULL DEFAULT 0 COMMENT '浏览时间',
  `site_id` int(10) NOT NULL DEFAULT 0 COMMENT '站点id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_goods_browse_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_goods_browse_sku_id`(`sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品浏览历史' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_browse
-- ----------------------------

-- ----------------------------
-- Table structure for goods_cart
-- ----------------------------
DROP TABLE IF EXISTS `goods_cart`;
CREATE TABLE `goods_cart`  (
  `cart_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '数量',
  `goods_type` tinyint(4) NULL DEFAULT 0 COMMENT '商品类型:0=普通商品,1=福利品,2=全国包邮',
  PRIMARY KEY (`cart_id`) USING BTREE,
  INDEX `IDX_goods_cart_member_id`(`member_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = ' 购物车' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_cart
-- ----------------------------

-- ----------------------------
-- Table structure for goods_category
-- ----------------------------
DROP TABLE IF EXISTS `goods_category`;
CREATE TABLE `goods_category`  (
  `category_id` int(11) NOT NULL AUTO_INCREMENT,
  `category_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `short_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '简称',
  `pid` int(11) NOT NULL DEFAULT 0 COMMENT '分类上级',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '层级',
  `is_show` int(11) NOT NULL DEFAULT 0 COMMENT '是否显示（0显示  -1不显示）',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类图片',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类页面关键字',
  `description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类介绍',
  `attr_class_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联商品类型id',
  `attr_class_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关联商品类型名称',
  `category_id_1` int(11) NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `category_id_2` int(11) NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `category_id_3` int(11) NOT NULL DEFAULT 0 COMMENT '三级分类id',
  `category_full_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '组装名称',
  `image_adv` varchar(510) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类广告图',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金比率%',
  `supply_commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商的佣金比率',
  `is_index` tinyint(4) NULL DEFAULT 0 COMMENT '是否推荐首页:1=是,0=否',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  PRIMARY KEY (`category_id`) USING BTREE,
  INDEX `pid_level`(`pid`, `level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = ' 商品分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_category
-- ----------------------------

-- ----------------------------
-- Table structure for goods_collect
-- ----------------------------
DROP TABLE IF EXISTS `goods_collect`;
CREATE TABLE `goods_collect`  (
  `collect_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuid',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品分类id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '收藏时间',
  `site_id` int(10) NOT NULL DEFAULT 0 COMMENT '站点id',
  PRIMARY KEY (`collect_id`) USING BTREE,
  INDEX `IDX_goods_collect_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_goods_collect_sku_id`(`sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_collect
-- ----------------------------

-- ----------------------------
-- Table structure for goods_evaluate
-- ----------------------------
DROP TABLE IF EXISTS `goods_evaluate`;
CREATE TABLE `goods_evaluate`  (
  `evaluate_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单ID',
  `order_no` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单编号',
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单项ID',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价内容',
  `images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价图片',
  `explain_first` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '解释内容',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '评价人id',
  `member_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价人名称',
  `member_headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价人头像',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0表示不是 1表示是匿名评价',
  `scores` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-5分',
  `again_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追加评价内容',
  `again_images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追评评价图片',
  `again_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追加解释内容',
  `explain_type` int(11) NOT NULL DEFAULT 0 COMMENT '1好评2中评3差评',
  `is_show` int(1) NOT NULL DEFAULT 1 COMMENT '1显示 0隐藏',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '评价时间',
  `again_time` int(11) NOT NULL DEFAULT 0 COMMENT '追加评价时间',
  `shop_desccredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '描述分值',
  `shop_servicecredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '服务分值',
  `shop_deliverycredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '配送分值',
  `is_audit` int(11) NOT NULL DEFAULT 1 COMMENT '审核状态：0 未审核 1 审核通过，-1 审核拒绝',
  PRIMARY KEY (`evaluate_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品评价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_evaluate
-- ----------------------------

-- ----------------------------
-- Table structure for goods_export
-- ----------------------------
DROP TABLE IF EXISTS `goods_export`;
CREATE TABLE `goods_export`  (
  `export_id` int(11) NOT NULL AUTO_INCREMENT,
  `condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '条件  json',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '导出状态  0 正在导出 1 已导出  2 已删除',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '导出时间',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '导出文件的物理路径',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  PRIMARY KEY (`export_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品导出记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_export
-- ----------------------------

-- ----------------------------
-- Table structure for goods_grab
-- ----------------------------
DROP TABLE IF EXISTS `goods_grab`;
CREATE TABLE `goods_grab`  (
  `grab_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `is_virtual` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商品类型（0实物1.虚拟）',
  `category_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品分类',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品分类名称',
  `total_num` int(11) NOT NULL DEFAULT 0 COMMENT '采集数',
  `success_num` int(11) NOT NULL DEFAULT 0 COMMENT '成功数',
  `error_num` int(11) NOT NULL DEFAULT 0 COMMENT '失败数',
  `create_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`grab_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品采集' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_grab
-- ----------------------------

-- ----------------------------
-- Table structure for goods_grab_detail
-- ----------------------------
DROP TABLE IF EXISTS `goods_grab_detail`;
CREATE TABLE `goods_grab_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `grab_id` int(11) NOT NULL DEFAULT 0,
  `url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '采集地址',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '采集平台',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '采集平台名称',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（1成功  2失败）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '采集明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_grab_detail
-- ----------------------------

-- ----------------------------
-- Table structure for goods_shop_category
-- ----------------------------
DROP TABLE IF EXISTS `goods_shop_category`;
CREATE TABLE `goods_shop_category`  (
  `category_id` int(11) NOT NULL AUTO_INCREMENT,
  `category_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `short_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '简称',
  `pid` int(11) NOT NULL DEFAULT 0 COMMENT '分类上级',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '层级',
  `is_show` int(11) NOT NULL DEFAULT 0 COMMENT '是否显示',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类图片',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类页面关键字',
  `description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类介绍',
  `category_id_1` int(11) NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `category_id_2` int(11) NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `category_full_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '组装名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = ' 商品店内分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_shop_category
-- ----------------------------

-- ----------------------------
-- Table structure for goods_sku
-- ----------------------------
DROP TABLE IF EXISTS `goods_sku`;
CREATE TABLE `goods_sku`  (
  `sku_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '商品sku_id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku名称',
  `sku_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku编码',
  `sku_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'sku规格格式',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku单价',
  `market_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku划线价',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku成本价',
  `discount_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku折扣价（默认等于单价）',
  `promotion_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '活动类型1.限时折扣',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku库存',
  `weight` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '重量（单位g）',
  `volume` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '体积（单位立方米）',
  `click_num` int(11) NOT NULL DEFAULT 0 COMMENT '点击量',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `collect_num` int(11) NOT NULL DEFAULT 0 COMMENT '收藏量',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku主图',
  `sku_images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku图片',
  `goods_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品种类1.实物商品2.虚拟商品3.卡券商品',
  `goods_class_name` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品种类',
  `goods_attr_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品类型id',
  `goods_attr_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属店铺名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属分站id',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  `brand_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属品牌名称',
  `goods_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品详情',
  `is_own` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `goods_state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '商品状态（1.正常0下架）',
  `verify_state` int(11) NOT NULL DEFAULT 1 COMMENT '审核状态（1 已审核 0 待审核 10 违规下架 -1 审核中 -2 审核失败）',
  `verify_state_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品违规或审核失败说明',
  `goods_stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT '库存预警',
  `is_virtual` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否虚拟类商品（0实物1.虚拟）',
  `virtual_indate` int(11) NOT NULL DEFAULT 1 COMMENT '虚拟商品有效期',
  `is_free_shipping` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否免邮',
  `shipping_template` int(11) NOT NULL DEFAULT 0 COMMENT '指定运费模板',
  `goods_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品规格格式',
  `goods_attr_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品属性格式',
  `is_delete` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已经删除',
  `introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '促销语',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键词',
  `unit` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `video_url` varchar(555) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '视频',
  `goods_shop_category_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店内分类id,逗号隔开',
  `evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '评价数',
  `evaluate_shaitu` int(11) NOT NULL DEFAULT 0 COMMENT '晒图评价数',
  `evaluate_shipin` int(11) NOT NULL DEFAULT 0 COMMENT '视频评价数',
  `evaluate_zhuiping` int(11) NOT NULL DEFAULT 0 COMMENT '追评数',
  `evaluate_haoping` int(11) NOT NULL DEFAULT 0 COMMENT '好评数',
  `evaluate_zhongping` int(11) NOT NULL DEFAULT 0 COMMENT '中评数',
  `evaluate_chaping` int(11) NOT NULL DEFAULT 0 COMMENT '差评数',
  `spec_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '规格名称',
  `supplier_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `max_buy` int(11) NOT NULL DEFAULT 0 COMMENT '限购',
  `min_buy` int(11) NOT NULL DEFAULT 0,
  `supply_goods_id` int(11) NOT NULL DEFAULT 0,
  `supply_sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联供应商sku_id',
  `fenxiao_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销计算价格',
  `stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT 'sku库存预警',
  `sale_sort` int(11) NOT NULL DEFAULT 0 COMMENT '销量排序字段 占位用',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `discount_config` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优惠设置（0默认 1自定义）',
  `discount_method` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠方式（discount打折 manjian 满减 fixed_price 指定价格）',
  `recommend_way` int(11) NOT NULL DEFAULT 0 COMMENT '推荐方式，1：新品，2：精品，3；推荐',
  `is_consume_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与会员等级折扣',
  `member_price` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员价',
  `point` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '积分商品所属积分',
  PRIMARY KEY (`sku_id`) USING BTREE,
  INDEX `IDX_goods_brand_id`(`brand_id`) USING BTREE,
  INDEX `IDX_goods_goods_class`(`goods_class`) USING BTREE,
  INDEX `IDX_goods_is_delete`(`is_delete`) USING BTREE,
  INDEX `IDX_goods_is_own_shop`(`is_own`) USING BTREE,
  INDEX `IDX_goods_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_goods_sort`(`sort`) USING BTREE,
  INDEX `IDX_goods_website_id`(`website_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 351 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_sku
-- ----------------------------

-- ----------------------------
-- Table structure for goods_virtual
-- ----------------------------
DROP TABLE IF EXISTS `goods_virtual`;
CREATE TABLE `goods_virtual`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '虚拟商品编码',
  `is_veirfy` int(11) NOT NULL DEFAULT 0 COMMENT '是否已经核销',
  `verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属人',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '虚拟商品图片',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户虚拟商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of goods_virtual
-- ----------------------------

-- ----------------------------
-- Table structure for group
-- ----------------------------
DROP TABLE IF EXISTS `group`;
CREATE TABLE `group`  (
  `group_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id（店铺，分站）,总平台端为0',
  `app_module` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '使用端口',
  `group_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户组名称',
  `group_status` int(11) NOT NULL DEFAULT 1 COMMENT '用户组状态',
  `is_system` int(1) NOT NULL DEFAULT 0 COMMENT '是否是系统用户组',
  `menu_array` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '系统菜单权限组，用，隔开',
  `desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`group_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户组表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of group
-- ----------------------------

-- ----------------------------
-- Table structure for help
-- ----------------------------
DROP TABLE IF EXISTS `help`;
CREATE TABLE `help`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_module` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '应用模块',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '帮助主题',
  `link_address` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '链接地址',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '帮助内容',
  `class_id` int(11) NOT NULL DEFAULT 0 COMMENT '帮助类型id',
  `class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '帮助类型名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '帮助文章表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of help
-- ----------------------------

-- ----------------------------
-- Table structure for help_class
-- ----------------------------
DROP TABLE IF EXISTS `help_class`;
CREATE TABLE `help_class`  (
  `class_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `app_module` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '应用模块',
  `class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '帮助类型名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`class_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '帮助类型' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of help_class
-- ----------------------------

-- ----------------------------
-- Table structure for inform
-- ----------------------------
DROP TABLE IF EXISTS `inform`;
CREATE TABLE `inform`  (
  `inform_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku名称',
  `subject_id` int(11) NOT NULL DEFAULT 0 COMMENT '举报主题id',
  `subject_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报主题名称',
  `content` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报内容',
  `inform_pic` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '内容图片（最多3张）',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `state` int(11) NOT NULL DEFAULT 0 COMMENT '处理状态',
  `deal_type` int(11) NOT NULL DEFAULT 1 COMMENT '处理类型1.有效2.无效3.恶意',
  `deal_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '有效' COMMENT '处理类型名称',
  `deal_content` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '处理信息',
  `deal_time` int(11) NOT NULL DEFAULT 0 COMMENT '处理时间',
  PRIMARY KEY (`inform_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '举报表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of inform
-- ----------------------------

-- ----------------------------
-- Table structure for inform_subject
-- ----------------------------
DROP TABLE IF EXISTS `inform_subject`;
CREATE TABLE `inform_subject`  (
  `subject_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '举报主题id',
  `subject_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报主题内容',
  `subject_type_id` int(11) NOT NULL DEFAULT 0 COMMENT '举报类型id',
  `subject_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报类型名称 ',
  `subject_state` tinyint(11) NOT NULL DEFAULT 1 COMMENT '举报主题状态(1使用/0关闭)',
  PRIMARY KEY (`subject_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '举报主题表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of inform_subject
-- ----------------------------

-- ----------------------------
-- Table structure for inform_subject_type
-- ----------------------------
DROP TABLE IF EXISTS `inform_subject_type`;
CREATE TABLE `inform_subject_type`  (
  `type_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '举报类型id',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报类型名称 ',
  `type_desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '举报类型描述',
  `type_state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '举报类型状态(1有效/0关闭)',
  PRIMARY KEY (`type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '举报类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of inform_subject_type
-- ----------------------------

-- ----------------------------
-- Table structure for link
-- ----------------------------
DROP TABLE IF EXISTS `link`;
CREATE TABLE `link`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `addon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标识',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '中文名称',
  `parent` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '父级',
  `sort` int(11) NOT NULL COMMENT '排序',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '级别',
  `web_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'pc端页面跳转路径',
  `wap_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'wap端跳转路径',
  `icon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图标',
  `support_diy_view` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支持的自定义页面（为空表示公共组件都支持）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_nc_link`(`addon_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 126 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '链接入口' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of link
-- ----------------------------

-- ----------------------------
-- Table structure for local
-- ----------------------------
DROP TABLE IF EXISTS `local`;
CREATE TABLE `local`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'default' COMMENT '配送方式  default 商家自配送  other 第三方配送',
  `area_type` int(11) NOT NULL DEFAULT 1 COMMENT '配送区域',
  `local_area_json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '区域配送设置',
  `time_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '订单达是否开启 0 关闭 1 开启',
  `time_type` int(11) NOT NULL DEFAULT 0 COMMENT '时间选取类型 0 全天  1 自定义',
  `time_week` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营业时间  周一 周二.......',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日的起始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日的营业结束时间',
  `update_time` int(11) NOT NULL DEFAULT 0,
  `is_open_step` int(11) NOT NULL DEFAULT 0 COMMENT '是否启用阶梯价(适用于行政区域)',
  `start_distance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '多少距离以内,...',
  `start_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '多少距离以内,多少钱',
  `continued_distance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每增加多少距离',
  `continued_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每增加多少距离,运费增加',
  `start_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '起送价',
  `delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '配送费',
  `area_array` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地域集合',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '本地配送设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of local
-- ----------------------------

-- ----------------------------
-- Table structure for local_delivery_package
-- ----------------------------
DROP TABLE IF EXISTS `local_delivery_package`;
CREATE TABLE `local_delivery_package`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_goods_id_array` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单项商品组合列表',
  `goods_id_array` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品组合列表',
  `package_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '包裹名称  （包裹- 1 包裹 - 2）',
  `delivery_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'default' COMMENT '发货方式 default 商家自配送 other 第三方配送',
  `delivery_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '运单编号',
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名称',
  `deliverer` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送员',
  `deliverer_mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外卖配送物流信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of local_delivery_package
-- ----------------------------

-- ----------------------------
-- Table structure for member
-- ----------------------------
DROP TABLE IF EXISTS `member`;
CREATE TABLE `member`  (
  `member_id` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `source_member` int(11) NOT NULL DEFAULT 0 COMMENT '推荐人',
  `fenxiao_id` int(11) NOT NULL DEFAULT 0 COMMENT '分销商（分销有效）',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是分销商',
  `username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户密码（MD5）',
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '用户状态  用户状态默认为1',
  `headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户头像',
  `member_level` int(11) NOT NULL DEFAULT 0 COMMENT '用户等级',
  `member_level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员等级名称',
  `member_label` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT ',' COMMENT '用户标签',
  `member_label_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员标签名称',
  `qq` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'qq号',
  `qq_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'qq互联id',
  `wx_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信用户openid',
  `weapp_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信小程序openid',
  `wx_unionid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信unionid',
  `ali_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付宝账户id',
  `baidu_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '百度账户id',
  `toutiao_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '头条账号',
  `douyin_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '抖音小程序openid',
  `login_ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '当前登录ip',
  `login_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'h5' COMMENT '当前登录的操作终端类型',
  `login_time` int(11) NOT NULL DEFAULT 0 COMMENT '当前登录时间',
  `last_login_ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上次登录ip',
  `last_login_type` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'h5' COMMENT '上次登录的操作终端类型',
  `last_login_time` int(11) NOT NULL DEFAULT 0 COMMENT '上次登录时间',
  `login_num` int(11) NOT NULL DEFAULT 0 COMMENT '登录次数',
  `realname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  `sex` smallint(6) NOT NULL DEFAULT 0 COMMENT '性别 0保密 1男 2女',
  `location` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定位地址',
  `birthday` int(11) NOT NULL DEFAULT 0 COMMENT '出生日期',
  `reg_time` int(11) NOT NULL DEFAULT 0 COMMENT '注册时间',
  `point` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '积分',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `growth` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成长值',
  `balance_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '现金余额(可提现)',
  `account5` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户5',
  `is_auth` int(11) NOT NULL DEFAULT 0 COMMENT '是否认证',
  `sign_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后一次签到时间',
  `sign_days_series` int(11) NOT NULL DEFAULT 0 COMMENT '持续签到天数',
  `pay_password` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易密码',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款后-消费金额',
  `order_complete_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单完成-消费金额',
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '付款后-消费次数',
  `order_complete_num` int(11) NOT NULL DEFAULT 0 COMMENT '订单完成-消费次数',
  `balance_withdraw_apply` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现中余额',
  `balance_withdraw` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已提现余额',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0正常  1已删除',
  `login_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '登陆类型名称',
  `is_edit_username` int(1) NOT NULL DEFAULT 1 COMMENT '是否能修改username   0-不可修改  1-可以修改',
  `member_level_time` int(11) NULL DEFAULT 0 COMMENT '成为会员时间',
  `shop_sign_days` int(11) NULL DEFAULT 0 COMMENT '商家签到已经签到天数',
  `shop_sign_round` int(11) NULL DEFAULT 1 COMMENT '商家签到第几轮（每一轮按照规则的天数）',
  `shop_sign_qrcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '商家签到二维码',
  `wxqy_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '企业端登录openid',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `site_id` int(11) NULL DEFAULT 0 COMMENT '商家(废弃)',
  `staff_member_id` int(11) NULL DEFAULT 0 COMMENT '员工memberID',
  PRIMARY KEY (`member_id`) USING BTREE,
  INDEX `IDX_member_weapp_openid`(`weapp_openid`) USING BTREE,
  INDEX `IDX_sys_user_user_email`(`email`) USING BTREE,
  INDEX `IDX_sys_user_user_name`(`username`) USING BTREE,
  INDEX `IDX_sys_user_user_password`(`password`) USING BTREE,
  INDEX `IDX_sys_user_user_tel`(`mobile`) USING BTREE,
  INDEX `IDX_sys_user_wx_openid`(`wx_openid`) USING BTREE,
  INDEX `IDX_sys_user_wx_unionid`(`wx_unionid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member
-- ----------------------------

-- ----------------------------
-- Table structure for member_account
-- ----------------------------
DROP TABLE IF EXISTS `member_account`;
CREATE TABLE `member_account`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户id',
  `account_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'point' COMMENT '账户类型',
  `account_data` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户数据',
  `from_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '来源类型',
  `type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '来源类型名称',
  `type_tag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关联关键字',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注信息',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `point_expire` tinyint(4) NOT NULL DEFAULT 0 COMMENT '积分到期状态:0=未到期,1=已到期',
  `point_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '积分来源:1=邀约奖励,2=下单奖励,3=积分消耗',
  `member_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '余额关联用户ID',
  `point_end_time` int(11) NULL DEFAULT 0 COMMENT '积分到期时间',
  `point_yu` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '剩余未消耗积分',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_member_account_account_type`(`account_type`) USING BTREE,
  INDEX `IDX_member_account_create_time`(`create_time`) USING BTREE,
  INDEX `IDX_member_account_from_type`(`from_type`) USING BTREE,
  INDEX `IDX_member_account_member_id`(`member_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 193 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '账户流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_account
-- ----------------------------

-- ----------------------------
-- Table structure for member_address
-- ----------------------------
DROP TABLE IF EXISTS `member_address`;
CREATE TABLE `member_address`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户姓名',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `telephone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地址信息',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址信息',
  `longitude` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `is_default` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否是默认地址',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '地址类型  1 普通地址  2 定位地址',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户地址管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_address
-- ----------------------------

-- ----------------------------
-- Table structure for member_auth
-- ----------------------------
DROP TABLE IF EXISTS `member_auth`;
CREATE TABLE `member_auth`  (
  `auth_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员ID',
  `member_username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员用户名',
  `auth_card_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '实名姓名',
  `auth_card_no` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '实名身份证',
  `auth_card_hand` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人手持身份证电子版',
  `auth_card_front` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证正面',
  `auth_card_back` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证反面',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '审核状态0待审核1.已审核-1已拒绝',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '审核意见',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核通过时间',
  PRIMARY KEY (`auth_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员实名认证表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_auth
-- ----------------------------

-- ----------------------------
-- Table structure for member_bank_account
-- ----------------------------
DROP TABLE IF EXISTS `member_bank_account`;
CREATE TABLE `member_bank_account`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL COMMENT '会员id',
  `realname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  `mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `withdraw_type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账户类型 alipay-支付宝  bank银行卡 wechatpay 微信',
  `branch_bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行名称',
  `bank_account` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行账号',
  `is_default` int(11) NOT NULL DEFAULT 0 COMMENT '是否默认账号',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '创建日期',
  `modify_time` int(11) NULL DEFAULT 0 COMMENT '修改日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员提现账号' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_bank_account
-- ----------------------------

-- ----------------------------
-- Table structure for member_cancel
-- ----------------------------
DROP TABLE IF EXISTS `member_cancel`;
CREATE TABLE `member_cancel`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员账号',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员昵称',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态',
  `audit_uid` int(11) NOT NULL DEFAULT 0 COMMENT '审核人UID',
  `audit_username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '审核人账号',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '审核拒绝原因',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请注销时间',
  `member_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '会员信息',
  `fenxiao_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '分销信息',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员注销表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_cancel
-- ----------------------------

-- ----------------------------
-- Table structure for member_cluster
-- ----------------------------
DROP TABLE IF EXISTS `member_cluster`;
CREATE TABLE `member_cluster`  (
  `cluster_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '会员群体ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `cluster_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '群体名称',
  `rule_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则json',
  `member_num` int(11) NOT NULL DEFAULT 0 COMMENT '群体内会员 数量',
  `member_ids` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '群体内会员ID',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`cluster_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员群体表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_cluster
-- ----------------------------

-- ----------------------------
-- Table structure for member_collection
-- ----------------------------
DROP TABLE IF EXISTS `member_collection`;
CREATE TABLE `member_collection`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NULL DEFAULT 0 COMMENT '用户',
  `category_id` int(11) NULL DEFAULT 0 COMMENT '关注者',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '类型:video_comment=视频评论',
  `create_time` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '视频点赞' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_collection
-- ----------------------------

-- ----------------------------
-- Table structure for member_import_log
-- ----------------------------
DROP TABLE IF EXISTS `member_import_log`;
CREATE TABLE `member_import_log`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `realname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  `wx_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信公众号openid',
  `weapp_openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '小程序openid',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '添加时间',
  `content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '内容',
  `record_id` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员导入记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_import_log
-- ----------------------------

-- ----------------------------
-- Table structure for member_import_record
-- ----------------------------
DROP TABLE IF EXISTS `member_import_record`;
CREATE TABLE `member_import_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `filename` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件名称',
  `path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '路径',
  `member_num` int(11) NULL DEFAULT 0 COMMENT '会员总数',
  `success_num` int(11) NULL DEFAULT 0 COMMENT '会员导入成功数量',
  `error_num` int(11) NULL DEFAULT 0 COMMENT '会员导入失败数量',
  `status_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '导入状态',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '导入时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员导入记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_import_record
-- ----------------------------

-- ----------------------------
-- Table structure for member_label
-- ----------------------------
DROP TABLE IF EXISTS `member_label`;
CREATE TABLE `member_label`  (
  `label_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '标签id',
  `label_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标签名称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`label_id`) USING BTREE,
  INDEX `IDX_nc_member_label_label_id`(`label_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员标签' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_label
-- ----------------------------

-- ----------------------------
-- Table structure for member_level
-- ----------------------------
DROP TABLE IF EXISTS `member_level`;
CREATE TABLE `member_level`  (
  `level_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '会员等级',
  `level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `sort` int(11) NOT NULL DEFAULT 1 COMMENT '等级排序列',
  `growth` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '所需成长值',
  `remark` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `is_default` int(11) NOT NULL DEFAULT 0 COMMENT '是否默认，0：否，1：是',
  `is_free_shipping` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否包邮',
  `consume_discount` decimal(10, 2) NOT NULL DEFAULT 100.00 COMMENT '消费折扣',
  `point_feedback` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '积分回馈倍率',
  `send_point` int(11) NOT NULL DEFAULT 0 COMMENT '赠送积分（等级礼包）',
  `send_balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '赠送红包（等级礼包）',
  `send_coupon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '赠送优惠券',
  `level_type` int(1) NOT NULL DEFAULT 0 COMMENT '等级类型 0免费卡 1付费卡',
  `charge_rule` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付费规则',
  `charge_type` int(1) NOT NULL COMMENT '付费类型 0付款 1充值',
  `bg_color` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '#333',
  `status` int(1) NOT NULL DEFAULT 1 COMMENT '状态 0已下架 1发售中',
  `is_recommend` int(1) NOT NULL DEFAULT 0 COMMENT '是否推荐',
  PRIMARY KEY (`level_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 AVG_ROW_LENGTH = 16384 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员等级' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_level
-- ----------------------------

-- ----------------------------
-- Table structure for member_level_order
-- ----------------------------
DROP TABLE IF EXISTS `member_level_order`;
CREATE TABLE `member_level_order`  (
  `order_id` int(11) NOT NULL AUTO_INCREMENT,
  `level_id` int(11) NULL DEFAULT 0,
  `level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '价格',
  `fan_point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '开通送积分',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单流水号',
  `status` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '支付状态（1未支付 2已支付）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '支付时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `member_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户头像',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开通会员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_level_order
-- ----------------------------

-- ----------------------------
-- Table structure for member_log
-- ----------------------------
DROP TABLE IF EXISTS `member_log`;
CREATE TABLE `member_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `action` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作行为插件',
  `action_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作行为名称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_log
-- ----------------------------

-- ----------------------------
-- Table structure for member_open_account
-- ----------------------------
DROP TABLE IF EXISTS `member_open_account`;
CREATE TABLE `member_open_account`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `member_id` int(10) NOT NULL DEFAULT 0,
  `realname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '个人姓名',
  `cert_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '个人证件号码',
  `cert_validity_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '个人证件有效期类型,1:长期有效 0:非长期有效',
  `cert_begin_date` date NULL DEFAULT NULL,
  `cert_end_date` date NULL DEFAULT NULL,
  `mobile_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `card_type` tinyint(1) NOT NULL DEFAULT 1,
  `card_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡户名',
  `card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号',
  `prov_id` int(10) NOT NULL DEFAULT 0,
  `area_id` int(10) NOT NULL DEFAULT 0,
  `huifu_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `login_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `login_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `req_seq_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户业务请求流水号',
  `req_date` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户业务请求日期',
  `apply_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户业务申请单号',
  `apply_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '审核状态,1审核中,2审核通过,3审核拒绝',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核意见',
  `token_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `createtime` int(10) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '个人开户' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_open_account
-- ----------------------------

-- ----------------------------
-- Table structure for member_recharge
-- ----------------------------
DROP TABLE IF EXISTS `member_recharge`;
CREATE TABLE `member_recharge`  (
  `recharge_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `recharge_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '套餐名称',
  `cover_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '封面',
  `face_value` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '面值',
  `buy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '购买金额',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分',
  `growth` int(11) NOT NULL DEFAULT 0 COMMENT '成长值',
  `coupon_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '优惠券ID',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '发放数量',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（1正常 2关闭）',
  PRIMARY KEY (`recharge_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员充值套餐' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_recharge
-- ----------------------------

-- ----------------------------
-- Table structure for member_recharge_card
-- ----------------------------
DROP TABLE IF EXISTS `member_recharge_card`;
CREATE TABLE `member_recharge_card`  (
  `card_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `recharge_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '套餐ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `card_account` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '充值卡号',
  `recharge_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '套餐名称',
  `cover_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '封面',
  `face_value` decimal(11, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '面值',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分',
  `growth` int(11) NOT NULL DEFAULT 0 COMMENT '成长值',
  `coupon_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券ID',
  `buy_price` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '购买金额',
  `member_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员ID',
  `member_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员头像',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员昵称',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单ID',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `from_type` tinyint(3) NOT NULL DEFAULT 0 COMMENT '获取来源',
  `use_status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '使用状态（1未使用 2已使用）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `use_time` int(11) NOT NULL DEFAULT 0 COMMENT '使用时间',
  PRIMARY KEY (`card_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '充值卡' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_recharge_card
-- ----------------------------

-- ----------------------------
-- Table structure for member_recharge_order
-- ----------------------------
DROP TABLE IF EXISTS `member_recharge_order`;
CREATE TABLE `member_recharge_order`  (
  `order_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `recharge_id` int(11) NOT NULL DEFAULT 0 COMMENT '套餐ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单流水号',
  `recharge_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '套餐名称',
  `cover_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '封面',
  `face_value` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '面值',
  `buy_price` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '价格',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分',
  `growth` int(11) NOT NULL DEFAULT 0 COMMENT '成长值',
  `coupon_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '优惠券ID',
  `price` decimal(11, 2) NOT NULL COMMENT '实付金额',
  `pay_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付方式',
  `pay_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付方式名称',
  `status` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '支付状态（1未支付 2已支付）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '支付时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `member_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户头像',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `order_from` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源名称',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '充值卡订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_recharge_order
-- ----------------------------

-- ----------------------------
-- Table structure for member_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `member_withdraw`;
CREATE TABLE `member_withdraw`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `withdraw_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现交易号',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员姓名',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `transfer_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '转账提现类型',
  `realname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  `apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现申请金额',
  `rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现手续费比率',
  `service_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现手续费',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现到账金额',
  `apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `payment_time` int(11) NOT NULL DEFAULT 0 COMMENT '转账时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态0待审核1.待转账2已转账 -1拒绝',
  `memo` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `refuse_reason` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由',
  `member_headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现状态名称',
  `transfer_type_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转账方式名称',
  `bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行名称',
  `account_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收款账号',
  `certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '凭证',
  `certificate_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '凭证说明',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员提现表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of member_withdraw
-- ----------------------------

-- ----------------------------
-- Table structure for menu
-- ----------------------------
DROP TABLE IF EXISTS `menu`;
CREATE TABLE `menu`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '菜单ID',
  `app_module` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'admin' COMMENT '应用模块',
  `addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属插件',
  `title` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '菜单标题',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '菜单关键字',
  `parent` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上级菜单',
  `level` int(11) NOT NULL DEFAULT 1 COMMENT '深度等级',
  `url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '链接地址',
  `is_show` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否展示',
  `sort` int(10) NOT NULL DEFAULT 0 COMMENT '排序（同级有效）',
  `desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `is_icon` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是矢量菜单图',
  `picture` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片(矢量图)',
  `picture_select` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片(矢量图)(选中)',
  `is_control` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否控制权限',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_menu_app_module`(`app_module`) USING BTREE,
  INDEX `IDX_menu_is_control`(`is_control`) USING BTREE,
  INDEX `IDX_menu_is_show`(`is_show`) USING BTREE,
  INDEX `IDX_menu_name`(`name`) USING BTREE,
  INDEX `IDX_menu_parent`(`parent`) USING BTREE,
  INDEX `IDX_menu_url`(`url`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10061 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '菜单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of menu
-- ----------------------------

-- ----------------------------
-- Table structure for message
-- ----------------------------
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '插件',
  `keywords` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键字',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '主题',
  `message_type` int(11) NOT NULL DEFAULT 1 COMMENT '消息类型 1 买家消息  2 卖家消息',
  `message_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配置参数',
  `email_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '是否启动邮箱',
  `email_title` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮箱标题',
  `email_content` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮箱发送内容',
  `sms_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '是否启动短信',
  `sms_addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发送短信插件',
  `sms_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '短信配置参数',
  `sms_content` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '短信内容',
  `wechat_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '微信公众号消息',
  `wechat_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配置参数',
  `weapp_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '微信小程序是否启动',
  `weapp_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信小程序配置参数',
  `aliapp_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '支付宝小程序是否启动',
  `aliapp_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付宝小程序配置参数',
  `support_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支持场景 如小程序  wep端',
  `sitemessage_is_open` int(11) NOT NULL DEFAULT 0 COMMENT '站内信是否启动',
  `sitemessage_json` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站内信配置参数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 AVG_ROW_LENGTH = 1585 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '消息管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of message
-- ----------------------------

