-- Records of message_email_records
-- ----------------------------

-- ----------------------------
-- Table structure for message_send_log
-- ----------------------------
DROP TABLE IF EXISTS `message_send_log`;
CREATE TABLE `message_send_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键字',
  `message_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '消息类型',
  `addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '执行插件',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '主题',
  `message_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '消息内容json',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `send_time` int(11) NOT NULL DEFAULT 0 COMMENT '发送时间',
  `send_log` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '发送结果',
  `is_success` int(11) NOT NULL DEFAULT 0 COMMENT '是否发送成功',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '消息发送日志' ROW_FORMAT = Dynamic;

