  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `open_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '接收者账号',
