-- ----------------------------
-- Table structure for notes
-- ----------------------------
DROP TABLE IF EXISTS `notes`;
CREATE TABLE `notes`  (
  `note_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `note_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '笔记类型',
  `note_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `note_abstract` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '摘要',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT '分组id',
  `cover_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '封面图片类型（0单图 1多图）',
  `cover_img` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '封面图片',
  `goods_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品id（根据类型判断商品是单个还是多个）',
  `goods_highlights` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品亮点（单品有效）',
  `note_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  `status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '状态（0草稿箱  1发布）',
  `is_show_release_time` tinyint(1) NOT NULL DEFAULT 0 COMMENT '发布时间是否显示',
  `is_show_read_num` tinyint(1) NOT NULL DEFAULT 0 COMMENT '阅读数是否显示',
  `is_show_dianzan_num` tinyint(1) NOT NULL COMMENT '点赞数是否显示',
  `read_num` int(11) NOT NULL DEFAULT 0 COMMENT '阅读数',
  `dianzan_num` int(11) NOT NULL DEFAULT 0 COMMENT '点赞数',
  `create_time` int(11) NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `initial_read_num` int(11) NOT NULL DEFAULT 0 COMMENT '初始阅读数',
  `initial_dianzan_num` int(11) NOT NULL DEFAULT 0 COMMENT '初始点赞数',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`note_id`) USING BTREE,
  INDEX `IDX_promotion_notes_group_id`(`group_id`) USING BTREE,
  INDEX `IDX_promotion_notes_site_id`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺笔记' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of notes
-- ----------------------------

-- ----------------------------
-- Table structure for notes_dianzan_record
-- ----------------------------
DROP TABLE IF EXISTS `notes_dianzan_record`;
CREATE TABLE `notes_dianzan_record`  (
  `record_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `note_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '分组名称',
  PRIMARY KEY (`record_id`) USING BTREE,
  INDEX `IDX_notes_dianzan_record_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_notes_dianzan_record_note_id`(`note_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '笔记点赞记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of notes_dianzan_record
-- ----------------------------

-- ----------------------------
-- Table structure for notes_group
-- ----------------------------
DROP TABLE IF EXISTS `notes_group`;
CREATE TABLE `notes_group`  (
  `group_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分组名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `notes_num` int(11) NOT NULL DEFAULT 0 COMMENT '笔记数',
  `release_num` int(11) NOT NULL DEFAULT 0 COMMENT '发布数',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`group_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '笔记分组' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of notes_group
-- ----------------------------

-- ----------------------------
-- Table structure for notice
-- ----------------------------
DROP TABLE IF EXISTS `notice`;
CREATE TABLE `notice`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '主题',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '内容',
  `is_top` int(11) NOT NULL DEFAULT 0 COMMENT '是否置顶',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `receiving_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '接受对象',
  `receiving_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '接受对象名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '公告排序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '公告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of notice
-- ----------------------------

-- ----------------------------
-- Table structure for open_account
-- ----------------------------
DROP TABLE IF EXISTS `open_account`;
CREATE TABLE `open_account`  (
  `account_id` int(10) NOT NULL AUTO_INCREMENT COMMENT '开户id',
  `site_id` int(10) NOT NULL DEFAULT 0,
  `enterprise_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `province_id` int(10) NOT NULL DEFAULT 0,
  `city_id` int(10) NOT NULL DEFAULT 0,
  `district_id` int(10) NOT NULL DEFAULT 0,
  `full_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业所在地',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业详细地址',
  `business_licence_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `business_license_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '社会信用证有效期类型,1是永久',
  `business_license_start_time` date NULL DEFAULT NULL COMMENT '社会信用证开始日期',
  `business_license_end_time` date NULL DEFAULT NULL COMMENT '社会信用证结束日期',
  `contact_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机号',
  `legal_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '法人姓名',
  `contact_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `id_card_num` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `id_card_time_type` tinyint(1) NOT NULL DEFAULT 0,
  `id_card_start_time` date NULL DEFAULT NULL,
  `id_card_end_time` date NULL DEFAULT NULL,
  `create_time` int(10) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0待审核,1审核通过,2审核拒绝',
  `huifu_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '汇付id',
  `login_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员账号',
  `login_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员密码',
  `req_seq_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `req_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `card_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '卡类型	0：对公，1：对私法人，2：对私非法人',
  `card_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡号',
  `prov_id` int(10) NOT NULL DEFAULT 0 COMMENT '银行所在省',
  `area_id` int(10) NOT NULL DEFAULT 0 COMMENT '银行所在市',
  `bank_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行号',
  `branch_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支行联行号',
  `card_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '持卡人姓名',
  `cert_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '持卡人证件号码',
  `cert_validity_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '持卡人证件有效期类型',
  `cert_begin_date` date NULL DEFAULT NULL COMMENT '持卡人证件有效期（起始）',
  `cert_end_date` date NULL DEFAULT NULL COMMENT '持卡人证件有效期（截止）',
  `apply_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `apply_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '审核状态,1审核中,2审核通过,3审核拒绝',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `token_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '取现卡序列号',
  PRIMARY KEY (`account_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '店铺开户' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of open_account
-- ----------------------------

-- ----------------------------
-- Table structure for order
-- ----------------------------
DROP TABLE IF EXISTS `order`;
CREATE TABLE `order`  (
  `order_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `order_name` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单内容',
  `order_from` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `order_type` int(11) NOT NULL DEFAULT 0 COMMENT '订单类型 1. 普通订单  2. 门店订单  3. 本地配送订单4. 虚拟订单',
  `order_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单类型名称',
  `order_promotion_type` int(11) NOT NULL DEFAULT 0 COMMENT '订单营销类型',
  `order_promotion_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营销活动类型名称',
  `promotion_id` int(11) NOT NULL DEFAULT 0 COMMENT '营销活动id',
  `out_trade_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付流水号',
  `out_trade_no_2` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付流水号（多次支付）',
  `delivery_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '整体提货编码',
  `order_status` int(11) NOT NULL DEFAULT 0 COMMENT '订单状态',
  `order_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单状态名称',
  `order_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单操作',
  `pay_status` int(11) NOT NULL DEFAULT 0 COMMENT '支付状态',
  `delivery_status` int(11) NOT NULL DEFAULT 0 COMMENT '配送状态',
  `refund_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `pay_type` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付方式',
  `pay_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付类型名称',
  `delivery_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '配送方式',
  `delivery_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送方式名称',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人uid',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人姓名',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人手机',
  `telephone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人固定电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人详细地址',
  `longitude` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址经度',
  `latitude` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址纬度',
  `buyer_ip` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人ip',
  `buyer_ask_delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '购买人要求配送时间',
  `buyer_message` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人留言信息',
  `order_invoice_company` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票公司名称',
  `order_invoice_type` int(11) NOT NULL DEFAULT 0 COMMENT '发票类型',
  `order_invoice_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票类型名称',
  `order_invoice_trade_type` int(11) NOT NULL DEFAULT 0 COMMENT '发票行业类型',
  `order_invoice_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票税率',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总金额',
  `delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '配送费用',
  `promotion_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单优惠金额（满减）',
  `coupon_id` int(11) NOT NULL DEFAULT 0 COMMENT '优惠券id',
  `coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `invoice_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票金额',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单合计金额',
  `adjust_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单调整金额',
  `balance_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额支付金额',
  `pay_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '抵扣之后应付金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单支付时间',
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单配送时间',
  `sign_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单签收时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单完成时间',
  `close_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单关闭时间',
  `is_lock` int(11) NOT NULL DEFAULT 0 COMMENT '是否锁定订单（针对维权，锁定不可操作）',
  `is_evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '是否允许订单评价',
  `is_delete` int(11) NOT NULL DEFAULT 0 COMMENT '是否删除(针对后台)',
  `is_enable_refund` int(11) NOT NULL DEFAULT 0 COMMENT '是否允许退款',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '卖家留言',
  `goods_num` int(11) NOT NULL DEFAULT 0 COMMENT '商品件数',
  `delivery_store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `delivery_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发货状态',
  `is_settlement` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否进行结算',
  `store_settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店结算id',
  `delivery_store_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店名称',
  `promotion_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营销类型',
  `promotion_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营销类型名称',
  `promotion_status_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营销状态名称',
  `delivery_store_info` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '门店信息(json)',
  `virtual_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '虚拟商品码',
  `evaluate_status` int(11) NOT NULL DEFAULT 0 COMMENT '评价状态，0：未评价，1：已评价，2：已追评',
  `evaluate_status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价状态名称，未评价，已评价，已追评',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台金额',
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单退款金额',
  `refund_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款店铺金额',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款平台结算金额',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总支出佣金',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT 'shop_settlement表结算id',
  `platform_coupon_id` int(11) NOT NULL DEFAULT 0 COMMENT '平台券id',
  `platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台券平台分摊优惠',
  `platform_coupon_total_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台券总金额',
  `platform_coupon_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台券店铺分摊优惠',
  `is_invoice` int(11) NOT NULL DEFAULT 0 COMMENT '是否需要发票 0 无发票  1 有发票',
  `invoice_type` int(11) NOT NULL DEFAULT 1 COMMENT '发票类型  1 纸质发票 2 电子发票',
  `invoice_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票抬头',
  `taxpayer_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纳税人识别号',
  `invoice_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票税率',
  `invoice_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票内容',
  `invoice_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票邮寄费用',
  `invoice_full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票邮寄地址',
  `is_tax_invoice` int(11) NOT NULL DEFAULT 0 COMMENT '是否需要增值税专用发票',
  `invoice_email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票发送邮件',
  `invoice_title_type` int(11) NOT NULL DEFAULT 0 COMMENT '发票抬头类型  1 个人  2 企业',
  `refund_platform_coupon_total_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_platform_coupon_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `invoice_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '发票状态（0待开票   1已开票）',
  `invoice_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '发票备注',
  `invoice_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票编码',
  `invoice_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票凭证',
  `invoice_time` int(11) NOT NULL DEFAULT 0 COMMENT '开票时间',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销 0不参与 1参与',
  `predict_delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '预计发货时间',
  `is_video_number` int(1) NOT NULL DEFAULT 0 COMMENT '订单是否同步到视频号',
  `order_point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '订单积分',
  `goods_type` tinyint(4) NULL DEFAULT 0 COMMENT '商品类型:0=普通商品,1=福利品',
  `is_admin` tinyint(4) NULL DEFAULT 0 COMMENT '是否总后台添加商品',
  `video_id` int(11) NULL DEFAULT 0 COMMENT '短视频ID',
  PRIMARY KEY (`order_id`) USING BTREE,
  INDEX `IDX_order_create_time`(`create_time`) USING BTREE,
  INDEX `IDX_order_finish_time`(`finish_time`) USING BTREE,
  INDEX `IDX_order_is_tax_invoice`(`is_tax_invoice`) USING BTREE,
  INDEX `IDX_order_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_order_order_from`(`order_from`) USING BTREE,
  INDEX `IDX_order_order_status`(`order_status`) USING BTREE,
  INDEX `IDX_order_order_type`(`order_type`) USING BTREE,
  INDEX `IDX_order_pay_status`(`pay_status`) USING BTREE,
  INDEX `IDX_order_promotion_id`(`promotion_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of order
-- ----------------------------

-- ----------------------------
-- Table structure for order_batch_delivery
-- ----------------------------
DROP TABLE IF EXISTS `order_batch_delivery`;
CREATE TABLE `order_batch_delivery`  (
  `batch_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '导入的订单数',
  `success_num` int(11) NOT NULL DEFAULT 0 COMMENT '成功数',
  `error_num` int(11) NOT NULL DEFAULT 0 COMMENT '失败数',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `batch_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '记录编号',
  PRIMARY KEY (`batch_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单批量导入发货' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of order_batch_delivery
-- ----------------------------

-- ----------------------------
-- Table structure for order_batch_delivery_log
-- ----------------------------
DROP TABLE IF EXISTS `order_batch_delivery_log`;
CREATE TABLE `order_batch_delivery_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `batch_id` int(11) NOT NULL DEFAULT 0 COMMENT '上传文件id',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `order_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单内容',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '原因',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结果  success  成功  fail  失败',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单批量发货导入明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of order_batch_delivery_log
-- ----------------------------

-- ----------------------------
-- Table structure for order_complain
-- ----------------------------
DROP TABLE IF EXISTS `order_complain`;
CREATE TABLE `order_complain`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单项id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买会员姓名',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `sku_no` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `is_virtual` int(11) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品卖价',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '购买数量',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `complain_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款编号（申请产生）',
  `complain_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `complain_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款状态名称',
  `complain_apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款申请金额',
  `complain_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款原因',
  `complain_real_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际退款金额',
  `complain_time` int(11) NOT NULL DEFAULT 0 COMMENT '实际退款时间',
  `complain_refuse_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款拒绝原因',
  `complain_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款说明',
  `complain_money_type` int(11) NOT NULL DEFAULT 1 COMMENT '退款方式   1 原路退款 2线下退款',
  `complain_apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请平台维权时间',
  `complain_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '维权操作',
  `real_goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单项实际金额',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单平台维权投诉' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of order_complain
-- ----------------------------

-- ----------------------------
-- Table structure for order_export
