DROP TABLE IF EXISTS `order_export`;
CREATE TABLE `order_export`  (
  `export_id` int(11) NOT NULL AUTO_INCREMENT,
  `condition` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '条件  json',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '导出状态  0 正在导出 1 已导出  2 已删除',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '导出时间',
  `type` int(11) NOT NULL DEFAULT 0 COMMENT '导出类型',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '导出文件的物理路径',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `app_module` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'shop' COMMENT '应用模块',
  PRIMARY KEY (`export_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单导出记录表' ROW_FORMAT = Dynamic;

