-- ----------------------------
-- Table structure for order_goods
-- ----------------------------
DROP TABLE IF EXISTS `order_goods`;
CREATE TABLE `order_goods`  (
  `order_goods_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买会员id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `sku_no` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `is_virtual` int(11) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品',
  `goods_class` int(11) NOT NULL DEFAULT 0 COMMENT '商品种类(1.实物 2.虚拟3.卡券)',
  `goods_class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品卖价',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '购买数量',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `cost_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本总价',
  `delivery_status` int(11) NOT NULL DEFAULT 0 COMMENT '配送状态',
  `delivery_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送单号',
  `gift_flag` int(11) NOT NULL DEFAULT 0 COMMENT '赠品标识',
  `refund_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款编号（申请产生）',
  `refund_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `refund_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款状态名称',
  `refund_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款操作',
  `refund_type` int(11) NOT NULL DEFAULT 0 COMMENT '退款方式',
  `refund_apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款申请金额',
  `refund_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款原因',
  `refund_real_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际退款金额',
  `refund_delivery_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款公司名称',
  `refund_delivery_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款单号',
  `refund_time` int(11) NOT NULL DEFAULT 0 COMMENT '实际退款时间',
  `refund_refuse_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款拒绝原因',
  `refund_action_time` int(11) NOT NULL DEFAULT 0 COMMENT '退款时间',
  `delivery_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送状态名称',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '待结算佣金比率',
  `real_goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际商品购买价',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺实际金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台实际金额',
  `is_settlement` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否结算',
  `refund_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款说明',
  `refund_delivery_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '买家退货说明',
  `refund_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退货地址',
  `is_refund_stock` int(11) NOT NULL DEFAULT 0 COMMENT '是否返还库存',
  `refund_money_type` int(11) NOT NULL DEFAULT 1 COMMENT '退款方式   1 原路退款 2线下退款',
  `promotion_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠活动金额',
  `coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `adjust_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '调整金额',
  `platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `is_present` int(11) NOT NULL DEFAULT 0,
  `refund_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款中包含的运费',
  `goods_name` varchar(400) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_spec_format` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku规格格式',
  `is_fenxiao` int(11) NOT NULL DEFAULT 1 COMMENT '是否参与分销',
  `goods_type` tinyint(4) NULL DEFAULT 0 COMMENT '商品类型:0=普通商品,1=福利品',
  `point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '积分单价',
  `goods_point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '积分总价',
  `refund_point_money` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '实际退款积分',
  `is_admin` tinyint(4) NULL DEFAULT 0 COMMENT '是否总后台添加商品',
  PRIMARY KEY (`order_goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 155 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单商品表' ROW_FORMAT = Dynamic;

