DROP TABLE IF EXISTS `order_promotion_detail`;
CREATE TABLE `order_promotion_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `promotion_text` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单优惠说明',
  `sku_list` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '参与的商品项',
