-- ----------------------------
-- Table structure for printer
-- ----------------------------
DROP TABLE IF EXISTS `printer`;
CREATE TABLE `printer`  (
  `printer_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `brand` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '小票打印机品牌（365 飞鹤 易联云）',
  `printer_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印机名称',
  `printer_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印机编号',
  `printer_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印机秘钥',
  `open_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开发者id',
  `apikey` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开发者密钥',
  `print_num` tinyint(3) NOT NULL DEFAULT 1 COMMENT '打印张数',
  `order_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印的订单类型',
  `template_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板id',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`printer_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小票打印机' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of printer
-- ----------------------------

-- ----------------------------
-- Table structure for printer_template
-- ----------------------------
DROP TABLE IF EXISTS `printer_template`;
CREATE TABLE `printer_template`  (
  `template_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名',
  `template_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板类型（预留字段）',
  `template_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '小票名称',
  `head` tinyint(1) NOT NULL DEFAULT 0 COMMENT '头部内容',
  `buy_notes` tinyint(1) NOT NULL DEFAULT 0 COMMENT '买家留言（0否 1是）',
  `seller_notes` tinyint(1) NOT NULL DEFAULT 0 COMMENT '卖家留言（0否  1是）',
  `buy_name` tinyint(1) NOT NULL DEFAULT 0 COMMENT '买家姓名',
  `buy_mobile` tinyint(1) NOT NULL DEFAULT 0 COMMENT '买家联系电话',
  `buy_address` tinyint(1) NOT NULL DEFAULT 0 COMMENT '买家地址',
  `shop_mobile` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商家联系电话',
  `shop_address` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商家地址',
  `shop_qrcode` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商家二维码',
  `qrcode_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '二维码链接',
  `bottom` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '底部内容',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`template_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '打印机模板' ROW_FORMAT = Dynamic;

