-- ----------------------------
-- Table structure for promotion_bargain
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bargain`;
CREATE TABLE `promotion_bargain`  (
  `bargain_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '砍价id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `bargain_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '砍价活动名称',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销（0不参与  1参与）',
  `buy_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '购买方式（0任意金额可购买 1砍到指定价格）',
  `bargain_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '砍价金额类型（0固定金额 1随机金额）',
  `bargain_num` int(11) NOT NULL DEFAULT 0 COMMENT '帮砍价人数',
  `bargain_time` int(11) NOT NULL DEFAULT 1 COMMENT '砍价有效期（小时）',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '活动规则说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0未开始 1活动进行中  2活动已结束  3失效  4删除）',
  `status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态名称',
  `is_own` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否自己砍价（0不支持  1支持）',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `join_num` int(11) NOT NULL DEFAULT 0 COMMENT '参与人数',
  `bargain_stock` int(11) NOT NULL DEFAULT 0 COMMENT '砍价总库存',
  `floor_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '底价',
  PRIMARY KEY (`bargain_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_bargain_start_time`(`start_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '砍价活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bargain
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_bargain_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bargain_goods`;
CREATE TABLE `promotion_bargain_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `bargain_id` int(11) NOT NULL DEFAULT 0 COMMENT '砍价id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku商品id',
  `first_bargain_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '首刀金额',
  `bargain_stock` int(11) NOT NULL DEFAULT 0 COMMENT '砍价库存',
  `floor_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '底价',
  `bargain_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '砍价活动名称',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销（0不参与  1参与）',
  `buy_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '购买方式（0任意金额可购买 1砍到指定价格）',
  `bargain_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '砍价金额类型（0固定金额 1随机金额）',
  `bargain_num` int(11) NOT NULL DEFAULT 0 COMMENT '帮砍价人数',
  `bargain_time` int(11) NOT NULL DEFAULT 1 COMMENT '砍价有效期',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '活动规则说明',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0未开始 1活动进行中  2活动已结束  3已关闭）',
  `status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态名称',
  `is_own` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否自己砍价（0不支持  1支持）',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `join_num` int(11) NOT NULL DEFAULT 0 COMMENT '参与人数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_bargain_goods_bargain_id`(`bargain_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_goods_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_goods_is_own`(`is_own`) USING BTREE,
  INDEX `IDX_promotion_bargain_goods_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_goods_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '砍价活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bargain_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_bargain_launch
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bargain_launch`;
CREATE TABLE `promotion_bargain_launch`  (
  `launch_id` int(11) NOT NULL AUTO_INCREMENT,
  `bargain_id` int(11) NOT NULL DEFAULT 0 COMMENT '砍价活动id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品原价',
  `floor_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '底价',
  `buy_type` int(1) NOT NULL DEFAULT 0 COMMENT '购买方式（0任意金额可购买 1砍到指定价格）',
  `bargain_type` int(1) NOT NULL DEFAULT 0 COMMENT '砍价金额类型（0固定金额 1随机金额）',
  `need_num` int(11) NOT NULL DEFAULT 0 COMMENT '帮砍人数需达到数',
  `curr_num` int(11) NOT NULL DEFAULT 0 COMMENT '当前已帮砍人数',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `status` int(1) NOT NULL DEFAULT 0 COMMENT '0砍价中 1已成功 2未成功',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '砍价发起用户',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `is_fenxiao` int(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销（0不参与  1参与）',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `first_bargain_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '首刀金额',
  `curr_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当前金额',
  `is_own` int(11) NOT NULL DEFAULT 0 COMMENT '是否自己砍价（0不支持  1支持）',
  PRIMARY KEY (`launch_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_bargain_id`(`bargain_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_launch_start_time`(`start_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '砍价发起表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bargain_launch
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_bargain_record
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bargain_record`;
CREATE TABLE `promotion_bargain_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `launch_id` int(11) NOT NULL DEFAULT 0 COMMENT '砍价发起id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '帮砍会员id',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '帮砍金额',
  `bargain_time` int(11) NOT NULL DEFAULT 0 COMMENT '帮砍时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_bargain_record_bargain_time`(`bargain_time`) USING BTREE,
  INDEX `IDX_promotion_bargain_record_launch_id`(`launch_id`) USING BTREE,
  INDEX `IDX_promotion_bargain_record_member_id`(`member_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bargain_record
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_bundling
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bundling`;
CREATE TABLE `promotion_bundling`  (
  `bl_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '组合ID',
  `bl_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '组合名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `bl_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品组合价格',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `shipping_fee_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '运费承担方式 1卖家承担运费 2买家承担运费',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '组合状态 0-关闭/1-开启',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`bl_id`) USING BTREE,
  INDEX `IDX_promotion_bundling_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_bundling_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '组合套餐活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bundling
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_bundling_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_bundling_goods`;
CREATE TABLE `promotion_bundling_goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `bl_id` int(11) NOT NULL DEFAULT 0 COMMENT '组合id',
  `sku_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品sku原价',
  `sku_image` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku图片',
  `promotion_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '套餐价格',
  `site_id` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_bundling_goods_bl_id`(`bl_id`) USING BTREE,
  INDEX `IDX_promotion_bundling_goods_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_bundling_goods_sku_id`(`sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '组合套餐活动商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_bundling_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_coupon
-- ----------------------------
DROP TABLE IF EXISTS `promotion_coupon`;
CREATE TABLE `promotion_coupon`  (
  `coupon_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '优惠券id',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券类型 reward-满减 discount-折扣 random-随机',
  `coupon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `coupon_type_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券类型id',
  `site_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '站点Id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '站点名称',
  `coupon_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编码',
  `member_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领用人',
  `use_order_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券使用订单id',
  `goods_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '适用商品类型1-全部商品可用；2-指定商品可用；3-指定商品不可用',
  `goods_ids` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '适用商品id',
  `at_least` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最小金额',
  `money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '面额',
  `discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '1 =< 折扣 <= 9.9 当type为discount时需要添加',
  `discount_limit` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最多折扣金额 当type为discount时可选择性添加',
  `is_mark` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否同时给会员打标签 0-否 1-是',
  `member_label_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员标签id',
  `is_share` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '分享设置 优惠券允许分享给好友领取',
  `is_handsel` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '转赠设置 优惠券允许转赠给好友',
  `is_forbid_preference` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠叠加 0-不限制 1- 优惠券仅原价购买商品时可用',
  `is_expire_notice` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启过期提醒0-不开启 1-开启',
  `expire_notice_fixed_term` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '过期前N天提醒',
  `is_noticed` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已提醒',
  `state` tinyint(4) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券状态 1已领用（未使用） 2已使用 3已过期',
  `get_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '获取方式1订单2.直接领取3.活动领取 4转赠 5分享获取',
  `related_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '获取优惠券的关联id',
  `fetch_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取时间',
  `use_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用时间',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '可使用的开始时间',
  `end_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效期结束时间',
  PRIMARY KEY (`coupon_id`) USING BTREE,
  INDEX `IDX_promotion_coupon_coupon_type_id`(`coupon_type_id`) USING BTREE,
  INDEX `IDX_promotion_coupon_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_coupon_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_promotion_coupon_site_id`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '优惠券表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_coupon
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_coupon_type
-- ----------------------------
DROP TABLE IF EXISTS `promotion_coupon_type`;
CREATE TABLE `promotion_coupon_type`  (
  `coupon_type_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '优惠券类型Id',
  `type` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券类型 reward-满减 discount-折扣 random-随机',
  `site_id` int(11) NOT NULL DEFAULT 1 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `coupon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `coupon_name_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '名称备注',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券图片',
  `count` int(11) NOT NULL DEFAULT 0 COMMENT '发放数量',
  `lead_count` int(11) NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `used_count` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '已使用数量',
  `goods_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '适用商品类型1-全部商品可用；2-指定商品可用；3-指定商品不可用',
  `goods_ids` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '适用商品id',
  `is_limit` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用门槛0-无门槛 1-有门槛',
  `at_least` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '满多少元使用 0代表无限制',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发放面额 当type为reward时需要添加',
  `discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '1 =< 折扣 <= 9.9 当type为discount时需要添加',
  `discount_limit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最多折扣金额 当type为discount时可选择性添加',
  `min_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最低金额 当type为radom时需要添加',
  `max_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最大金额 当type为radom时需要添加',
  `validity_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '过期类型1-时间范围过期 2-领取之日固定日期后过期 3-领取次日固定日期后过期',
  `start_use_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用开始日期 过期类型1时必填',
  `end_use_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用结束日期 过期类型1时必填',
  `fixed_term` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '当validity_type为2或者3时需要添加 领取之日起或者次日N天内有效',
  `is_limit_member` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否限制会员身份0-不限制 1限制',
  `member_level_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '若开启会员身份限制,需要添加会员等级id',
  `is_limitless` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否无限制0-否 1是',
  `max_fetch` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '每人最大领取个数',
  `is_expire_notice` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启过期提醒0-不开启 1-开启',
  `expire_notice_fixed_term` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '过期前N天提醒',
  `is_mark` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否同时给会员打标签 0-否 1-是',
  `member_label_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员标签id',
  `is_share` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '分享设置 优惠券允许分享给好友领取',
  `is_handsel` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '转赠设置 优惠券允许转赠给好友',
  `is_forbid_preference` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠叠加 0-不限制 1- 优惠券仅原价购买商品时可用',
  `is_show` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否显示',
  `discount_order_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单的优惠总金额',
  `order_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '用券总成交额',
  `is_forbidden` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否禁止发放0-否 1-是',
  `old_member_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用优惠券的老会员数',
  `new_member_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台第一次购买使用优惠券的会员数',
  `order_goods_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用优惠券购买的商品数量',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态（1进行中2已结束-1已关闭）',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '修改时间',
  `end_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效日期结束时间',
  `is_limitcount` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否限制领取数量,0限制，1无限制',
  PRIMARY KEY (`coupon_type_id`) USING BTREE,
  INDEX `IDX_promotion_coupon_type_site_id`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '优惠券类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_coupon_type
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_discount
-- ----------------------------
DROP TABLE IF EXISTS `promotion_discount`;
CREATE TABLE `promotion_discount`  (
  `discount_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 1 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `discount_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1进行中 2已结束 -1已关闭（手动）',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `discount_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '折扣金额，只做展示',
  PRIMARY KEY (`discount_id`) USING BTREE,
  INDEX `IDX_promotion_discount_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_discount_start_time`(`start_time`) USING BTREE,
  INDEX `IDX_promotion_discount_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '限时折扣' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_discount
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_discount_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_discount_goods`;
CREATE TABLE `promotion_discount_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `discount_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应活动Id',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuId',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `discount_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '折扣价',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '商品图片',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_discount_goods_discount_id`(`discount_id`) USING BTREE,
  INDEX `IDX_promotion_discount_goods_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_discount_goods_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_discount_goods_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_promotion_discount_goods_start_time`(`start_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '限时折扣商品列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_discount_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_exchange
-- ----------------------------
DROP TABLE IF EXISTS `promotion_exchange`;
CREATE TABLE `promotion_exchange`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '兑换形式',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '兑换类型名称',
  `type_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '兑换名称',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '当前库存',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分数',
  `market_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '市场价',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '兑换价',
  `delivery_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '物流费用（礼品有效）',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额红包（余额有效）',
  `state` int(11) NOT NULL DEFAULT 1 COMMENT '状态（上下架）',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '兑换说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `pay_type` int(11) NOT NULL DEFAULT 0,
  `sort` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '积分兑换' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_exchange
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_exchange_order
-- ----------------------------
DROP TABLE IF EXISTS `promotion_exchange_order`;
CREATE TABLE `promotion_exchange_order`  (
  `order_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应会员',
  `out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付流水号（线上支付有效）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '兑换积分数',
  `exchange_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '兑换价格',
  `delivery_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '邮费',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际应付金额',
  `express_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流单号（礼品发货）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '兑换成功时间',
  `exchange_id` int(11) NOT NULL DEFAULT 0 COMMENT '兑换商品id',
  `exchange_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '兑换商品名称',
  `exchange_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '兑换商品图片',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '兑换数量',
  `order_status` int(11) NOT NULL DEFAULT 0 COMMENT '状态',
  `type` int(11) NOT NULL DEFAULT 0 COMMENT '类型',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '姓名',
  `mobile` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `telephone` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地址信息',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址信息',
  `longitude` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `buyer_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `order_from` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `type_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '赠送红包',
  `gift_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联订单id',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '积分兑换订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_exchange_order
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_freeshipping
-- ----------------------------
DROP TABLE IF EXISTS `promotion_freeshipping`;
CREATE TABLE `promotion_freeshipping`  (
  `freeshipping_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `area_ids` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '地区ids',
  `area_names` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '地区名称',
  `surplus_area_ids` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`freeshipping_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '满额包邮' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_freeshipping
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_games
-- ----------------------------
DROP TABLE IF EXISTS `promotion_games`;
CREATE TABLE `promotion_games`  (
  `game_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '游戏id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `game_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '游戏活动名称',
  `game_type` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '游戏类型（插件名称）',
  `game_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '游戏类型名称',
  `level_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '参与的会员等级0表示全部参与',
  `level_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '参与活动会员名称',
  `points` int(11) NOT NULL DEFAULT 0 COMMENT '参与一次扣除积分',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1已开始 2已结束 3已关闭',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '活动说明',
  `winning_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '中奖率',
  `no_winning_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `no_winning_desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '未中奖说明',
  `is_show_winner` int(11) NOT NULL DEFAULT 0 COMMENT '中奖名单是否显示 0不显示 1显示',
  `join_type` int(11) NOT NULL DEFAULT 0 COMMENT '参加类型 0活动全过程 1每天',
  `join_frequency` int(11) NOT NULL DEFAULT 1 COMMENT '根据类型计算参加次数',
  `join_num` int(11) NOT NULL DEFAULT 0 COMMENT '抽奖人数',
  `winning_num` int(11) NOT NULL DEFAULT 0 COMMENT '中奖人数',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`game_id`) USING BTREE,
  INDEX `IDX_promotion_games_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_games_game_type`(`game_type`) USING BTREE,
  INDEX `IDX_promotion_games_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_games_start_time`(`start_time`) USING BTREE,
  INDEX `IDX_promotion_games_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '营销游戏（概率游戏）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_games
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_games_award
-- ----------------------------
DROP TABLE IF EXISTS `promotion_games_award`;
CREATE TABLE `promotion_games_award`  (
  `award_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `game_id` int(11) NOT NULL DEFAULT 0 COMMENT '游戏id',
  `award_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '奖品名称',
  `award_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `award_type` tinyint(3) NOT NULL DEFAULT 0 COMMENT '奖品类型（1积分  2余额（不可提现）  3优惠券  4赠品）',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id（根据奖品类型）',
  `relate_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关联商品名称（优惠券或者赠品名称）',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '积分数',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `award_num` int(11) NOT NULL DEFAULT 0 COMMENT '奖品数量',
  `award_winning_rate` int(11) NOT NULL DEFAULT 0 COMMENT '奖品中奖概率',
  `remaining_num` int(11) NOT NULL DEFAULT 0 COMMENT '剩余数量',
  `receive_num` int(11) NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `no_winning_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '未中奖图片',
  PRIMARY KEY (`award_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '游戏奖品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_games_award
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_games_draw_record
-- ----------------------------
DROP TABLE IF EXISTS `promotion_games_draw_record`;
CREATE TABLE `promotion_games_draw_record`  (
  `record_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `game_id` int(11) NOT NULL DEFAULT 0 COMMENT '游戏id',
  `game_type` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '游戏类型（插件名称）',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `member_nick_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员昵称',
  `points` int(11) NOT NULL DEFAULT 0 COMMENT '参与消耗积分',
  `is_winning` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否中奖（0未中  1中奖）',
  `award_id` int(11) NOT NULL DEFAULT 0 COMMENT '奖品id',
  `award_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '奖品名称',
  `award_type` tinyint(3) NOT NULL DEFAULT 0 COMMENT '奖品类型（1积分  2余额（不可提现）  3优惠券  4赠品）',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联id（根据奖品类型）',
  `relate_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关联商品名称（优惠券或者赠品名称）',
  `is_receive` tinyint(3) NOT NULL DEFAULT 0 COMMENT '是否领取（0未领取 1领取）奖品为优惠券 赠品是使用',
  `point` int(11) NOT NULL DEFAULT 0 COMMENT '奖励积分数',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '奖励余额',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '参与时间',
  PRIMARY KEY (`record_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '抽奖记录' ROW_FORMAT = Dynamic;

