-- ----------------------------
-- Table structure for promotion_gift
-- ----------------------------
DROP TABLE IF EXISTS `promotion_gift`;
CREATE TABLE `promotion_gift`  (
  `gift_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `gift_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '礼品编号',
