  `gift_keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '礼品关键字',
  `gift_desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '礼品简介',
  `gift_body` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '礼品详情',
  `gift_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '礼品价格',
  `gift_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '礼品图片',
  `gift_stock` int(11) NOT NULL DEFAULT 0 COMMENT '礼品库存',
  `gift_state` int(11) NOT NULL DEFAULT 0 COMMENT '礼品状态',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `is_delete` int(11) NOT NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`gift_id`) USING BTREE
