  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `event` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '查询事件',
  `tag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关联标识',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `express_status` int(11) NOT NULL DEFAULT 0 COMMENT '配送状态',
  `express_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送编码',
  `express_company_id` int(11) NOT NULL DEFAULT 0 COMMENT '物流公司id',
  `express_company_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `express_time` int(11) NOT NULL DEFAULT 0 COMMENT '配送时间',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
