  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `relevant_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '相关的订单ID',
  `get_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '获取方式名称，积分兑换',
