DROP TABLE IF EXISTS `promotion_groupbuy`;
CREATE TABLE `promotion_groupbuy`  (
  `groupbuy_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `goods_image` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `is_virtual_goods` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品（0否 1是）',
  `goods_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品原价',
  `groupbuy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '团购价',
  `buy_num` int(11) NOT NULL DEFAULT 0 COMMENT '最低购买量',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `sell_num` int(11) NOT NULL DEFAULT 0 COMMENT '已出售数量',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态（1未开始  2进行中  3已结束）',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku',
  PRIMARY KEY (`groupbuy_id`) USING BTREE,
  INDEX `IDX_promotion_groupbuy_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_groupbuy_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_groupbuy_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_groupbuy_start_time`(`start_time`) USING BTREE,
  INDEX `IDX_promotion_groupbuy_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '团购' ROW_FORMAT = Dynamic;

