-- ----------------------------
-- Table structure for promotion_manjian
-- ----------------------------
DROP TABLE IF EXISTS `promotion_manjian`;
CREATE TABLE `promotion_manjian`  (
  `manjian_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `manjian_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `manjian_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1全部商品参与  2指定商品 3指定商品不参与 ',
  `type` int(1) NOT NULL DEFAULT 0 COMMENT '条件类型 0:满N元  1:满N件',
  `goods_ids` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品id集',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态（0未开始1进行中2已结束-1已关闭）',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `rule_json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '{}' COMMENT '规则json',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`manjian_id`) USING BTREE,
  INDEX `IDX_promotion_manjian_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_manjian_manjian_type`(`manjian_type`) USING BTREE,
  INDEX `IDX_promotion_manjian_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_manjian_start_time`(`start_time`) USING BTREE,
  INDEX `IDX_promotion_manjian_status`(`status`) USING BTREE,
  INDEX `IDX_promotion_manjian_type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '满减活动' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_manjian
