  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `manjian_id` int(11) NOT NULL DEFAULT 0 COMMENT '满减活动id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `manjian_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1全部商品参与  2指定商品 3指定商品不参与 ',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0未开始1进行中2已结束-1已关闭）',
  `rule_json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '满减规则json',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_manjian_goods_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_manjian_goods_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_manjian_goods_manjian_id`(`manjian_id`) USING BTREE,
  INDEX `IDX_promotion_manjian_goods_manjian_type`(`manjian_type`) USING BTREE,
  INDEX `IDX_promotion_manjian_goods_start_time`(`start_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '满减商品表' ROW_FORMAT = Dynamic;

