  `promotion_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '团长优惠价',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_pintuan_goods_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_pintuan_goods_pintuan_id`(`pintuan_id`) USING BTREE,
  INDEX `IDX_promotion_pintuan_goods_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_pintuan_goods_sku_id`(`sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '拼团商品表' ROW_FORMAT = Dynamic;

