-- ----------------------------
-- Table structure for promotion_platformcoupon
-- ----------------------------
DROP TABLE IF EXISTS `promotion_platformcoupon`;
CREATE TABLE `promotion_platformcoupon`  (
  `platformcoupon_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '优惠券id',
  `platformcoupon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `platformcoupon_type_id` int(11) NOT NULL DEFAULT 0 COMMENT '优惠券类型id',
  `platformcoupon_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编码',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '领用人',
  `use_order_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券使用订单id',
  `at_least` decimal(10, 2) NOT NULL COMMENT '最小金额',
  `money` decimal(10, 2) NOT NULL COMMENT '面额',
  `state` tinyint(4) NOT NULL DEFAULT 0 COMMENT '优惠券状态 1已领用（未使用） 2已使用 3已过期',
  `get_type` int(11) NOT NULL DEFAULT 0 COMMENT '获取方式1订单2.直接领取3.活动领取4.系统发放5.用户操作奖励6.会员级别升级送优惠券',
  `fetch_time` int(11) NOT NULL DEFAULT 0 COMMENT '领取时间',
  `use_time` int(11) NOT NULL DEFAULT 0 COMMENT '使用时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '有效期结束时间',
  `use_scenario` tinyint(3) NOT NULL DEFAULT 1 COMMENT '使用场景（1全场通用 2指定店铺）',
  `group_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺等级ids',
  `platform_split_rare` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台分担比例',
  `shop_split_rare` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺分店比例',
  PRIMARY KEY (`platformcoupon_id`) USING BTREE,
  INDEX `IDX_promotion_platformcoupon_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_platformcoupon_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_promotion_platformcoupon_platformcoupon_type_id`(`platformcoupon_type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '优惠券表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_platformcoupon
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_platformcoupon_type
-- ----------------------------
DROP TABLE IF EXISTS `promotion_platformcoupon_type`;
CREATE TABLE `promotion_platformcoupon_type`  (
  `platformcoupon_type_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '优惠券类型Id',
  `platformcoupon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `money` decimal(10, 2) NOT NULL COMMENT '发放面额',
  `count` int(11) NOT NULL DEFAULT 0 COMMENT '发放数量',
  `lead_count` int(11) NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `max_fetch` int(11) NOT NULL DEFAULT 0 COMMENT '每人最大领取个数 0无限制',
  `at_least` decimal(10, 2) NOT NULL COMMENT '满多少元使用 0代表无限制',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '有效日期结束时间',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券图片',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `validity_type` int(1) NOT NULL DEFAULT 0 COMMENT '有效期类型 0固定时间 1领取之日起',
  `fixed_term` int(3) NOT NULL DEFAULT 1 COMMENT '领取之日起N天内有效',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态（1进行中2已结束-1已关闭）',
  `is_show` int(11) NOT NULL DEFAULT 0 COMMENT '是否显示',
  `use_scenario` tinyint(3) NOT NULL DEFAULT 1 COMMENT '使用场景（1全场通用 2指定店铺）',
  `group_ids` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺等级ids',
  `platform_split_rare` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台分担比例',
  `shop_split_rare` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺分店比例',
  PRIMARY KEY (`platformcoupon_type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '优惠券类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_platformcoupon_type
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_presale
-- ----------------------------
DROP TABLE IF EXISTS `promotion_presale`;
CREATE TABLE `promotion_presale`  (
  `presale_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `presale_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '预售活动名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '所属店铺名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `presale_stock` int(11) NOT NULL DEFAULT 0 COMMENT '预售总库存',
  `presale_num` int(11) NOT NULL DEFAULT 0 COMMENT '限购',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '定金开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '定金结束时间',
  `pay_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '尾款支付时间',
  `pay_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '尾款结束时间',
  `deliver_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '发货方式（0固定时间   1尾款支付后N天）',
  `deliver_time` int(11) NOT NULL DEFAULT 0 COMMENT '发货时间',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销（0不参与  1参与）',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0未开始 1活动进行中  2活动已结束  3失效  4删除）',
  `status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态名称',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `presale_deposit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '预售定金',
  `presale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '抵扣金额',
  `sku_id` int(11) NOT NULL DEFAULT 0,
  `is_deposit_back` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否退定金是0 否1',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `deposit_agreement` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '定金协议',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '活动规则说明',
  PRIMARY KEY (`presale_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商品预售' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_presale
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_presale_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_presale_goods`;
CREATE TABLE `promotion_presale_goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `presale_id` int(11) NOT NULL DEFAULT 0,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `goods_id` int(11) NOT NULL DEFAULT 0,
  `sku_id` int(11) NOT NULL DEFAULT 0,
  `presale_stock` int(11) NOT NULL DEFAULT 0 COMMENT '预售库存',
  `presale_deposit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '预售定金',
  `presale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '抵扣金额',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_presale_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_presale_order
-- ----------------------------
DROP TABLE IF EXISTS `promotion_presale_order`;
CREATE TABLE `promotion_presale_order`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `presale_id` int(11) NOT NULL DEFAULT 0 COMMENT '预售id',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `deposit_out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定金支付流水号',
  `final_out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '尾款支付流水号',
  `order_from` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `order_type` int(11) NOT NULL DEFAULT 0 COMMENT '订单类型 1. 普通订单  2. 门店订单  3. 本地配送订单4. 虚拟订单',
  `order_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单类型名称',
  `pay_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '尾款支付开始时间',
  `pay_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '尾款支付结束时间',
  `is_fenxiao` int(1) NOT NULL DEFAULT 0 COMMENT '是否参与分销 0不参与 1参与',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `goods_name` varchar(400) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `sku_no` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `is_virtual` int(11) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品',
  `goods_class` int(11) NOT NULL DEFAULT 0 COMMENT '商品种类(1.实物 2.虚拟3.卡券)',
  `goods_class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `sku_spec_format` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku规格格式',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人uid',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人姓名',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人手机',
  `telephone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人固定电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人详细地址',
  `longitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址经度',
  `latitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址纬度',
  `buyer_ip` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人ip',
  `buyer_ask_delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '购买人要求配送时间',
  `buyer_message` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人留言信息',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '购买数量',
  `presale_deposit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '预售定金单价',
  `presale_deposit_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '定金总额',
  `presale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '抵扣金额单价',
  `presale_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '抵扣总额',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品单价',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总额',
  `balance_deposit_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额支付定金金额',
  `pay_deposit_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '现金支付定金金额',
  `delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '配送金额',
  `promotion_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单优惠金额',
  `coupon_id` int(11) NOT NULL DEFAULT 0 COMMENT '优惠券id',
  `coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `invoice_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票金额',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `final_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '尾款总额',
  `balance_final_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额支付尾款金额',
  `pay_final_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '现金支付尾款金额',
  `pay_deposit_time` int(11) NOT NULL DEFAULT 0 COMMENT '定金支付时间',
  `deposit_pay_type` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定金支付方式',
  `deposit_pay_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定金支付类型名称',
  `pay_final_time` int(11) NOT NULL DEFAULT 0 COMMENT '尾款支付时间',
  `final_pay_type` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '尾款支付方式',
  `final_pay_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '尾款支付类型名称',
  `order_status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '订单状态',
  `order_status_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态名称',
  `order_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单操作',
  `deposit_refund_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定金退款流水号',
  `final_refund_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '尾款退款流水号',
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `refund_status_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款名称',
  `apply_refund_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请退款时间',
  `refund_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `refuse_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `delivery_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '配送方式',
  `delivery_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送方式名称',
  `delivery_store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `delivery_store_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店名称',
  `delivery_store_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店信息(json)',
  `is_invoice` int(11) NOT NULL DEFAULT 0 COMMENT '是否需要发票 0 无发票  1 有发票',
  `invoice_type` int(11) NOT NULL DEFAULT 1 COMMENT '发票类型  1 纸质发票 2 电子发票',
  `invoice_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票抬头',
  `taxpayer_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纳税人识别号',
  `invoice_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票税率',
  `invoice_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票内容',
  `invoice_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票邮寄费用',
  `invoice_full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票邮寄地址',
  `is_tax_invoice` int(11) NOT NULL DEFAULT 0 COMMENT '是否需要增值税专用发票',
  `invoice_email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发票发送邮件',
  `invoice_title_type` int(11) NOT NULL DEFAULT 0 COMMENT '发票抬头类型  1 个人  2 企业',
  `close_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单关闭时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单创建时间',
  `predict_delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '预计发货时间',
  `is_deposit_back` int(11) NOT NULL DEFAULT 0 COMMENT '是否退定金是0 否1',
  `deposit_agreement` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '定金协议',
  `relate_order_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联订单id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '预售定金表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_presale_order
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_present
-- ----------------------------
DROP TABLE IF EXISTS `promotion_present`;
CREATE TABLE `promotion_present`  (
  `present_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `is_virtual` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品（0否 1是）',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '已赠送数量',
  `limit_num` int(11) NOT NULL DEFAULT 0 COMMENT '每人限制领取数量',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态（1未开始  2进行中  3已结束）',
  PRIMARY KEY (`present_id`) USING BTREE,
  INDEX `IDX_promotion_present_goods_id`(`goods_id`) USING BTREE,
  INDEX `IDX_promotion_present_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_present_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '赠品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_present
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_present_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_present_goods`;
CREATE TABLE `promotion_present_goods`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺id',
  `present_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '主键',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sale_num` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '赠品参与商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_present_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_seckill
-- ----------------------------
DROP TABLE IF EXISTS `promotion_seckill`;
CREATE TABLE `promotion_seckill`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 1 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `seckill_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1进行中 2已结束 -1已关闭（手动）',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `goods_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `seckill_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀金额，只做展示',
  `seckill_time_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '秒杀时段id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '秒杀活动' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_seckill
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_seckill_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_seckill_goods`;
CREATE TABLE `promotion_seckill_goods`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺id',
  `seckill_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '主键',
  `seckill_time_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '秒杀时间段',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `seckill_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀金额',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原价',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '秒杀库存',
  `max_buy` int(11) NOT NULL DEFAULT 0 COMMENT '每人限购',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1进行中 2已结束 -1已关闭（手动）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '秒杀参与商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_seckill_goods
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_seckill_time
-- ----------------------------
DROP TABLE IF EXISTS `promotion_seckill_time`;
CREATE TABLE `promotion_seckill_time`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '秒杀时段名称',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '修改时间',
  `seckill_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间点',
  `seckill_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间点',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '秒杀时段' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_seckill_time
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_topic
-- ----------------------------
DROP TABLE IF EXISTS `promotion_topic`;
CREATE TABLE `promotion_topic`  (
  `topic_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `topic_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '专题名称',
  `topic_adv` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '专题广告',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '活动状态 1未开始  2进行中  3已结束',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '结束时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `bg_color` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '#ffffff' COMMENT '背景色',
  PRIMARY KEY (`topic_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '专题活动' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_topic
-- ----------------------------

-- ----------------------------
-- Table structure for promotion_topic_goods
-- ----------------------------
DROP TABLE IF EXISTS `promotion_topic_goods`;
CREATE TABLE `promotion_topic_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `topic_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应活动Id',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '活动结束时间',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuId',
  `topic_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '折扣价',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `default` int(1) NOT NULL DEFAULT 0 COMMENT '是否为默认展示规格',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_promotion_topic_goods_end_time`(`end_time`) USING BTREE,
  INDEX `IDX_promotion_topic_goods_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_promotion_topic_goods_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_promotion_topic_goods_start_time`(`start_time`) USING BTREE,
  INDEX `IDX_promotion_topic_goods_topic_id`(`topic_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '限时折扣商品列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotion_topic_goods
-- ----------------------------

-- ----------------------------
-- Table structure for reward_config
-- ----------------------------
DROP TABLE IF EXISTS `reward_config`;
CREATE TABLE `reward_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `city_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商会比例',
  `site_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商家比例',
  `staff_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '员工比例',
  `site_rate2` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台分商家比例',
  `level2` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '钻石比例',
  `level3` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '黑钻比例',
  `level4` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '合伙人比例',
  `point_year` int(11) NULL DEFAULT 1 COMMENT '积分有效期',
  `video_day` int(11) NULL DEFAULT 0 COMMENT '新视频置顶天数',
  `video_order_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '下单次数权重',
  `video_share_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '转发数权重',
  `video_end_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '完播率权重',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '奖励设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of reward_config
-- ----------------------------

-- ----------------------------
-- Table structure for servicer
-- ----------------------------
DROP TABLE IF EXISTS `servicer`;
CREATE TABLE `servicer`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '客服ID',
  `is_platform` tinyint(2) NOT NULL DEFAULT 1 COMMENT '是否平台客服',
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '商户ID',
  `user_id` int(11) NOT NULL DEFAULT 0 COMMENT '客服账号归属用户ID',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '客服创建时间',
  `last_online_time` int(11) NOT NULL DEFAULT 0 COMMENT '最近在线时间',
  `delete_time` int(11) NOT NULL DEFAULT 0 COMMENT '删除时间',
  `client_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'session会话临时ID',
  `online` tinyint(2) NOT NULL DEFAULT 0 COMMENT '是否在线',
  `nickname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '客服昵称',
  `avatar` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '客服头像',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '客服基础表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of servicer
-- ----------------------------

-- ----------------------------
-- Table structure for servicer_dialogue
-- ----------------------------
DROP TABLE IF EXISTS `servicer_dialogue`;
CREATE TABLE `servicer_dialogue`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '数据ID',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员ID（匿名聊天则为0）',
  `servicer_id` int(11) NOT NULL COMMENT '客服ID',
  `create_day` date NOT NULL COMMENT '聊天创建日',
  `create_time` time NOT NULL COMMENT '聊天创建时间',
  `add_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间戳',
  `content_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '内容类型（0文本1商品2订单3图片）',
  `read` tinyint(2) NOT NULL DEFAULT 0 COMMENT '消息是否已读',
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '商户ID',
  `goods_sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联商品ID',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联订单ID',
  `consumer_say` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '顾客说',
  `servicer_say` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '客服说',
  `type` tinyint(2) NOT NULL DEFAULT 0 COMMENT '0: say,客户咨询，1：answer,客服回答',
  `relate_data` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '相关数据 json格式',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '聊天内容',
  `message` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `index_create_day`(`create_day`) USING BTREE COMMENT '聊天日期索引'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '客服对话内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of servicer_dialogue
-- ----------------------------

-- ----------------------------
-- Table structure for servicer_fast_reply
-- ----------------------------
DROP TABLE IF EXISTS `servicer_fast_reply`;
CREATE TABLE `servicer_fast_reply`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '回复内容',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '客服快捷回复表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of servicer_fast_reply
-- ----------------------------

-- ----------------------------
-- Table structure for servicer_keyword_reply
-- ----------------------------
DROP TABLE IF EXISTS `servicer_keyword_reply`;
CREATE TABLE `servicer_keyword_reply`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `keyword` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键词',
  `content_type` tinyint(3) NOT NULL DEFAULT 0 COMMENT '内容类型',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '回复内容',
  `is_use` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否使用',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `INDEX`(`keyword`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '客服关键词回复表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of servicer_keyword_reply
-- ----------------------------

-- ----------------------------
-- Table structure for servicer_member
-- ----------------------------
DROP TABLE IF EXISTS `servicer_member`;
CREATE TABLE `servicer_member`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '数据ID',
  `member_id` int(11) NOT NULL COMMENT '关联会员ID',
  `servicer_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联客服ID',
  `member_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名称',
  `online` tinyint(2) NOT NULL DEFAULT 0 COMMENT '是否在线',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '登录时间',
  `last_online_time` int(11) NOT NULL DEFAULT 0 COMMENT '上次在线时间',
  `delete_time` int(11) NOT NULL DEFAULT 0 COMMENT '删除时间',
  `headimg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员头像',
  `client_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'session会话临时ID',
  `shop_id` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '聊天会员在线状态表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of servicer_member
-- ----------------------------

-- ----------------------------
-- Table structure for shop
-- ----------------------------
DROP TABLE IF EXISTS `shop`;
CREATE TABLE `shop`  (
  `site_id` int(11) NOT NULL,
  `expire_time` int(11) NOT NULL DEFAULT 0 COMMENT '到期时间（0表示无限期）',
  `site_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员用户',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `cert_id` int(11) NOT NULL DEFAULT 0 COMMENT '认证信息',
  `is_own` int(11) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺等级',
  `level_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺等级名称',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺类别',
  `category_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺类别名称',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT '分组id',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分组名称',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '创建会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '创建会员名称',
  `shop_status` int(11) NOT NULL DEFAULT 1 COMMENT '店铺经营状态（0.关闭，1正常 2. 审核中）',
  `close_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺关闭原因',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '经营时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '关闭时间',
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺logo',
  `avatar` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺头像（大图）',
  `banner` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺条幅',
  `seo_keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺关键字',
  `seo_description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺简介',
  `qq` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人qq',
  `ww` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人阿里旺旺',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `telephone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系手机号',
  `is_recommend` int(11) NOT NULL DEFAULT 0 COMMENT '是否推荐',
  `shop_desccredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '描述分值',
  `shop_servicecredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '服务分值',
  `shop_deliverycredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '发货速度分值',
  `workingtime` int(11) NOT NULL DEFAULT 0 COMMENT '工作时间',
  `shop_baozh` int(11) NOT NULL DEFAULT 0 COMMENT '保证服务开关',
  `shop_baozhopen` int(11) NOT NULL DEFAULT 0 COMMENT '保证金显示开关',
  `shop_baozhrmb` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金金额',
  `shop_qtian` int(11) NOT NULL DEFAULT 0 COMMENT '7天退换',
  `shop_zhping` int(11) NOT NULL DEFAULT 0 COMMENT '正品保障',
  `shop_erxiaoshi` int(11) NOT NULL DEFAULT 0 COMMENT '两小时发货',
  `shop_tuihuo` int(11) NOT NULL DEFAULT 0 COMMENT '退货承诺',
  `shop_shiyong` int(11) NOT NULL DEFAULT 0 COMMENT '试用中心',
  `shop_shiti` int(11) NOT NULL DEFAULT 0 COMMENT '实体验证',
  `shop_xiaoxie` int(11) NOT NULL DEFAULT 0 COMMENT '消协保证',
  `shop_free_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '商家配送时间',
  `shop_sales` int(11) NOT NULL DEFAULT 0 COMMENT '店铺销量',
  `shop_adv` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺广告图',
  `account` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户实际余额',
  `account_withdraw` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已提现金额',
  `account_withdraw_apply` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '申请提现中金额',
  `province` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `province_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '省名称',
  `city` int(11) NOT NULL DEFAULT 0 COMMENT '城市id',
  `city_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '城市名称',
  `district` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `district_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '区县地址',
  `community` int(11) NOT NULL DEFAULT 0 COMMENT '乡镇地址id',
  `community_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '乡镇地址名称',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '完整地址',
  `longitude` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `sub_num` int(11) NOT NULL DEFAULT 0 COMMENT '关注会员数',
  `shop_open_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺申请续签费用',
  `email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '开店时间',
  `store_settlement_time` int(11) NOT NULL DEFAULT 0 COMMENT '门店最后结算时间',
  `work_week` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '工作日',
  `region_id` int(11) NULL DEFAULT 0 COMMENT '区域ID',
  `can_id` int(11) NULL DEFAULT 0 COMMENT '商会ID',
  `is_admin` tinyint(4) NULL DEFAULT 0 COMMENT '是否总平台:1=是',
  `huifu_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `points` int(11) NULL DEFAULT 0,
  `deposit_status` tinyint(2) NULL DEFAULT 0 COMMENT '是否已经缴纳了保证金0、未缴纳1、已缴纳',
  `deposit_amount` float(10, 2) NULL DEFAULT 0.00 COMMENT '保证金金额',
  `zlr_employee_id` int(11) NULL DEFAULT 0 COMMENT '主理人员工id',
  `shop_mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '主理人关联手机号，多个商家可切换',
  PRIMARY KEY (`site_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop
-- ----------------------------

-- ----------------------------
-- Table structure for shop_accept_message
-- ----------------------------
DROP TABLE IF EXISTS `shop_accept_message`;
CREATE TABLE `shop_accept_message`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id（接受消息的会员id）',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '类型（0统一设置   1单独设置）',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '消息关键字（针对单独设置有效）',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商家接受消息设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_accept_message
-- ----------------------------

-- ----------------------------
-- Table structure for shop_account
-- ----------------------------
DROP TABLE IF EXISTS `shop_account`;
CREATE TABLE `shop_account`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `account_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'order' COMMENT '类型',
  `account_data` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `from_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '来源类型',
  `type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `relate_tag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '说明',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺账户记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_account
-- ----------------------------

-- ----------------------------
-- Table structure for shop_address
-- ----------------------------
DROP TABLE IF EXISTS `shop_address`;
CREATE TABLE `shop_address`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `contact_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机号',
  `postcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮政编码',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '县',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '乡镇',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收票地址',
  `is_return` tinyint(1) NOT NULL DEFAULT 0 COMMENT '退货地址',
  `is_return_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是默认退货地址',
  `is_delivery` tinyint(1) NOT NULL DEFAULT 0 COMMENT '发货地址',
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商家地址库' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_address
-- ----------------------------

-- ----------------------------
-- Table structure for shop_apply
-- ----------------------------
DROP TABLE IF EXISTS `shop_apply`;
CREATE TABLE `shop_apply`  (
  `apply_id` int(11) NOT NULL AUTO_INCREMENT,
  `apply_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名称 取昵称字段',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `cert_id` int(11) NOT NULL DEFAULT 0 COMMENT '认证信息',
  `shop_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请店铺名称',
  `apply_state` int(11) NOT NULL DEFAULT 1 COMMENT '申请状态 1. 待审核 2. 财务凭据审核中  3. 开店通过 -1.审核失败 -2 财务审核拒绝',
  `apply_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员审核信息',
  `apply_year` int(11) NOT NULL DEFAULT 1 COMMENT '开店时长(年)',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分类名称',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺分类id',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分组名称',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 店铺分组ID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请店铺等级',
  `level_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请店铺等级名称',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证说明',
  `paying_deposit` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `paying_apply` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '开店费用',
  `paying_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核通过时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建成功时间',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_apply
-- ----------------------------

-- ----------------------------
-- Table structure for shop_can
-- ----------------------------
DROP TABLE IF EXISTS `shop_can`;
CREATE TABLE `shop_can`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商会名称',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商会列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_can
-- ----------------------------

-- ----------------------------
-- Table structure for shop_category
-- ----------------------------
DROP TABLE IF EXISTS `shop_category`;
CREATE TABLE `shop_category`  (
  `category_id` int(11) NOT NULL AUTO_INCREMENT,
  `category_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `baozheng_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `category_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '分类图标',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_category
-- ----------------------------

-- ----------------------------
-- Table structure for shop_cert
-- ----------------------------
DROP TABLE IF EXISTS `shop_cert`;
CREATE TABLE `shop_cert`  (
  `cert_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id（申请为0）',
  `cert_type` int(11) NOT NULL DEFAULT 0 COMMENT '申请类型1.个人2.公司',
  `company_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司名称',
  `company_province_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在省',
  `company_city_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在市',
  `company_district_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在区/县',
  `company_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司地址',
  `company_full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司完整地址',
  `contacts_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `contacts_mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机',
  `contacts_card_no` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人身份证',
  `contacts_card_electronic_1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人手持身份证电子版',
  `contacts_card_electronic_2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证正面',
  `contacts_card_electronic_3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证反面',
  `business_licence_number` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '统一社会信用码',
  `business_licence_number_electronic` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营业执照电子版',
  `business_sphere` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '法定经营范围',
  `taxpayer_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纳税人识别号',
  `general_taxpayer` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '一般纳税人证明',
  `tax_registration_certificate` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '税务登记证号',
  `tax_registration_certificate_electronic` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '税务登记证号电子版',
  `bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行开户名',
  `bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司银行账号',
  `bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开户银行支行名称',
  `bank_address` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开户银行所在地',
  `bank_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支行联行号',
  `bank_type` int(11) NOT NULL DEFAULT 1 COMMENT '结算账户类型  1银行卡 2 支付宝 ',
  `settlement_bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行开户名',
  `settlement_bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行支行名称',
  `settlement_bank_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行所在地',
  PRIMARY KEY (`cert_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺认证表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_cert
-- ----------------------------

-- ----------------------------
-- Table structure for shop_deposit
-- ----------------------------
DROP TABLE IF EXISTS `shop_deposit`;
CREATE TABLE `shop_deposit`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `deposit_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '支付金额',
  `pay_account_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付银行名称',
  `pay_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付编码',
  `pay_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付凭据',
  `pay_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付凭据说明',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '审核状态0待审核1.审核成功',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `pay_status` tinyint(2) NULL DEFAULT 0 COMMENT '保证金支付状态0、未支付1、已支付',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺保证金' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_deposit
-- ----------------------------

-- ----------------------------
-- Table structure for shop_deposit_order
-- ----------------------------
DROP TABLE IF EXISTS `shop_deposit_order`;
CREATE TABLE `shop_deposit_order`  (
  `order_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NULL DEFAULT 0,
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '价格',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `out_trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单流水号',
  `status` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '支付状态（1未支付 2已支付）',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '支付时间',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商家名称',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商家logo',
  `member_id` int(11) NULL DEFAULT 0 COMMENT '登录用户id',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商家缴纳保证金' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_deposit_order
-- ----------------------------

-- ----------------------------
-- Table structure for shop_employee
-- ----------------------------
DROP TABLE IF EXISTS `shop_employee`;
CREATE TABLE `shop_employee`  (
  `employee_id` int(11) NOT NULL AUTO_INCREMENT,
  `shop_id` int(11) NULL DEFAULT NULL COMMENT '店铺id',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '员工姓名',
  `mobile` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '员工手机号',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '0',
  `employee_status` tinyint(2) NULL DEFAULT 0 COMMENT '员工状态0、正常1、禁用',
  `is_deleted` tinyint(2) NULL DEFAULT 0 COMMENT '删除状态0、正常1、已删除',
  `member_id` int(11) NULL DEFAULT 0 COMMENT '关联用户id',
  `employeeID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `is_manager` tinyint(2) NULL DEFAULT 0 COMMENT '是否是主理人0、否1、是',
  `bymember_id` int(11) NULL DEFAULT 0,
  `website_id` int(11) NULL DEFAULT 0 COMMENT '城市id',
  `headimg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像',
  `init_level` int(11) NULL DEFAULT 1 COMMENT '员工等级',
  PRIMARY KEY (`employee_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 84 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '店铺员工表（只能企业法人进行添加）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_employee
-- ----------------------------

-- ----------------------------
-- Table structure for shop_group
-- ----------------------------
DROP TABLE IF EXISTS `shop_group`;
CREATE TABLE `shop_group`  (
  `group_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `is_own` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺组名',
  `fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '年费标准',
  `menu_array` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '功能权限',
  `addon_array` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '营销插件',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `remark` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明信息',
  `is_experience` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是体验开店（0不是 1是）',
  PRIMARY KEY (`group_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺分组' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_group
-- ----------------------------

-- ----------------------------
-- Table structure for shop_heat
-- ----------------------------
DROP TABLE IF EXISTS `shop_heat`;
CREATE TABLE `shop_heat`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NULL DEFAULT 0,
  `store_id` int(11) NULL DEFAULT 0,
  `heat` int(11) NULL DEFAULT 0 COMMENT '热度',
  `create_time` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '品牌热度' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_heat
-- ----------------------------

-- ----------------------------
-- Table structure for shop_join
-- ----------------------------
DROP TABLE IF EXISTS `shop_join`;
CREATE TABLE `shop_join`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NULL DEFAULT 0 COMMENT '用户',
  `category_id` int(11) NULL DEFAULT 0 COMMENT '所属行业',
  `category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '所属行业',
  `site_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '品牌名称',
  `is_stall` tinyint(4) NULL DEFAULT 1 COMMENT '身份:1=老板,2=负责人',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '姓名',
  `mobile` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '手机号',
  `province_id` int(11) NULL DEFAULT 0 COMMENT '省',
  `city_id` int(11) NULL DEFAULT 0 COMMENT '市',
  `district_id` int(11) NULL DEFAULT 0 COMMENT '区',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址信息',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '详细地址',
  `status` enum('0','1','-1') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态值:0=待审核,1=已审核,-1=拒绝',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `refuse_reason` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商家入驻表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_join
-- ----------------------------

-- ----------------------------
-- Table structure for shop_level
-- ----------------------------
DROP TABLE IF EXISTS `shop_level`;
CREATE TABLE `shop_level`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺等级' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_level
-- ----------------------------

-- ----------------------------
-- Table structure for shop_member
-- ----------------------------
DROP TABLE IF EXISTS `shop_member`;
CREATE TABLE `shop_member`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺站点id',
  `subscribe_time` int(11) NOT NULL DEFAULT 0 COMMENT '关注时间',
  `is_subscribe` int(1) NOT NULL DEFAULT 1 COMMENT '是否关注 0未关注 1已关注',
  `cancel_time` int(11) NOT NULL DEFAULT 0 COMMENT '取消关注时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺会员关注管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_member
-- ----------------------------

-- ----------------------------
-- Table structure for shop_open_account
-- ----------------------------
DROP TABLE IF EXISTS `shop_open_account`;
CREATE TABLE `shop_open_account`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账单编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '费用',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '类型（1开店  2续签）',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联开店续签id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '时间',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应分站',
  `website_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分站名称',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站分成',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站结算id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺开店费用流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_open_account
-- ----------------------------

-- ----------------------------
-- Table structure for shop_region
-- ----------------------------
DROP TABLE IF EXISTS `shop_region`;
CREATE TABLE `shop_region`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区域名称',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '密码',
  `create_time` int(11) NULL DEFAULT 0,
  `type` tinyint(4) NULL DEFAULT 0 COMMENT '类型:1=省,2=市,3=区',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `site_id` int(11) NULL DEFAULT 0 COMMENT '区域site_id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商家城市表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_region
-- ----------------------------

-- ----------------------------
-- Table structure for shop_reopen
-- ----------------------------
DROP TABLE IF EXISTS `shop_reopen`;
CREATE TABLE `shop_reopen`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reopen_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站ID',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请会员id',
  `apply_state` int(11) NOT NULL DEFAULT 1 COMMENT '申请状态 1. 待审核 -1.审核失败 2.审核成功',
  `apply_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员审核信息',
  `apply_year` int(11) NOT NULL DEFAULT 1 COMMENT '开店时长(年)',
  `shop_group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分组名称',
  `shop_group_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 店铺分组ID',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证',
  `paying_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款金额',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核通过时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '完成时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺续签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_reopen
-- ----------------------------

-- ----------------------------
-- Table structure for shop_service
-- ----------------------------
DROP TABLE IF EXISTS `shop_service`;
CREATE TABLE `shop_service`  (
  `apply_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请站点名称',
  `service_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请服务类型',
  `service_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请服务类型名称',
  `status` int(11) NULL DEFAULT 0 COMMENT '申请状态0待审核1.已审核-1已拒绝',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '同意或者拒绝理由',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NULL DEFAULT 0 COMMENT '通过时间',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺申请服务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_service
-- ----------------------------

-- ----------------------------
-- Table structure for shop_settlement
-- ----------------------------
DROP TABLE IF EXISTS `shop_settlement`;
CREATE TABLE `shop_settlement`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `settlement_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `period_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算周期id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款抽成',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台抽成',
  `refund_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺退款金额',
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结束时间',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金支出',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站分成',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算id',
  `platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额',
  `refund_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额(退款部分)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `settlement_no_index`(`settlement_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16338 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for shop_settlement_period
-- ----------------------------
DROP TABLE IF EXISTS `shop_settlement_period`;
CREATE TABLE `shop_settlement_period`  (
  `period_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `period_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `shop_num` int(11) NOT NULL DEFAULT 0 COMMENT '结算店铺数量',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款总金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台抽成',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结算时间',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站总分成',
  `platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额',
  `refund_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额(退款部分)',
  PRIMARY KEY (`period_id`) USING BTREE,
  UNIQUE INDEX `period_no`(`period_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 222 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_settlement_period
-- ----------------------------

-- ----------------------------
-- Table structure for shop_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `shop_withdraw`;
CREATE TABLE `shop_withdraw`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `withdraw_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现流水编号',
  `site_id` int(11) NOT NULL DEFAULT 0,
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机',
  `bank_type` int(11) NOT NULL DEFAULT 0 COMMENT '账户类型1.银行2.支付宝',
  `settlement_bank_account_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行开户名',
  `settlement_bank_account_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司支行名',
  `settlement_bank_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行所在地',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现金额',
  `apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `payment_time` int(11) NOT NULL DEFAULT 0 COMMENT '转账时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态0待审核1.待转账2已转账 -1拒绝',
  `memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后修改时间',
  `is_period` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否周期结算',
  `period_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算周期',
  `period_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算周期名称',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上传付款凭证',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `req_seq_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '请求流水号',
  `req_date` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '	请求日期',
  `hf_seq_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '汇付全局流水号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺提现表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_withdraw
-- ----------------------------

-- ----------------------------
-- Table structure for shop_withdraw_period
-- ----------------------------
DROP TABLE IF EXISTS `shop_withdraw_period`;
CREATE TABLE `shop_withdraw_period`  (
  `period_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '账期时间',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '结算金额',
  `shop_num` int(11) NOT NULL DEFAULT 0 COMMENT '结算店铺数量',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期截止时间',
  `period_type` int(11) NOT NULL DEFAULT 3 COMMENT '结算周期类型',
  PRIMARY KEY (`period_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺结算账期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shop_withdraw_period
-- ----------------------------

-- ----------------------------
-- Table structure for shopcompoent_category
-- ----------------------------
DROP TABLE IF EXISTS `shopcompoent_category`;
CREATE TABLE `shopcompoent_category`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `first_cat_id` int(11) NOT NULL DEFAULT 0 COMMENT '第一级类目ID',
  `second_cat_id` int(11) NOT NULL DEFAULT 0 COMMENT '第二级类目ID',
  `third_cat_id` int(11) NOT NULL DEFAULT 0 COMMENT '第三级类目ID',
  `first_cat_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '一级类目名称',
  `second_cat_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '二级类目名称',
  `third_cat_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '三级类目名称',
  `qualification` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类目资质',
  `qualification_type` int(1) NOT NULL DEFAULT 0 COMMENT '类目资质类型,0:不需要,1:必填,2:选填',
  `product_qualification_type` int(1) NOT NULL DEFAULT 0 COMMENT '商品资质类型,0:不需要,1:必填,2:选填',
  `product_qualification` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品资质',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小程序交易组件类目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shopcompoent_category
-- ----------------------------

-- ----------------------------
-- Table structure for shopcompoent_category_audit
-- ----------------------------
DROP TABLE IF EXISTS `shopcompoent_category_audit`;
CREATE TABLE `shopcompoent_category_audit`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `third_cat_id` int(11) NOT NULL DEFAULT 0 COMMENT '第三级类目ID',
  `certificate` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类目资质材料',
  `qualification_pics` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品资质材料',
  `audit_id` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '审核ID',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `status` int(1) NOT NULL DEFAULT 0 COMMENT '审核状态, 0：审核中，1：审核成功，9：审核拒绝',
  `reject_reason` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小程序交易组件类目审核表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shopcompoent_category_audit
-- ----------------------------

-- ----------------------------
-- Table structure for shopcompoent_goods
-- ----------------------------
DROP TABLE IF EXISTS `shopcompoent_goods`;
CREATE TABLE `shopcompoent_goods`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点ID',
  `out_product_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家自定义商品ID',
  `third_cat_id` int(11) NOT NULL DEFAULT 0 COMMENT '第三级类目ID',
  `cat_name` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类目名称',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  `product_id` int(11) NOT NULL DEFAULT 0 COMMENT '交易组件平台内部商品ID',
  `edit_status` int(11) NOT NULL DEFAULT 0 COMMENT '商品草稿状态, 0：初始值，1：编辑中，2：审核中，3：审核失败，4：审核成功',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '商品线上状态, 0:初始值,5:上架,11:自主下架,13:违规下架/风控系统下架',
  `info_version` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '预留字段，用于版本控制',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `audit_time` int(100) NOT NULL DEFAULT 0 COMMENT '审核时间',
  `reject_reason` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小程序交易组件商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shopcompoent_goods
-- ----------------------------

-- ----------------------------
-- Table structure for shopcomponent_account
-- ----------------------------
DROP TABLE IF EXISTS `shopcomponent_account`;
CREATE TABLE `shopcomponent_account`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `wx_username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信号',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '视频号名称',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态 0 申请中  1已通过    -1 已拒绝  ',
  `refuse` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '视频号店铺微信号申请' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shopcomponent_account
-- ----------------------------

-- ----------------------------
-- Table structure for sign_member_record
-- ----------------------------
DROP TABLE IF EXISTS `sign_member_record`;
CREATE TABLE `sign_member_record`  (
  `signin_id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NULL DEFAULT 0,
  `shop_id` int(11) NULL DEFAULT 0,
  `create_time` int(11) NULL DEFAULT 0 COMMENT '签到时间',
  `rewardnum` int(11) NULL DEFAULT 0 COMMENT '得到的奖励值',
  `rewardname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `rewardtype` tinyint(2) NULL DEFAULT 0,
  `rewardtxt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `rules_id` int(11) NULL DEFAULT 0,
  `sign_day` int(11) NULL DEFAULT 0,
  `sign_rounds` int(11) NULL DEFAULT 0 COMMENT '第几轮签到，一轮完成后进行下一轮',
  `goods_id` int(11) NULL DEFAULT 0,
  `order_id` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`signin_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sign_member_record
-- ----------------------------

-- ----------------------------
-- Table structure for sign_rules
-- ----------------------------
DROP TABLE IF EXISTS `sign_rules`;
CREATE TABLE `sign_rules`  (
  `rules_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` int(2) NULL DEFAULT 0 COMMENT '第几天',
  `reward_type` tinyint(2) NULL DEFAULT NULL COMMENT '奖励类型1、积分2、元3、礼包',
  `reward_typename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖励类型名称',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '添加时间',
  `reward_value` int(11) NULL DEFAULT 0 COMMENT '奖励金额',
  `goods_id` int(11) NOT NULL DEFAULT 0,
  `order_id` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`rules_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sign_rules
-- ----------------------------

-- ----------------------------
-- Table structure for site
-- ----------------------------
DROP TABLE IF EXISTS `site`;
CREATE TABLE `site`  (
  `site_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '站点id',
  `site_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点类型',
  PRIMARY KEY (`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 100 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '站点基础表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site
-- ----------------------------

-- ----------------------------
-- Table structure for site_address
-- ----------------------------
DROP TABLE IF EXISTS `site_address`;
CREATE TABLE `site_address`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `mobile` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `area_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `telephone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `province_id` int(11) NOT NULL DEFAULT 0,
  `city_id` int(11) NOT NULL DEFAULT 0,
  `district_id` int(11) NOT NULL DEFAULT 0,
  `community_id` int(11) NOT NULL DEFAULT 0,
  `province_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `city_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `district_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `community_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '镇（街道）名称',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否是默认地址',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商家地址' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_address
-- ----------------------------

-- ----------------------------
-- Table structure for site_diy_view
-- ----------------------------
DROP TABLE IF EXISTS `site_diy_view`;
CREATE TABLE `site_diy_view`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `addon_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '插件名称',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `value` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '配置值',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'admin' COMMENT '应用模块:admin、shop、city、store',
  `icon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图标',
  `template_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板id',
  `click_num` int(11) NOT NULL DEFAULT 0 COMMENT '浏览量',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_nc_site_diy_view`(`site_id`, `name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 177 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺自定义模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_diy_view
-- ----------------------------

-- ----------------------------
-- Table structure for site_floor
-- ----------------------------
DROP TABLE IF EXISTS `site_floor`;
CREATE TABLE `site_floor`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '数据ID',
  `index` int(3) NOT NULL DEFAULT 0 COMMENT '楼层索引',
  `title` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '楼层标题',
  `block_id` int(11) NOT NULL DEFAULT 0 COMMENT '模板ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '状态（0：禁用，1：启用）',
  `config` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '配置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '网店楼层定义表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_floor
-- ----------------------------

-- ----------------------------
-- Table structure for site_member_message
-- ----------------------------
DROP TABLE IF EXISTS `site_member_message`;
CREATE TABLE `site_member_message`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站内信类型  service客服消息   group会员群发  system系统消息  ',
  `total_num` int(11) NOT NULL DEFAULT 0 COMMENT '消息数量',
  `is_seed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否查看过 0未查看  1 已查看',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标题  最后一条会重置标题',
  `content` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '缩略内容  最后一条会重置缩略内容',
  `is_top` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否置顶 0 无需置顶  1 置顶',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `seed_time` int(11) NOT NULL DEFAULT 0 COMMENT '接收时间',
  `sub_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '具体的业务类型',
  `seed_num` int(11) NOT NULL DEFAULT 0 COMMENT '已读数量',
  `is_delete` int(11) NOT NULL DEFAULT 0 COMMENT '是否被删除',
  `delete_time` int(11) NOT NULL DEFAULT 0 COMMENT '删除时间',
  `send_time` int(11) NOT NULL DEFAULT 0 COMMENT '送达时间',
  `remind_num` int(11) NOT NULL DEFAULT 0 COMMENT '提醒显示数量',
  `delete_num` int(11) NOT NULL DEFAULT 0 COMMENT '删除数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员收到站内信的个人消息记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_member_message
-- ----------------------------

-- ----------------------------
-- Table structure for site_member_sub_message
-- ----------------------------
DROP TABLE IF EXISTS `site_member_sub_message`;
CREATE TABLE `site_member_sub_message`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站内信类型  service客服消息   group会员群发  system系统消息  ',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '标题',
  `content` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '内容',
  `message_json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '消息内容',
  `event_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定义点击行为  跳转链接   固定跳转   公告(可以使富文本 也可能是是个公共的界面(占用文章))',
  `link` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '跳转的链接 ',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `records_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联消息记录id',
  `is_seed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '接收状态 0未接收 1 已接收',
  `seed_time` int(11) NOT NULL DEFAULT 0 COMMENT '接收时间',
  `scene` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '场景',
  `sended_status` int(11) NOT NULL DEFAULT 0 COMMENT '送达状态 0未送达  1已送达',
  `sended_time` int(11) NOT NULL DEFAULT 0 COMMENT '送达时间',
  `text` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '消息页展示内容',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态  0未送达  1已送达  2已接收',
  `json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '附属内容',
  `is_delete` int(11) NOT NULL DEFAULT 0 COMMENT '是否被删除',
  `delete_time` int(11) NOT NULL DEFAULT 0 COMMENT '删除时间',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '导航图',
  `sub_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '次级业务类型',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '会员收到站内信的个人消息副表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_member_sub_message
-- ----------------------------

-- ----------------------------
-- Table structure for site_message_records
-- ----------------------------
DROP TABLE IF EXISTS `site_message_records`;
CREATE TABLE `site_message_records`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站内信类型  service客服消息   group会员群发  system系统消息  ',
  `total_num` int(11) NOT NULL DEFAULT 0 COMMENT '消息数量',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标题  最后一条会重置标题',
  `content` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '缩略内容  最后一条会重置缩略内容',
  `addon` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '插件',
  `event_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '定义点击事件',
  `scene` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '限制使用场景 h5  移动手机端  pc  pc电脑端  applet  小程序  如果为空的话为全场景',
  `json` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '附属信息  各自业务各自调用',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `is_timing` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否定时 0 立即发送 1已经发送 ',
  `timing` int(11) NOT NULL DEFAULT 0 COMMENT '定时',
  `message_json` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '消息数据json',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '是否已发送 0 创建中  1 待发送  2 已发送  -1 已拒绝',
  `error_msg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '错误原因',
  `link` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '链接',
  `text` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '消息也展示内容',
  `is_search` int(11) NOT NULL DEFAULT 0 COMMENT '是否参与筛选  0 不参与  1 参与筛选',
  `image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '导航图',
  `sub_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '次级业务类型',
  `send_num` int(11) NOT NULL DEFAULT 0 COMMENT '已发送数量',
  `send_time` int(11) NOT NULL DEFAULT 0 COMMENT '发送时间',
  `seed_num` int(11) NOT NULL DEFAULT 0 COMMENT '已读数量',
  `delete_num` int(11) NOT NULL DEFAULT 0 COMMENT '删除消息数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '站内信' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of site_message_records
-- ----------------------------

-- ----------------------------
-- Table structure for sms_template
-- ----------------------------
DROP TABLE IF EXISTS `sms_template`;
CREATE TABLE `sms_template`  (
  `template_id` int(11) NOT NULL AUTO_INCREMENT,
  `tem_id` int(11) NOT NULL DEFAULT 0 COMMENT '返回的模板id',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `template_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '模板类型（1验证码  2行业通知  3营销推广 ）',
  `template_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `template_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板内容',
  `param_json` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '模板变量json',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '启用状态（1 启用，0 禁用）',
  `audit_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审核状态（0 未审核，1 待审核，2 审核通过， 3 审核不通过）',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`template_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 AVG_ROW_LENGTH = 564 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '牛云短信模板' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sms_template
-- ----------------------------

-- ----------------------------
-- Table structure for stat_shop
-- ----------------------------
DROP TABLE IF EXISTS `stat_shop`;
CREATE TABLE `stat_shop`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NULL DEFAULT 0 COMMENT '站点id',
  `year` int(11) NOT NULL DEFAULT 0 COMMENT '年',
  `month` int(11) NOT NULL DEFAULT 0 COMMENT '月',
  `day` int(11) NOT NULL DEFAULT 0 COMMENT '日',
  `day_time` int(11) NOT NULL DEFAULT 0 COMMENT '当日时间',
  `order_total` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `shipping_total` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_total` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `order_pay_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单总数',
  `goods_pay_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单商品总数',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `collect_shop` int(11) NOT NULL DEFAULT 0 COMMENT '店铺收藏量',
  `collect_goods` int(11) NOT NULL DEFAULT 0 COMMENT '商品收藏量',
  `visit_count` int(11) NOT NULL DEFAULT 0 COMMENT '浏览量',
  `order_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单量（总）',
  `goods_count` int(11) NOT NULL DEFAULT 0 COMMENT '订单商品量（总）',
  `add_goods_count` int(11) NOT NULL DEFAULT 0 COMMENT '添加商品数',
  `member_count` int(11) NOT NULL DEFAULT 0 COMMENT '会员统计',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `year`(`site_id`, `year`, `month`, `day`) USING BTREE,
  INDEX `IDX_stat_shop_day`(`day`) USING BTREE,
  INDEX `IDX_stat_shop_day_time`(`day_time`) USING BTREE,
  INDEX `IDX_stat_shop_month`(`month`) USING BTREE,
  INDEX `IDX_stat_shop_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_stat_shop_year`(`year`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1136 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of stat_shop
-- ----------------------------

-- ----------------------------
-- Table structure for store
-- ----------------------------
DROP TABLE IF EXISTS `store`;
CREATE TABLE `store`  (
  `store_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '门店站点id',
  `store_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店名称',
  `telphone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `store_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店图片',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `longitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `is_pickup` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否启用自提',
  `is_o2o` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否启用本地配送',
  `open_date` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营业时间',
  `o2o_fee_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '配送费用设置',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店管理员',
  `order_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '付款后订单金额',
  `order_complete_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单完成-订单金额',
  `order_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单数',
  `order_complete_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单完成数量',
  `is_frozen` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否冻结0-未冻结 1已冻结',
  `store_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '门店编号id',
  `store_desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '门店描述',
  `store_logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '门店logo',
  PRIMARY KEY (`store_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 82 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '线下门店表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store
-- ----------------------------

-- ----------------------------
-- Table structure for store_goods
-- ----------------------------
DROP TABLE IF EXISTS `store_goods`;
CREATE TABLE `store_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `store_goods_stock` int(11) NOT NULL DEFAULT 0 COMMENT '商品库存',
  `store_sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '门店商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_goods
-- ----------------------------

-- ----------------------------
-- Table structure for store_goods_sku
-- ----------------------------
DROP TABLE IF EXISTS `store_goods_sku`;
CREATE TABLE `store_goods_sku`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `store_stock` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存',
  `store_sale_num` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 345 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '门店sku表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_goods_sku
-- ----------------------------

-- ----------------------------
-- Table structure for store_member
-- ----------------------------
DROP TABLE IF EXISTS `store_member`;
CREATE TABLE `store_member`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店站点id',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款后-消费金额',
  `order_complete_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单完成-消费金额',
  `order_num` int(11) NOT NULL DEFAULT 0 COMMENT '付款后-消费次数',
  `order_complete_num` int(11) NOT NULL DEFAULT 0 COMMENT '订单完成-消费次数',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '门店会员管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_member
-- ----------------------------

-- ----------------------------
-- Table structure for store_settlement
-- ----------------------------
DROP TABLE IF EXISTS `store_settlement`;
CREATE TABLE `store_settlement`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `settlement_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `store_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '门店名称',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款抽成',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台抽成',
  `refund_shop_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺退款金额',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结束时间',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金支出',
  `is_settlement` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否结算',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `offline_order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '线下支付的订单金额',
  `offline_refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '线下退款金额',
  `platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额',
  `refund_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台优惠券平台承担金额(退款部分)',
  `offline_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `offline_refund_platform_coupon_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 541 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for store_stock_import
-- ----------------------------
DROP TABLE IF EXISTS `store_stock_import`;
CREATE TABLE `store_stock_import`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0,
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `filename` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件名称',
  `path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `sku_num` int(11) NOT NULL DEFAULT 0 COMMENT '导入的sku商品数',
  `error_num` int(11) NOT NULL DEFAULT 0 COMMENT '失败数量',
  `create_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = ' 门店库存导入批量修改' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_stock_import
-- ----------------------------

-- ----------------------------
-- Table structure for store_stock_import_log
-- ----------------------------
DROP TABLE IF EXISTS `store_stock_import_log`;
CREATE TABLE `store_stock_import_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) NOT NULL DEFAULT 0 COMMENT '门店id',
  `file_id` int(11) NOT NULL DEFAULT 0 COMMENT '文件id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku名称',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '库存（增/减）',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0成功 -1失败）',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '原因',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '门店导入库存失败记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of store_stock_import_log
-- ----------------------------

-- ----------------------------
-- Table structure for supplier
-- ----------------------------
DROP TABLE IF EXISTS `supplier`;
CREATE TABLE `supplier`  (
  `supplier_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_site_id` int(10) NOT NULL DEFAULT 0 COMMENT '供应商站点',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商logo',
  `desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商简介',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商关键字',
  `supplier_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商地址',
  `supplier_email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商邮箱',
  `supplier_phone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `supplier_qq` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商qq',
  `supplier_weixin` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人微信号',
  `account` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户金额',
  `account_withdraw` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已提现金额',
  `account_withdraw_apply` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现中金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'admin' COMMENT '供应商管理员',
  `settlement_bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行开户名',
  `settlement_bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行支行名称',
  `settlement_bank_address` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行所在地',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT '分组id',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分组名称',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商类别',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺类别名称',
  `expire_time` int(11) NOT NULL DEFAULT 0 COMMENT '过期时间',
  `cert_id` int(11) UNSIGNED NOT NULL COMMENT '凭证ID',
  `open_fee` decimal(10, 2) UNSIGNED NOT NULL COMMENT '开店费用',
  `supply_desccredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '描述分值',
  `supply_servicecredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '服务分值',
  `supply_deliverycredit` decimal(10, 1) NOT NULL DEFAULT 5.0 COMMENT '发货速度分值',
  `bond` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `supplier_contact` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `province` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '省id',
  `province_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '省名称',
  `city` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市id',
  `city_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '城市名称',
  `district` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '区县id',
  `district_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '区县地址',
  `community` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '乡镇地址id',
  `community_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '乡镇地址名称',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '完整地址',
  `service_qtian` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_zhping` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_erxiaoshi` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_tuihuo` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_shiyong` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_shiti` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `service_xiaoxie` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `end_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '关闭时间',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站id',
  `longitude` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `latitude` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`supplier_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supplier
-- ----------------------------

-- ----------------------------
-- Table structure for supply_account
-- ----------------------------
DROP TABLE IF EXISTS `supply_account`;
CREATE TABLE `supply_account`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `account_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'order' COMMENT '类型',
  `account_data` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `from_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '来源类型',
  `type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `relate_tag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '说明',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商账户记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_account
-- ----------------------------

-- ----------------------------
-- Table structure for supply_adv
-- ----------------------------
DROP TABLE IF EXISTS `supply_adv`;
CREATE TABLE `supply_adv`  (
  `adv_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `ap_id` int(11) NOT NULL DEFAULT 0 COMMENT '广告位id',
  `adv_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告内容描述',
  `adv_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告链接',
  `adv_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告内容图片',
  `slide_sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序号',
  `background` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '#FFFFFF' COMMENT '背景色',
  PRIMARY KEY (`adv_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商广告表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_adv
-- ----------------------------

-- ----------------------------
-- Table structure for supply_adv_position
-- ----------------------------
DROP TABLE IF EXISTS `supply_adv_position`;
CREATE TABLE `supply_adv_position`  (
  `ap_id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广告位置id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `ap_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告位置名',
  `ap_intro` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告位简介',
  `ap_height` int(10) NOT NULL DEFAULT 0 COMMENT '广告位高度',
  `ap_width` int(10) NOT NULL DEFAULT 0 COMMENT '广告位宽度',
  `default_content` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `ap_background_color` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '#FFFFFF' COMMENT '广告位背景色 默认白色',
  `keyword` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键字',
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ap_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商广告位表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_adv_position
-- ----------------------------

-- ----------------------------
-- Table structure for supply_apply
-- ----------------------------
DROP TABLE IF EXISTS `supply_apply`;
CREATE TABLE `supply_apply`  (
  `apply_id` int(11) NOT NULL AUTO_INCREMENT,
  `apply_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请会员id',
  `member_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '会员名称 取昵称字段',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `cert_id` int(11) NOT NULL DEFAULT 0 COMMENT '认证信息',
  `supplier_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请店铺名称',
  `apply_state` int(11) NOT NULL DEFAULT 1 COMMENT '申请状态 1. 待审核 2. 财务凭据审核中  3. 开店通过 -1.审核失败 -2 财务审核拒绝',
  `apply_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员审核信息',
  `apply_year` int(11) NOT NULL DEFAULT 1 COMMENT '开店时长(年)',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分类名称',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺分类id',
  `group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分组名称',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 店铺分组ID',
  `level_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请店铺等级',
  `level_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请店铺等级名称',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证说明',
  `paying_deposit` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `paying_apply` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '开店费用',
  `paying_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核通过时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建成功时间',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_apply
-- ----------------------------

-- ----------------------------
-- Table structure for supply_category
-- ----------------------------
DROP TABLE IF EXISTS `supply_category`;
CREATE TABLE `supply_category`  (
  `category_id` int(11) NOT NULL AUTO_INCREMENT,
  `category_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `baozheng_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商行业分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_category
-- ----------------------------

-- ----------------------------
-- Table structure for supply_cert
-- ----------------------------
DROP TABLE IF EXISTS `supply_cert`;
CREATE TABLE `supply_cert`  (
  `cert_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id（申请为0）',
  `cert_type` int(11) NOT NULL DEFAULT 0 COMMENT '申请类型1.个人2.公司',
  `company_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司名称',
  `company_province_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在省',
  `company_city_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在市',
  `company_district_id` int(11) NOT NULL DEFAULT 0 COMMENT '公司所在区/县',
  `company_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司地址',
  `company_full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司完整地址',
  `contacts_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `contacts_mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机',
  `contacts_card_no` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人身份证',
  `contacts_card_electronic_1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人手持身份证电子版',
  `contacts_card_electronic_2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证正面',
  `contacts_card_electronic_3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '申请人身份证反面',
  `business_licence_number` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '统一社会信用码',
  `business_licence_number_electronic` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '营业执照电子版',
  `business_sphere` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '法定经营范围',
  `taxpayer_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '纳税人识别号',
  `general_taxpayer` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '一般纳税人证明',
  `tax_registration_certificate` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '税务登记证号',
  `tax_registration_certificate_electronic` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '税务登记证号电子版',
  `bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行开户名',
  `bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '公司银行账号',
  `bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开户银行支行名称',
  `bank_address` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开户银行所在地',
  `bank_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支行联行号',
  `bank_type` int(11) NOT NULL DEFAULT 1 COMMENT '结算账户类型  1银行卡 2 支付宝 ',
  `settlement_bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行开户名',
  `settlement_bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行支行名称',
  `settlement_bank_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行所在地',
  PRIMARY KEY (`cert_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺认证表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_cert
-- ----------------------------

-- ----------------------------
-- Table structure for supply_deposit
-- ----------------------------
DROP TABLE IF EXISTS `supply_deposit`;
CREATE TABLE `supply_deposit`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `deposit_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '支付金额',
  `pay_account_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付银行名称',
  `pay_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付编码',
  `pay_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付凭据',
  `pay_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付凭据说明',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '审核状态0待审核1.审核成功',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺保证金' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_deposit
-- ----------------------------

-- ----------------------------
-- Table structure for supply_goods
-- ----------------------------
DROP TABLE IF EXISTS `supply_goods`;
CREATE TABLE `supply_goods`  (
  `goods_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `goods_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品种类1.实物商品2.虚拟商品3.卡券商品',
  `goods_class_name` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品种类',
  `goods_attr_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品类型id',
  `goods_attr_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属分站id',
  `category_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品分类id,逗号隔开',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属分类名称',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  `brand_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属品牌名称',
  `goods_image` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品主图路径',
  `goods_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品详情',
  `is_own` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `goods_state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '商品状态（1.正常0下架）',
  `verify_state` int(11) NOT NULL DEFAULT 1 COMMENT '审核状态（1 已审核 0 待审核 10 违规下架 -1 审核中 -2 审核失败）',
  `verify_state_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品违规或审核失败说明',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格（取第一个sku）',
  `market_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '市场价格（取第一个sku）',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价（取第一个sku）',
  `goods_stock` int(11) NOT NULL DEFAULT 0 COMMENT '商品库存（总和）',
  `goods_stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT '库存预警',
  `is_virtual` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否虚拟类商品（0实物1.虚拟）',
  `virtual_indate` int(11) NOT NULL DEFAULT 1 COMMENT '虚拟商品有效期',
  `is_free_shipping` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否免邮',
  `shipping_template` int(11) NOT NULL DEFAULT 0 COMMENT '指定运费模板',
  `goods_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品规格格式',
  `goods_attr_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品属性格式',
  `is_delete` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已经删除',
  `introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '促销语',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键词',
  `unit` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分佣比率(按照分类)',
  `video_url` varchar(555) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '视频',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '评价数',
  `evaluate_shaitu` int(11) NOT NULL DEFAULT 0 COMMENT '评价晒图数',
  `evaluate_shipin` int(11) NOT NULL DEFAULT 0 COMMENT '评价视频数',
  `evaluate_zhuiping` int(11) NOT NULL DEFAULT 0 COMMENT '评价追评数',
  `evaluate_haoping` int(11) NOT NULL DEFAULT 0 COMMENT '评价好评数',
  `evaluate_zhongping` int(11) NOT NULL DEFAULT 0 COMMENT '评价中评数',
  `evaluate_chaping` int(11) NOT NULL DEFAULT 0 COMMENT '评价差评数',
  `is_fenxiao` tinyint(1) NOT NULL DEFAULT 0 COMMENT '参与分销（0不参与 1参与）',
  `fenxiao_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '分销佣金类型（1默认  2自行设置）',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '供应商名称',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `min_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最低价',
  `max_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最高价',
  `min_num` int(11) NOT NULL DEFAULT 0,
  `category_json` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类json字符串',
  `timer_on` int(11) NOT NULL DEFAULT 0 COMMENT '定时上架',
  `timer_off` int(11) NOT NULL DEFAULT 0 COMMENT '定时下架',
  PRIMARY KEY (`goods_id`) USING BTREE,
  INDEX `IDX_supply_goods_brand_id`(`brand_id`) USING BTREE,
  INDEX `IDX_supply_goods_category_id`(`category_id`) USING BTREE,
  INDEX `IDX_supply_goods_goods_class`(`goods_class`) USING BTREE,
  INDEX `IDX_supply_goods_is_delete`(`is_delete`) USING BTREE,
  INDEX `IDX_supply_goods_is_own_shop`(`is_own`) USING BTREE,
  INDEX `IDX_supply_goods_sku_id`(`sku_id`) USING BTREE,
  INDEX `IDX_supply_goods_sort`(`sort`) USING BTREE,
  INDEX `IDX_supply_goods_website_id`(`website_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_goods
-- ----------------------------

-- ----------------------------
-- Table structure for supply_goods_cart
-- ----------------------------
DROP TABLE IF EXISTS `supply_goods_cart`;
CREATE TABLE `supply_goods_cart`  (
  `cart_id` int(11) NOT NULL AUTO_INCREMENT,
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '用户id',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '数量',
  PRIMARY KEY (`cart_id`) USING BTREE,
  INDEX `IDX_supply_goods_uid`(`uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '进货单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_goods_cart
-- ----------------------------

-- ----------------------------
-- Table structure for supply_goods_evaluate
-- ----------------------------
DROP TABLE IF EXISTS `supply_goods_evaluate`;
CREATE TABLE `supply_goods_evaluate`  (
  `evaluate_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单ID',
  `order_no` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单编号',
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单项ID',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价内容',
  `images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价图片',
  `explain_first` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '解释内容',
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '评价人id',
  `shop_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价人名称',
  `shop_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价人头像',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0表示不是 1表示是匿名评价',
  `scores` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-5分',
  `again_content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追加评价内容',
  `again_images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追评评价图片',
  `again_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '追加解释内容',
  `explain_type` int(11) NOT NULL DEFAULT 0 COMMENT '1好评2中评3差评',
  `is_show` int(1) NOT NULL DEFAULT 1 COMMENT '1显示 0隐藏',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '评价时间',
  `again_time` int(11) NOT NULL DEFAULT 0 COMMENT '追加评价时间',
  `supply_desccredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '描述分值',
  `supply_servicecredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '服务分值',
  `supply_deliverycredit` decimal(10, 2) NOT NULL DEFAULT 5.00 COMMENT '配送分值',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`evaluate_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商商品评价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_goods_evaluate
-- ----------------------------

-- ----------------------------
-- Table structure for supply_goods_sku
-- ----------------------------
DROP TABLE IF EXISTS `supply_goods_sku`;
CREATE TABLE `supply_goods_sku`  (
  `sku_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '商品sku_id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku名称',
  `sku_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品sku编码',
  `sku_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'sku规格格式',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku单价',
  `market_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku市场价',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'sku成本价',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku库存',
  `weight` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '重量（单位g）',
  `volume` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '体积（单位立方米）',
  `click_num` int(11) NOT NULL DEFAULT 0 COMMENT '点击量',
  `sale_num` int(11) NOT NULL DEFAULT 0 COMMENT '销量',
  `collect_num` int(11) NOT NULL DEFAULT 0 COMMENT '收藏量',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku主图',
  `sku_images` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'sku图片',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `goods_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品种类1.实物商品2.虚拟商品3.卡券商品',
  `goods_class_name` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品种类',
  `goods_attr_class` int(11) NOT NULL DEFAULT 1 COMMENT '商品类型id',
  `goods_attr_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属分站id',
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌id',
  `brand_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属品牌名称',
  `goods_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品详情',
  `is_own` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否自营',
  `goods_state` tinyint(4) NOT NULL DEFAULT 1 COMMENT '商品状态（1.正常0下架）',
  `verify_state` int(11) NOT NULL DEFAULT 1 COMMENT '审核状态（1 已审核 0 待审核 10 违规下架 -1 审核中 -2 审核失败）',
  `verify_state_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品违规或审核失败说明',
  `goods_stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT '库存预警',
  `is_virtual` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否虚拟类商品（0实物1.虚拟）',
  `virtual_indate` int(11) NOT NULL DEFAULT 1 COMMENT '虚拟商品有效期',
  `is_free_shipping` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否免邮',
  `shipping_template` int(11) NOT NULL DEFAULT 0 COMMENT '指定运费模板',
  `goods_spec_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品规格格式',
  `goods_attr_format` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品属性格式',
  `is_delete` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已经删除',
  `introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '促销语',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关键词',
  `unit` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `video_url` varchar(555) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '视频',
  `evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '评价数',
  `evaluate_shaitu` int(11) NOT NULL DEFAULT 0 COMMENT '晒图评价数',
  `evaluate_shipin` int(11) NOT NULL DEFAULT 0 COMMENT '视频评价数',
  `evaluate_zhuiping` int(11) NOT NULL DEFAULT 0 COMMENT '追评数',
  `spec_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '规格名称',
  `evaluate_haoping` int(11) NOT NULL DEFAULT 0 COMMENT '好评数',
  `evaluate_zhongping` int(11) NOT NULL DEFAULT 0 COMMENT '中评数',
  `evaluate_chaping` int(11) NOT NULL DEFAULT 0 COMMENT '差评数',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '所属店铺id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '供应商名称',
  `price_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `min_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最低价',
  `max_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最高价',
  `min_num` int(11) NOT NULL DEFAULT 0 COMMENT '最小购买量',
  `stock_alarm` int(11) NOT NULL DEFAULT 0 COMMENT 'sku库存预警',
  `sale_sort` int(11) NOT NULL DEFAULT 0 COMMENT '销量排序字段 占位用',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认',
  PRIMARY KEY (`sku_id`) USING BTREE,
  INDEX `IDX_supply_goods_brand_id`(`brand_id`) USING BTREE,
  INDEX `IDX_supply_goods_goods_class`(`goods_class`) USING BTREE,
  INDEX `IDX_supply_goods_is_delete`(`is_delete`) USING BTREE,
  INDEX `IDX_supply_goods_is_own_shop`(`is_own`) USING BTREE,
  INDEX `IDX_supply_goods_sort`(`sort`) USING BTREE,
  INDEX `IDX_supply_goods_website_id`(`website_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_goods_sku
-- ----------------------------

-- ----------------------------
-- Table structure for supply_open_account
-- ----------------------------
DROP TABLE IF EXISTS `supply_open_account`;
CREATE TABLE `supply_open_account`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账单编号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺ID',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '费用',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '类型（1开店  2续签）',
  `type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '关联开店续签id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '时间',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '对应分站',
  `website_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分站名称',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站分成',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站结算id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺开店费用流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_open_account
-- ----------------------------

-- ----------------------------
-- Table structure for supply_order
-- ----------------------------
DROP TABLE IF EXISTS `supply_order`;
CREATE TABLE `supply_order`  (
  `order_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `order_name` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单内容',
  `order_from` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源',
  `order_from_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单来源名称',
  `order_type` int(11) NOT NULL DEFAULT 0 COMMENT '订单类型 1. 普通订单  2. 门店订单  3. 本地配送订单4. 虚拟订单',
  `order_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单类型名称',
  `out_trade_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付流水号',
  `out_trade_no_2` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付流水号（多次支付）',
  `delivery_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '整体提货编码',
  `order_status` int(11) NOT NULL DEFAULT 0 COMMENT '订单状态',
  `order_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单状态名称',
  `order_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单操作',
  `pay_status` int(11) NOT NULL DEFAULT 0 COMMENT '支付状态',
  `delivery_status` int(11) NOT NULL DEFAULT 0 COMMENT '配送状态',
  `refund_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `pay_type` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付方式',
  `pay_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '支付类型名称',
  `delivery_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '配送方式',
  `delivery_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送方式名称',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总金额',
  `delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '配送费用',
  `invoice_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发票金额',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单合计金额',
  `adjust_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单调整金额',
  `balance_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额支付金额',
  `pay_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '抵扣之后应付金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `pay_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单支付时间',
  `delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单配送时间',
  `sign_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单签收时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单完成时间',
  `close_time` int(11) NOT NULL DEFAULT 0 COMMENT '订单关闭时间',
  `is_lock` int(11) NOT NULL DEFAULT 0 COMMENT '是否锁定订单（针对维权，锁定不可操作）',
  `is_evaluate` int(11) NOT NULL DEFAULT 0 COMMENT '是否允许订单评价',
  `is_delete` int(11) NOT NULL DEFAULT 0 COMMENT '是否删除(针对后台)',
  `is_enable_refund` int(11) NOT NULL DEFAULT 0 COMMENT '是否允许退款',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '卖家留言',
  `goods_num` int(11) NOT NULL DEFAULT 0 COMMENT '商品件数',
  `delivery_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发货状态',
  `is_settlement` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否进行结算',
  `evaluate_status` int(11) NOT NULL DEFAULT 0 COMMENT '评价状态，0：未评价，1：已评价，2：已追评',
  `evaluate_status_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '评价状态名称，未评价，已评价，已追评',
  `supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台金额',
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单退款金额',
  `refund_supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款店铺金额',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款平台结算金额',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总支出佣金',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT 'shop_settlement表结算id',
  `buyer_shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买店铺id',
  `buyer_shop_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买店铺名称',
  `buyer_uid` int(11) NOT NULL DEFAULT 0 COMMENT '购买人uid',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人姓名',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人手机',
  `telephone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人固定电话',
  `province_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人省id',
  `city_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人市id',
  `district_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人区县id',
  `community_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人社区id',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人详细地址',
  `longitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址经度',
  `latitude` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人地址纬度',
  `buyer_ip` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人ip',
  `buyer_ask_delivery_time` int(11) NOT NULL DEFAULT 0 COMMENT '购买人要求配送时间',
  `buyer_message` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人留言信息',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `site_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_order
-- ----------------------------

-- ----------------------------
-- Table structure for supply_order_goods
-- ----------------------------
DROP TABLE IF EXISTS `supply_order_goods`;
CREATE TABLE `supply_order_goods`  (
  `order_goods_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单id',
  `order_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品skuid',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `sku_no` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `is_virtual` int(11) NOT NULL DEFAULT 0 COMMENT '是否是虚拟商品',
  `goods_class` int(11) NOT NULL DEFAULT 0 COMMENT '商品种类(1.实物 2.虚拟3.卡券)',
  `goods_class_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品类型名称',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品卖价',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '购买数量',
  `goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `cost_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本总价',
  `delivery_status` int(11) NOT NULL DEFAULT 0 COMMENT '配送状态',
  `delivery_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送单号',
  `refund_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款编号（申请产生）',
  `refund_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `refund_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款状态名称',
  `refund_status_action` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款操作',
  `refund_type` int(11) NOT NULL DEFAULT 0 COMMENT '退款方式',
  `refund_apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款申请金额',
  `refund_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款原因',
  `refund_real_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际退款金额',
  `refund_delivery_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款公司名称',
  `refund_delivery_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款单号',
  `refund_time` int(11) NOT NULL DEFAULT 0 COMMENT '实际退款时间',
  `refund_refuse_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款拒绝原因',
  `refund_action_time` int(11) NOT NULL DEFAULT 0 COMMENT '退款时间',
  `delivery_status_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配送状态名称',
  `commission_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '待结算佣金比率',
  `real_goods_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际商品购买价',
  `supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商实际金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台实际金额',
  `is_settlement` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否结算',
  `refund_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款说明',
  `refund_delivery_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '买家退货说明',
  `refund_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退货地址',
  `is_refund_stock` int(11) NOT NULL DEFAULT 0 COMMENT '是否返还库存',
  `refund_money_type` int(11) NOT NULL DEFAULT 1 COMMENT '退款方式   1 原路退款 2线下退款',
  `adjust_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '调整金额',
  `buyer_uid` int(11) NOT NULL DEFAULT 0 COMMENT '购买人uid',
  `buyer_shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '购买人店铺id',
  `buyer_shop_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购买人店铺名称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '供应商id',
  `site_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `is_move` int(11) NOT NULL DEFAULT 0 COMMENT '是否已经迁移过商品',
  `refund_delivery_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款中包含的运费',
  PRIMARY KEY (`order_goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_order_goods
-- ----------------------------

-- ----------------------------
-- Table structure for supply_order_refund_log
-- ----------------------------
DROP TABLE IF EXISTS `supply_order_refund_log`;
CREATE TABLE `supply_order_refund_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '订单项id',
  `refund_status` int(11) NOT NULL DEFAULT 0 COMMENT '退款状态',
  `refund_status_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '退款状态名称',
  `action` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作内容',
  `action_way` int(11) NOT NULL DEFAULT 2 COMMENT '操作类型1买家2卖家',
  `action_userid` int(11) NOT NULL DEFAULT 0 COMMENT '操作人id',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `action_time` int(11) NOT NULL DEFAULT 0 COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单退款操作表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_order_refund_log
-- ----------------------------

-- ----------------------------
-- Table structure for supply_purchase
-- ----------------------------
DROP TABLE IF EXISTS `supply_purchase`;
CREATE TABLE `supply_purchase`  (
  `purchase_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '求购单标题',
  `type` int(11) NOT NULL DEFAULT 1 COMMENT '求购类型   1 现货商品 2 定制商品',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '姓名',
  `sex` int(11) NOT NULL DEFAULT 1 COMMENT '性别 1 男 2 女',
  `mobile` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '求购截止日期',
  `is_invoice` int(11) NOT NULL DEFAULT 0 COMMENT '是否需要发票',
  `province` int(11) NOT NULL DEFAULT 0 COMMENT '省id',
  `province_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '省名称',
  `city` int(11) NOT NULL DEFAULT 0 COMMENT '城市id',
  `city_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '城市名称',
  `district` int(11) NOT NULL DEFAULT 0 COMMENT '区县id',
  `district_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '区县地址',
  `community` int(11) NOT NULL DEFAULT 0 COMMENT '乡镇地址id',
  `community_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '乡镇地址名称',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `full_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '完整地址',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '求购备注',
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `shop_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '用户 uid',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `goods_num` int(11) NOT NULL DEFAULT 0 COMMENT '商品数量',
  `goods_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价',
  `goods_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '状态  1进行中  2 已结束',
  `audit_status` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`purchase_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '求购表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_purchase
-- ----------------------------

-- ----------------------------
-- Table structure for supply_purchase_goods_item
-- ----------------------------
DROP TABLE IF EXISTS `supply_purchase_goods_item`;
CREATE TABLE `supply_purchase_goods_item`  (
  `purchase_item_id` int(11) NOT NULL AUTO_INCREMENT,
  `purchase_id` int(11) NOT NULL DEFAULT 0 COMMENT '求购主id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '采购商品名称',
  `category_id` int(11) NOT NULL DEFAULT 0 COMMENT '分类id',
  `category_id_1` int(11) NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `category_id_2` int(11) NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `category_id_3` int(11) NOT NULL DEFAULT 0 COMMENT '三级分类id',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '采购数量',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '期望单价',
  `goods_image` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品主图路径',
  `goods_images` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片路径',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '求购备注',
  `shop_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `shop_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '用户 uid',
  `category_name_1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '一级分类名称',
  `category_name_2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `category_name_3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '三级级分类名称',
  `category_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类',
  PRIMARY KEY (`purchase_item_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '求购商品项表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_purchase_goods_item
-- ----------------------------

-- ----------------------------
-- Table structure for supply_reopen
-- ----------------------------
DROP TABLE IF EXISTS `supply_reopen`;
CREATE TABLE `supply_reopen`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reopen_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '店铺id',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站ID',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '申请会员id',
  `apply_state` int(11) NOT NULL DEFAULT 1 COMMENT '申请状态 1. 待审核 -1.审核失败 2.审核成功',
  `apply_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员审核信息',
  `apply_year` int(11) NOT NULL DEFAULT 1 COMMENT '开店时长(年)',
  `shop_group_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '店铺分组名称',
  `shop_group_id` int(11) NOT NULL DEFAULT 0 COMMENT ' 店铺分组ID',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证',
  `paying_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '付款金额',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '付款凭证说明',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NOT NULL DEFAULT 0 COMMENT '审核通过时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '完成时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺续签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_reopen
-- ----------------------------

-- ----------------------------
-- Table structure for supply_service
-- ----------------------------
DROP TABLE IF EXISTS `supply_service`;
CREATE TABLE `supply_service`  (
  `apply_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请站点名称',
  `service_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请服务类型',
  `service_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '申请服务类型名称',
  `status` int(11) NULL DEFAULT 0 COMMENT '申请状态0待审核1.已审核-1已拒绝',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '同意或者拒绝理由',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '创建时间',
  `audit_time` int(11) NULL DEFAULT 0 COMMENT '通过时间',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺申请服务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_service
-- ----------------------------

-- ----------------------------
-- Table structure for supply_settlement
-- ----------------------------
DROP TABLE IF EXISTS `supply_settlement`;
CREATE TABLE `supply_settlement`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `settlement_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `period_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算周期id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺金额',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款抽成',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台抽成',
  `refund_supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺退款金额',
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结束时间',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金支出',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站分成',
  `settlement_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `settlement_no_index`(`settlement_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for supply_settlement_period
-- ----------------------------
DROP TABLE IF EXISTS `supply_settlement_period`;
CREATE TABLE `supply_settlement_period`  (
  `period_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `period_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `supply_num` int(11) NOT NULL DEFAULT 0 COMMENT '结算店铺数量',
  `order_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_supply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款总金额',
  `platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台抽成',
  `refund_platform_money` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `refund_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结算时间',
  `commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金金额',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `website_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分站总分成',
  PRIMARY KEY (`period_id`) USING BTREE,
  UNIQUE INDEX `period_no`(`period_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_settlement_period
-- ----------------------------

-- ----------------------------
-- Table structure for supply_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `supply_withdraw`;
CREATE TABLE `supply_withdraw`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `withdraw_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现流水编号',
  `site_id` int(11) NOT NULL DEFAULT 0,
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人手机',
  `bank_type` int(11) NOT NULL DEFAULT 0 COMMENT '账户类型1.银行2.支付宝',
  `settlement_bank_account_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行开户名',
  `settlement_bank_account_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司支行名',
  `settlement_bank_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行所在地',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现金额',
  `apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `payment_time` int(11) NOT NULL DEFAULT 0 COMMENT '转账时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态0待审核1.待转账2已转账 -1拒绝',
  `memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后修改时间',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上传付款凭证',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应商提现表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supply_withdraw
-- ----------------------------

-- ----------------------------
-- Table structure for sys_upgrade_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_upgrade_log`;
CREATE TABLE `sys_upgrade_log`  (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `upgrade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '升级编号 每次的编号都不同',
  `upgrade_time` int(11) NOT NULL DEFAULT 0 COMMENT '升级时间 记录开始时间',
  `version_info` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '版本信息 json数据 包含升级前和升级后的基本信息',
  `backup_root` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备份文件和sql的根目录',
  `download_root` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '下载文件的根目录',
  `status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '升级状态 0 进行中 1 升级成功 2 升级失败',
  `error_message` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '升级失败错误信息',
  PRIMARY KEY (`log_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统升级日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_upgrade_log
-- ----------------------------

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `uid` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `app_module` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '应用模块',
  `app_group` int(11) NOT NULL DEFAULT 0 COMMENT '应用所属组',
  `is_admin` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否是管理员',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `group_id` int(11) NOT NULL DEFAULT 0 COMMENT '权限id',
  `group_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '权限组',
  `username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0,
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '状态 1 正常',
  `login_time` int(11) NOT NULL DEFAULT 0 COMMENT '最新一次登陆时间',
  `login_ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '最新登录ip',
  PRIMARY KEY (`uid`) USING BTREE,
  INDEX `IDX_user`(`group_id`, `app_module`) USING BTREE,
  INDEX `IDX_user_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_user_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_user_username`(`username`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 97 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '站点后台用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user
-- ----------------------------

-- ----------------------------
-- Table structure for user_log
-- ----------------------------
DROP TABLE IF EXISTS `user_log`;
CREATE TABLE `user_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '操作用户ID',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '对应url',
  `data` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '传输数据',
  `ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'ip地址',
  `action_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作行为',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_user_log`(`uid`, `site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 681 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_log
-- ----------------------------

-- ----------------------------
-- Table structure for verifier
-- ----------------------------
DROP TABLE IF EXISTS `verifier`;
CREATE TABLE `verifier`  (
  `verifier_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '核销员id',
  `verifier_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销员姓名',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '商家id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '前台会员id',
  `uid` int(11) NOT NULL DEFAULT 0 COMMENT '后台用户id',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`verifier_id`) USING BTREE,
  INDEX `IDX_verifier_member_id`(`member_id`) USING BTREE,
  INDEX `IDX_verifier_site_id`(`site_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '核销员（商品或订单商品）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of verifier
-- ----------------------------

-- ----------------------------
-- Table structure for verify
-- ----------------------------
DROP TABLE IF EXISTS `verify`;
CREATE TABLE `verify`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `verify_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销码',
  `verify_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销类型',
  `verify_type_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销类型名称',
  `verify_content_json` varchar(5000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销相关数据',
  `verifier_id` int(11) NOT NULL DEFAULT 0 COMMENT '核销员id',
  `verifier_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '核销员姓名',
  `is_verify` int(11) NOT NULL DEFAULT 0 COMMENT '是否已经核销',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `verify_time` int(11) NOT NULL DEFAULT 0 COMMENT '核销时间',
  `relate_id` int(11) NOT NULL DEFAULT 0 COMMENT '业务关联id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_verify_is_verify`(`is_verify`) USING BTREE,
  INDEX `IDX_verify_site_id`(`site_id`) USING BTREE,
  INDEX `IDX_verify_verify_code`(`verify_code`) USING BTREE,
  INDEX `IDX_verify_verify_time`(`verify_time`) USING BTREE,
  INDEX `IDX_verify_verify_type`(`verify_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '核销编码管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of verify
-- ----------------------------

-- ----------------------------
-- Table structure for video
-- ----------------------------
DROP TABLE IF EXISTS `video`;
CREATE TABLE `video`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '标题',
  `video_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '视频',
  `site_id` int(11) NULL DEFAULT 0 COMMENT '关联商家',
  `goods_id` int(11) NULL DEFAULT 0 COMMENT '关联商品',
  `point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '观看获得积分',
  `point_num` int(11) NULL DEFAULT 0 COMMENT '每人观看获得积分次数',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '创建时间',
  `is_new` tinyint(4) NULL DEFAULT 0 COMMENT '是否新视频:1=是,0=否',
  `weight` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '权重',
  `second` int(11) NULL DEFAULT 0 COMMENT '转动秒数',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '城市分站',
  `order_num` int(11) NULL DEFAULT 0 COMMENT '商品下单次数',
  `comment_num` int(11) NULL DEFAULT 0 COMMENT '评论数',
  `share_count` int(11) NULL DEFAULT 0 COMMENT '转发数',
  `end_count` int(11) NULL DEFAULT 0 COMMENT '完播数',
  `end_time` int(11) NULL DEFAULT 0 COMMENT '置顶到期时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '短视频' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of video
-- ----------------------------

-- ----------------------------
-- Table structure for video_comment
-- ----------------------------
DROP TABLE IF EXISTS `video_comment`;
CREATE TABLE `video_comment`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NULL DEFAULT 0 COMMENT '用户ID',
  `content` varchar(510) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '评论内容',
  `category_id` int(11) NULL DEFAULT 0 COMMENT '评论ID',
  `create_time` int(11) NULL DEFAULT 0,
  `pid` int(11) NULL DEFAULT 0 COMMENT '上级ID',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '类型:video=视频',
  `again_is_audit` int(11) NULL DEFAULT 0 COMMENT '审核状态：0 未审核 1 审核通过，2 审核拒绝',
  `collect_count` int(11) NULL DEFAULT 0 COMMENT '点赞量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '视频评论表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of video_comment
-- ----------------------------

-- ----------------------------
-- Table structure for video_log
-- ----------------------------
DROP TABLE IF EXISTS `video_log`;
CREATE TABLE `video_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `video_id` int(11) NULL DEFAULT 0 COMMENT '视频ID',
  `member_id` int(11) NULL DEFAULT 0 COMMENT '用户',
  `point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '观看获得积分',
  `create_time` int(11) NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '视频观看领取积分记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of video_log
-- ----------------------------

-- ----------------------------
-- Table structure for weapp_goods
-- ----------------------------
DROP TABLE IF EXISTS `weapp_goods`;
CREATE TABLE `weapp_goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL COMMENT '站点id',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '小程序商品库商品id 非商城商品id',
  `name` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `cover_img` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品图片链接',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `status` int(255) NOT NULL DEFAULT 0 COMMENT '商品状态，0：未审核。1：审核中，2：审核通过，3：审核驳回',
  `url` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品小程序链接',
  `audit_id` int(11) NOT NULL DEFAULT 0 COMMENT '审核单id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品sku_id',
  `third_party_tag` int(1) NOT NULL DEFAULT 1 COMMENT '商品来源 0在小程序平台添加的商品  1/2通过api添加的商品',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of weapp_goods
-- ----------------------------

-- ----------------------------
-- Table structure for weapp_live_room
-- ----------------------------
DROP TABLE IF EXISTS `weapp_live_room`;
CREATE TABLE `weapp_live_room`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `roomid` int(11) NOT NULL DEFAULT 0 COMMENT '直播间id',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '房间名称',
  `cover_img` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '房间背景封面',
  `share_img` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分享卡片图片',
  `start_time` int(11) NOT NULL DEFAULT 0 COMMENT '直播计划开始时间',
  `end_time` int(11) NOT NULL DEFAULT 0 COMMENT '直播计划结束时间',
  `anchor_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '主播昵称',
  `goods` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '直播间商品',
  `live_status` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'live_status  101: 直播中, 102: 未开始, 103: 已结束, 104: 禁播, 105: 暂停中, 106: 异常, 107: 已过期',
  `anchor_img` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '主播头像',
  `banner` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '直播间横幅',
  `audit_status` int(11) NOT NULL DEFAULT 0 COMMENT '审核状态 0待审核 1 审核已通过 -1 已拒绝',
  `refuse_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由',
  `type` int(11) NOT NULL DEFAULT 0 COMMENT '直播方式 0 手机直播',
  `close_like` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启点赞',
  `close_goods` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启货架',
  `close_comment` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启评论',
  `anchor_wechat` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主播微信号',
  `site_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `feeds_img` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '购物直播频道封面图',
  `close_replay` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启回放',
  `close_share` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启分享',
  `close_kf` int(11) NOT NULL DEFAULT 0 COMMENT '是否开启客服',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小程序直播直播间表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of weapp_live_room
-- ----------------------------

-- ----------------------------
-- Table structure for website
-- ----------------------------
DROP TABLE IF EXISTS `website`;
CREATE TABLE `website`  (
  `site_id` int(10) NOT NULL DEFAULT 0,
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站主题',
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站logo',
  `desc` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站简介',
  `keywords` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站关键字',
  `web_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站地址',
  `web_qrcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站二维码',
  `web_email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站邮箱',
  `web_phone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `web_qq` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '网站qq',
  `web_weixin` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系人微信号',
  `web_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '网站状态',
  `close_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '关闭原因',
  `wap_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '手机端状态',
  `account` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户金额',
  `account_withdraw` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已提现金额',
  `account_shop` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺入驻费用',
  `account_order` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单结算费用',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `wap_domain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'wap端域名',
  `site_area_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站城市id',
  `site_area_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '全国' COMMENT '分站城市名称',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'admin' COMMENT '分站管理员',
  `shop_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '开店分佣比率',
  `order_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单分佣比率',
  `settlement_bank_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行开户名',
  `settlement_bank_account_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行支行名称',
  `settlement_bank_address` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算开户银行所在地',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '分站状态（1正常 -1冻结）',
  `web_domain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '电脑端域名',
  `douyin_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '抖音直播二维码',
  `yao_point` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '邀请好友送积分数量',
  `video_url_info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '简介视频',
  `content_info` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '简介内容',
  `mini_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '小程序名称',
  `mini_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '小程序logo',
  `shop_deposit_amount` float(11, 2) NULL DEFAULT 0.00 COMMENT '商铺保证金',
  `sh_status` tinyint(4) NULL DEFAULT 0,
  PRIMARY KEY (`site_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统站点设置（城市分站）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of website
-- ----------------------------

-- ----------------------------
-- Table structure for website_settlement
-- ----------------------------
DROP TABLE IF EXISTS `website_settlement`;
CREATE TABLE `website_settlement`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `settlement_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `period_id` int(11) NOT NULL DEFAULT 0 COMMENT '结算周期id',
  `website_id` int(11) NOT NULL DEFAULT 0 COMMENT '分站id',
  `website_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分站名称',
  `shop_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '入驻支出',
  `order_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单分成',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结束时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1101 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of website_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for website_settlement_period
-- ----------------------------
DROP TABLE IF EXISTS `website_settlement_period`;
CREATE TABLE `website_settlement_period`  (
  `period_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `settlement_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `website_num` int(11) NOT NULL DEFAULT 0 COMMENT '分站数量',
  `order_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单分成',
  `shop_commission` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '入驻抽成',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `period_start_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期开始时间',
  `period_end_time` int(11) NOT NULL DEFAULT 0 COMMENT '账期结束时间',
  PRIMARY KEY (`period_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 222 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '城市分站周期结算' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of website_settlement_period
-- ----------------------------

-- ----------------------------
-- Table structure for website_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `website_withdraw`;
CREATE TABLE `website_withdraw`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `withdraw_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '提现流水编号',
  `website_id` int(11) NOT NULL DEFAULT 0,
  `website_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分站名称',
  `bank_type` int(11) NOT NULL DEFAULT 0 COMMENT '账户类型',
  `settlement_bank_account_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '银行开户名',
  `settlement_bank_account_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司银行账号',
  `settlement_bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算公司支行名',
  `settlement_bank_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '结算银行所在地',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现金额',
  `apply_time` int(11) NOT NULL DEFAULT 0 COMMENT '申请时间',
  `payment_time` int(11) NOT NULL DEFAULT 0 COMMENT '转账时间',
  `status` int(11) NOT NULL DEFAULT 0 COMMENT '状态0待审核1.待转账2已转账 -1拒绝',
  `memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '最后修改时间',
  `paying_money_certificate` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上传付款凭证',
  `paying_money_certificate_explain` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '说明',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分站转账记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of website_withdraw
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_fans
-- ----------------------------
DROP TABLE IF EXISTS `wechat_fans`;
CREATE TABLE `wechat_fans`  (
  `fans_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '粉丝ID',
  `nickname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `nickname_decode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '昵称编码',
  `headimgurl` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `sex` smallint(6) NOT NULL DEFAULT 1 COMMENT '性别',
  `language` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户语言',
  `country` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '国家',
  `province` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '城市',
  `district` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '行政区/县',
  `openid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户的标识，对当前公众号唯一     用户的唯一身份ID',
  `unionid` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '粉丝unionid',
  `groupid` int(11) NOT NULL DEFAULT 0 COMMENT '粉丝所在组id',
  `is_subscribe` bigint(1) NOT NULL DEFAULT 1 COMMENT '是否订阅',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `subscribe_time` int(11) NOT NULL DEFAULT 0 COMMENT '关注时间',
  `subscribe_scene` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '返回用户关注的渠道来源',
  `unsubscribe_time` int(11) NOT NULL DEFAULT 0 COMMENT '取消关注时间',
  `update_date` int(11) NOT NULL DEFAULT 0 COMMENT '粉丝信息最后更新时间',
  `tagid_list` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户被打上的标签ID列表',
  `subscribe_scene_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '返回用户关注的渠道来源名称',
  `qr_scene` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'qr_scene',
  `qr_scene_str` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'qr_scene_str',
  PRIMARY KEY (`fans_id`) USING BTREE,
  INDEX `IDX_weixin_fans`(`unionid`, `openid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信粉丝列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_fans
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_fans_tag
-- ----------------------------
DROP TABLE IF EXISTS `wechat_fans_tag`;
CREATE TABLE `wechat_fans_tag`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tags` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信拉取到的标签内容 json格式',
  `tag_id` int(11) NOT NULL DEFAULT 0 COMMENT '标签id',
  `tag_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '标签名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_wechat_fans_tag`(`tag_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信粉丝标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_fans_tag
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_mass_recording
-- ----------------------------
DROP TABLE IF EXISTS `wechat_mass_recording`;
CREATE TABLE `wechat_mass_recording`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `status` int(50) NOT NULL DEFAULT 0 COMMENT '发送状态1-成功  0-失败',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `member_label` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发送群体（会员标签）',
  `media_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '素材id',
  `err` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '错误信息',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信消息记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_mass_recording
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_media
-- ----------------------------
DROP TABLE IF EXISTS `wechat_media`;
CREATE TABLE `wechat_media`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '类型',
  `value` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '值',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  `media_id` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '微信端返回的素材id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信素材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_media
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_qrcode
-- ----------------------------
DROP TABLE IF EXISTS `wechat_qrcode`;
CREATE TABLE `wechat_qrcode`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '实例ID',
  `background` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '背景图片',
  `nick_font_color` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '#000' COMMENT '昵称字体颜色',
  `nick_font_size` smallint(6) NOT NULL DEFAULT 12 COMMENT '昵称字体大小',
  `is_logo_show` smallint(6) NOT NULL DEFAULT 1 COMMENT 'logo是否显示',
  `header_left` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '头部左边距',
  `header_top` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '头部上边距',
  `name_left` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '昵称左边距',
  `name_top` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '昵称上边距',
  `logo_left` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT 'logo左边距',
  `logo_top` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT 'logo上边距',
  `code_left` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '二维码左边距',
  `code_top` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0px' COMMENT '二维码上边距',
  `is_default` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `is_remove` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否删除  0未删除 1删除',
  `update_time` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信推广二维码模板管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_qrcode
-- ----------------------------

-- ----------------------------
-- Table structure for wechat_replay_rule
-- ----------------------------
DROP TABLE IF EXISTS `wechat_replay_rule`;
CREATE TABLE `wechat_replay_rule`  (
  `rule_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '规则名称',
  `rule_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'KEYWORDS' COMMENT '规则类型KEYWORDS表示关键字,DEFAULT表示默认,AFTER表示关注后',
  `keywords_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '关键字json',
  `replay_json` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '回复内容json',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `modify_time` int(11) NOT NULL DEFAULT 0 COMMENT '修改时间',
  PRIMARY KEY (`rule_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信回复规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wechat_replay_rule
-- ----------------------------

-- ----------------------------
-- Table structure for wholesale_goods
-- ----------------------------
DROP TABLE IF EXISTS `wholesale_goods`;
CREATE TABLE `wholesale_goods`  (
  `wholesale_goods_id` int(11) NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `min_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最低价',
  `max_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最高价',
  `min_num` int(11) NOT NULL DEFAULT 0,
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `status` int(11) NOT NULL DEFAULT 0,
  `goods_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  PRIMARY KEY (`wholesale_goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '批发商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wholesale_goods
-- ----------------------------

-- ----------------------------
-- Table structure for wholesale_goods_cart
-- ----------------------------
DROP TABLE IF EXISTS `wholesale_goods_cart`;
CREATE TABLE `wholesale_goods_cart`  (
  `cart_id` int(11) NOT NULL AUTO_INCREMENT,
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `member_id` int(11) NOT NULL DEFAULT 0 COMMENT '会员id',
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT 'sku_id',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '数量',
  PRIMARY KEY (`cart_id`) USING BTREE,
  INDEX `IDX_wholesale_goods_cart_member_id`(`member_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '进货单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wholesale_goods_cart
-- ----------------------------

-- ----------------------------
-- Table structure for wholesale_goods_sku
-- ----------------------------
DROP TABLE IF EXISTS `wholesale_goods_sku`;
CREATE TABLE `wholesale_goods_sku`  (
  `wholesale_sku_id` int(11) NOT NULL AUTO_INCREMENT,
  `sku_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品规格id',
  `sku_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `price_json` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `min_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最低价',
  `max_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最高价',
  `min_num` int(11) NOT NULL DEFAULT 0 COMMENT '最小购买量',
  `create_time` int(11) NOT NULL DEFAULT 0,
  `update_time` int(11) NOT NULL DEFAULT 0,
  `sku_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '规格图片',
  `site_id` int(11) NOT NULL DEFAULT 0 COMMENT '站点id',
  `site_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '站点名称',
  `goods_id` int(11) NOT NULL DEFAULT 0 COMMENT '商品id',
  PRIMARY KEY (`wholesale_sku_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '批发商品规格表' ROW_FORMAT = Dynamic;

