INSERT INTO `document` VALUES (8, 0, 'admin', 'GOODS_AFTER_SALE', '售后保障协议', '<p><span style=\"color: rgb(255, 0, 0);\"><strong>权利声明：</strong></span><br/>商城上的所有商品信息、客户评价、商品咨询、网友讨论等内容，是商城重要的经营资源，未经许可，禁止非法转载使用。</p><p><span style=\"color: rgb(63, 63, 63);\"><strong>注：</strong></span>本站商品信息均来自于合作方，其真实性、准确性和合法性由信息拥有者（合作方）负责。本站不提供任何保证，并不承担任何法律责任。</p><p><br/><span style=\"color: rgb(255, 0, 0);\"><strong>价格说明：</strong></span><br/></p><p><span style=\"color: rgb(63, 63, 63);\"><strong>价格：</strong></span>价格为商品的销售价，是您最终决定是否购买商品的依据。</p><p><span style=\"color: rgb(63, 63, 63);\"><strong>划线价：</strong></span>商品展示的划横线价格为参考价，该价格可能是品牌专柜标价、商品吊牌价或由品牌供应商提供的正品零售价（如厂商指导价、建议零售价等）或该商品在商城平台上曾经展示过的销售价；由于地区、时间的差异性和市场行情波动，品牌专柜标价、商品吊牌价等可能会与您购物时展示的不一致，该价格仅供您参考。</p><p><span style=\"color: rgb(63, 63, 63);\"><strong>折扣：</strong></span>如无特殊说明，折扣指销售商在原价、或划线价（如品牌专柜标价、商品吊牌价、厂商指导价、厂商建议零售价）等某一价格基础上计算出的优惠比例或优惠金额；如有疑问，您可在购买前联系销售商进行咨询。</p><p><span style=\"color: rgb(63, 63, 63);\"><strong>异常问题：</strong></span>商品促销信息以商品详情页“促销”栏中的信息为准；商品的具体售价以订单结算页价格为准；如您发现活动商品售价或促销信息有异常，建议购买前先联系销售商咨询。</p><p><br/></p><p><br/></p>', 1733193299, 0);
INSERT INTO `document` VALUES (9, 0, 'admin', 'GET_PRI', '隐私政策', '<p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">一、政策声明</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">【服务提供方名称，可根据实际情况填写，如：XX 科技有限公司、XX 平台运营团队】（以下简称 “我们”）高度重视用户（以下简称 “您”）的个人信息保护，致力于保障您的信息安全与合法权益。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本《隐私政策》（以下简称 “政策”）旨在向您说明，我们在提供【具体服务名称，如：APP、网站、线下服务等，未明确时可写 “相关服务”】（以下简称 “本服务”）过程中，如何收集、使用、存储、共享、转让、公开披露您的个人信息，以及您享有的信息管理权利。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本政策是《用户协议》的重要组成部分，与《用户协议》具有同等法律效力。您在注册、登录、使用本服务的任何环节，均视为已充分阅读、理解并同意本政策全部内容；若您不同意本政策，应立即停止使用本服务。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们有权根据法律法规更新、业务调整等情况，对本政策进行修改。修改后的政策将通过【通知方式，如：APP 弹窗、官网公告、短信】向您公示，公示之日起【合理期限，如：7 日】后生效。若您继续使用本服务，即视为接受修改后的政策；若您不同意，应停止使用本服务。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">二、信息收集范围与方式</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（一）您主动提供的信息</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">注册与账号管理信息：您在注册账号时，需根据提示提供【如：手机号、邮箱地址、用户名、密码】，若您选择实名认证（如使用金融、出行类服务），还需提供【如：身份证号、银行卡信息、生物识别信息（指纹 / 面容）】，此类信息用于账号创建、身份核验及账号安全维护。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">服务使用相关信息：您在使用本服务过程中，主动提交的【如：订单信息（收货地址、联系方式、商品偏好）、内容发布信息（评论、图文、视频）、咨询反馈信息（问题描述、沟通记录）】，此类信息用于为您提供对应服务、处理您的需求。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">其他主动提供的信息：您参与我们举办的【如：活动报名、问卷调查、用户访谈】时，根据活动要求提供的【如：姓名、联系方式、地址、兴趣偏好】，此类信息用于活动组织、结果通知及后续服务优化。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（二）我们自动收集的信息</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">设备与网络信息：当您使用本服务时，我们会通过技术手段自动收集您的【如：设备型号、操作系统版本、设备唯一标识（IMEI、MAC 地址）、IP 地址、网络类型（WiFi / 蜂窝网络）、浏览器类型】，此类信息用于保障服务兼容性、优化服务体验及识别异常访问。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">使用行为信息：我们会记录您使用本服务的【如：页面浏览记录、功能使用记录（点击、搜索、收藏）、服务使用时长、操作路径】，此类信息用于分析用户行为、优化服务功能（如个性化推荐）及提升服务质量。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">位置信息（若适用）：若您开启设备定位权限并同意我们收集位置信息（如使用地图、本地生活类服务），我们会收集您的【如：大致位置（基于 IP 地址）、精确位置（基于 GPS / 北斗）】，此类信息用于提供【如：附近服务推荐、位置相关功能】，您可随时在设备设置中关闭定位权限，停止信息收集。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（三）从第三方获取的信息</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您通过第三方平台（如微信、支付宝、社交媒体账号）授权登录本服务，或我们与合作方（如支付服务商、数据服务商）合作提供服务，我们会从第三方获取【如：您在第三方平台的昵称、头像、授权范围内的用户信息】，此类信息的获取已获得您的授权，且我们会要求第三方保障信息来源的合法性。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">三、信息使用规则</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">基础服务保障：我们会使用收集的信息，为您提供【如：账号登录验证、服务功能实现（订单处理、内容展示）、客服咨询响应】等基础服务，确保本服务正常运行。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">服务优化与个性化：我们会对收集的【设备信息、使用行为信息】进行分析，用于【如：优化服务界面、改进功能体验、根据您的偏好提供个性化内容推荐（如商品、资讯）】，提升您使用本服务的便捷性与满意度。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">安全保障：我们会使用【账号信息、设备信息、行为信息】识别异常登录（如异地登录、陌生设备登录）、防范恶意攻击（如盗号、刷单），并采取【如：账号冻结、验证码验证】等措施，保障您的账号安全与信息安全。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">合规与纠纷处理：我们会根据法律法规要求，或为处理【如：用户投诉、服务纠纷、违法违规行为】，使用相关信息进行调查、取证及责任认定，维护您及其他用户的合法权益。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">其他经授权的使用：若我们将信息用于本政策未明确说明的用途，会事先获得您的明确同意（如书面确认、弹窗授权）。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">四、信息存储与保护</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（一）信息存储</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">存储地点：我们收集的您的个人信息，将存储在【如：中国大陆境内服务器】，若因业务需要需将信息传输至境外，我们会按照《个人信息保护法》等法规要求，获得您的明确同意，并采取【如：数据加密、合规认证（如 ISO27001）】等措施，保障信息传输安全。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">存储期限：我们会按照 “最小必要” 及 “合理期限” 原则存储您的个人信息，具体存储期限如下：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）账号相关信息（如手机号、实名认证信息）：在您的账号存续期间持续存储，若您注销账号，我们会在完成必要审核后，按法律法规要求删除或匿名化处理（法律法规另有规定的除外）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）服务使用信息（如订单记录、行为记录）：存储至【如：服务结束后 1-3 年】，或至满足法律法规规定的留存期限（如交易记录需留存 5 年）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）临时收集的信息（如活动报名信息）：存储至【如：活动结束后 6 个月】，或至完成对应服务需求后，立即删除或匿名化处理。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（二）信息保护措施</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">技术保障：我们采用【如：数据加密（SSL/TLS）、访问权限控制（分级授权）、异常行为监测、病毒防护】等技术手段，防止信息被未授权访问、篡改、泄露或破坏。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">管理保障：我们建立了【如：信息安全管理制度、数据分类分级管理机制、员工保密协议】，明确员工访问信息的权限与流程，仅允许经授权的员工在必要范围内接触您的个人信息，并对员工进行定期信息安全培训。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">应急响应：若发生信息泄露、丢失等安全事件，我们会立即启动应急预案，采取【如：阻断泄露源、修复漏洞、通知受影响用户】等措施，并按照法律法规要求，及时向监管部门报告。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">五、信息共享、转让与公开披露</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（一）信息共享</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们不会未经您授权，将您的个人信息共享给第三方，但以下情况除外：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">合作服务需求：为向您提供完整服务（如支付、物流、客服），我们会向【如：支付服务商（微信支付 / 支付宝）、物流服务商（顺丰 / 中通）、客服外包团队】共享【如：订单信息（金额、收货地址）、联系方式】，且我们会与合作方签订保密协议，要求其仅在授权范围内使用信息，并采取安全保护措施；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">法律法规要求：根据【如：司法机关、行政机关（公安、市场监管）】的合法要求，我们会向其提供您的个人信息，且会对要求的合法性进行审核；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您的明确同意：在您明确授权或同意的情况下（如您主动选择第三方服务并授权信息共享），我们会按照您的要求共享信息。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（二）信息转让</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们不会未经您授权，将您的个人信息转让给任何第三方，除非发生【如：公司合并、分立、收购、破产清算】等情形，此时信息转让需获得您的同意（或符合法律法规规定的无需同意的情形），且我们会要求受让方继续履行信息保护义务，若受让方无法履行，我们会采取措施保护您的信息安全。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（三）信息公开披露</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们不会未经您授权，公开披露您的个人信息，除非发生以下情况：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您的明确同意：在您主动要求或同意的情况下（如您参与公开活动并同意展示信息），我们会按您的要求公开披露信息；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">合规与安全需求：为维护【如：国家安全、公共利益、用户合法权益】，或应对【如：重大安全事件、违法违规行为】，我们在法律法规允许的范围内，可公开披露相关信息（如公示违规用户账号信息）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">匿名化处理后的信息：我们可将经过匿名化处理（无法识别具体个人）的信息【如：用户行为统计数据、服务使用趋势数据】进行公开披露或商业利用，此类信息不视为个人信息。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">六、您的信息管理权利</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">根据《个人信息保护法》等法律法规，您对您的个人信息享有以下权利，我们会为您提供便捷的行使路径：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">知情权：您有权通过【如：账号设置页面、客服咨询】查询我们收集的您的个人信息类型、使用情况及存储期限，我们会在【合理期限，如：15 个工作日】内予以答复；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">更正权：若您发现您的个人信息存在错误（如手机号、地址有误），可通过【如：账号设置 - 个人信息编辑、客服反馈】申请更正，我们会在审核确认后【合理期限，如：7 个工作日】内完成更正；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">删除权：若您认为我们收集的信息超出必要范围、或您不再使用本服务，可通过【如：账号设置 - 信息删除、客服申请】要求删除相关信息，我们会在审核确认后【合理期限，如：15 个工作日】内完成删除（法律法规要求留存的除外）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">撤回同意权：您可随时撤回对信息收集、使用的同意（如关闭定位权限、取消个性化推荐），具体路径为【如：设备设置 - 应用权限管理、APP 内设置 - 隐私选项】，撤回同意不会影响此前基于您同意已进行的信息处理；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">账号注销权：您可通过【如：账号设置 - 注销账号、客服申请】申请注销账号，注销前请确保您已处理【如：未完成订单、账户余额】，账号注销后，我们会按本政策第四条第（一）款的约定，删除或匿名化处理您的个人信息（法律法规要求留存的除外）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">投诉举报权：若您认为我们的信息处理行为违反本政策或法律法规，可通过【联系方式，如：客服电话、投诉邮箱】向我们投诉举报，我们会在【合理期限，如：15 个工作日】内进行调查处理并反馈结果。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">七、第三方服务说明</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本服务可能包含第三方提供的【如：广告、链接、插件、服务入口】（如社交媒体分享按钮、第三方支付接口），第三方会根据其自身的隐私政策收集、使用您的信息，我们不对第三方的信息处理行为负责，也不对第三方服务的安全性、合法性承担责任；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您使用第三方服务时，需仔细阅读并同意第三方的隐私政策，您与第三方之间的信息交互及纠纷，由您与第三方自行解决；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们仅为第三方服务提供展示或跳转通道，不会将您的个人信息主动共享给第三方（除非获得您的明确授权或符合本政策第五条的约定）。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">八、未成年人信息保护</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您为未满 14 周岁的未成年人，需在法定监护人的陪同下阅读本政策，并由法定监护人代为同意本政策及提供个人信息；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们仅在法律法规允许、监护人同意或为保护未成年人权益的情况下，收集未成年人的【如：姓名、联系方式（监护人）、年龄】等必要信息，且会采取额外的保护措施（如限制信息使用范围、定期审核信息存储）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若监护人发现未成年人未经授权使用本服务并提供了个人信息，可通过【联系方式，如：客服电话、邮箱】与我们联系，我们会在审核确认后，及时删除相关信息并注销账号。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">九、争议解决</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本政策的订立、效力、解释、履行及争议解决，均适用《中华人民共和国法律》（不包括冲突法规则）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您与我们之间就本政策产生争议，应首先通过友好协商解决；协商不成的，任何一方均有权向【我们所在地有管辖权的人民法院】提起诉讼（或约定仲裁，如：提交 XX 仲裁委员会，按照该会现行仲裁规则进行仲裁）；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">在争议解决期间，除争议事项外，本政策其他条款应继续履行。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">十、其他条款</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本政策的任何条款被认定为无效或不可执行，不影响其他条款的效力，其他条款仍应继续履行；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您若对本政策或信息保护相关事宜有任何疑问，可通过【联系方式，如：客服电话、邮箱、在线客服入口】与我们沟通，我们会在合理期限内回复；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本政策未尽事宜，适用《用户协议》及相关法律法规的规定。</span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><br/></p>', 1756173941, 1760434000);
INSERT INTO `document` VALUES (10, 0, 'admin', 'GET_VIP', '用户协议', '<p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">一、协议范围与效力</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本《用户协议》（以下简称 “协议”）是用户（以下简称 “您”）与【服务提供方名称，可根据实际情况填写，如：XX 科技有限公司、XX 平台运营团队】（以下简称 “我们”）之间就使用我们提供的【具体服务名称，如：APP、网站、线下服务等，未明确时可写 “相关服务”】（以下简称 “本服务”）所订立的具有法律约束力的契约。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您在注册、登录、使用本服务的任何环节，均视为已充分阅读、理解并同意本协议全部条款。若您不同意本协议内容，应立即停止使用本服务。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们有权根据业务调整、法律法规更新等情况，对本协议条款进行修改。修改后的协议将通过【通知方式，如：APP 弹窗、官网公告、短信】向您公示，公示之日起【合理期限，如：7 日】后生效。若您继续使用本服务，即视为接受修改后的协议；若您不同意，应停止使用本服务。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">二、服务内容与使用规则</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（一）服务内容</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们将根据业务规划，为您提供【具体服务描述，如：信息查询、在线交易、内容分享、工具使用等】服务。具体服务范围及功能以本服务实际呈现为准，我们有权根据运营需求调整服务内容，且无需单独通知您，但重大调整将按本协议第一条第 3 款进行公示。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们将尽力保障本服务的稳定性与可用性，但因技术故障、网络问题、不可抗力（如自然灾害、政策调整）等非可控因素导致服务暂停、延迟或无法使用的，我们不承担违约责任，但会在合理范围内采取补救措施并及时通知您。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（二）使用规则</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您在使用本服务前，需按照要求完成注册，提供真实、准确、完整的个人信息（如手机号、邮箱、身份信息等）。若您提供的信息虚假、失效或不完整，我们有权拒绝为您提供服务，或暂停、终止您的账号使用权。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您应妥善保管账号及密码，不得将账号转借、出租、出售给他人使用。因您自身保管不当导致账号被盗用、信息泄露或产生其他损失的，由您自行承担责任；若您发现账号异常，应立即通知我们，我们将协助您采取冻结账号等措施，但不承担因通知延迟导致的损失。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您使用本服务时，不得从事以下行为：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）违反国家法律法规及政策，传播违法、暴力、色情、恐怖、虚假信息等危害国家安全、社会公共利益或侵犯他人合法权益的内容；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）破坏本服务的技术架构，如恶意攻击、植入病毒、篡改代码、刷单、刷量等干扰服务正常运行的行为；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）未经我们或第三方授权，获取、使用本服务中的数据、内容、技术等知识产权相关信息，或进行商业性利用；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（4）其他违反公序良俗、本协议约定或损害我们及其他用户合法权益的行为。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您违反上述使用规则，我们有权根据情节严重程度，采取警告、限制账号功能、暂停账号使用、永久封禁账号等措施，且无需退还您已支付的费用（如有）；若您的行为造成我们或第三方损失，您还需承担相应的赔偿责任。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">三、知识产权</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本服务中所有的内容（包括但不限于文字、图片、音频、视频、图标、界面设计、代码等）、技术及商标、logo、名称等标识，均归我们或相关权利人所有，受《中华人民共和国著作权法》《商标法》等法律法规保护。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您在使用本服务过程中，仅获得对本服务内容的非商业性使用权，不得擅自复制、修改、传播、展示、转让、许可他人使用上述知识产权相关内容，除非获得我们或相关权利人的书面授权。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您在本服务中上传、发布原创内容（如评论、作品、分享内容等），您应保证对该内容拥有完整的知识产权，且不侵犯任何第三方的合法权益。同时，您同意授予我们一项非独占、可转授权、全球范围内的免费使用权，可将该内容用于本服务的运营、推广（如展示、宣传、编辑整合）等用途，且无需额外向您支付费用。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">四、用户信息保护</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们将按照《中华人民共和国个人信息保护法》等法律法规的要求，保护您的个人信息安全。具体信息收集、使用、存储、共享等规则，详见我们单独发布的《隐私政策》。《隐私政策》是本协议的重要组成部分，与本协议具有同等法律效力。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您有权查询、更正、删除您的个人信息，或申请注销账号（具体路径以本服务实际提供为准）。若您申请注销账号，我们将在完成必要审核后，按法律法规要求删除或匿名化处理您的个人信息，但法律法规另有规定（如留存交易记录）的除外。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们不会未经您授权，将您的个人信息出售、出租给第三方，但以下情况除外：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）获得您的明确同意；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）为履行本协议义务、提供本服务所需，向我们的合作方（如支付服务商、技术服务商）共享，且合作方需遵守保密义务；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）根据法律法规、司法机关或行政机关的要求，提供您的个人信息。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">五、免责条款</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您明确知晓，本服务可能包含第三方提供的链接、内容或服务（如广告、合作平台入口）。我们仅提供跳转或展示服务，不对第三方内容的真实性、合法性、安全性负责，您与第三方之间的纠纷，由您自行解决。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">因以下情况导致您的损失，我们不承担责任：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）您违反本协议约定或法律法规规定，导致自身权益受损；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）因网络运营商、设备供应商等第三方原因，导致您无法使用本服务；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）不可抗力、意外事件（如火灾、停电）或技术升级等非我们可控因素，导致服务中断或数据丢失；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（4）您通过本服务获取的非我们官方发布的信息，或基于非官方信息做出的决策。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本服务提供的内容（如信息、建议、工具等）仅作为参考，不构成专业意见（如法律、金融、医疗建议），您应根据自身情况独立判断并承担相应风险。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">六、协议的终止</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您符合以下情形，我们有权终止本协议，停止为您提供服务：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）您主动申请注销账号；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）您违反本协议条款，经我们警告后仍不改正；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）您的账号长期（如 12 个月）未使用，且无未结清的交易或债务；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（4）我们停止运营本服务，且已按本协议第一条第 3 款进行公示。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">协议终止后，我们将停止为您提供服务，但仍需遵守以下义务：</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（1）按照《隐私政策》保护您的个人信息；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（2）留存您的交易记录等必要信息，直至法律法规规定的期限届满；</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">（3）若您有未结清的费用（如充值余额、未支付订单），我们将按约定退还或要求您支付。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">七、争议解决</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本协议的订立、效力、解释、履行及争议解决，均适用《中华人民共和国法律》（不包括冲突法规则）。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">若您与我们之间就本协议产生争议，应首先通过友好协商解决；协商不成的，任何一方均有权向【我们所在地有管辖权的人民法院】提起诉讼（或约定仲裁，如：提交 XX 仲裁委员会，按照该会现行仲裁规则进行仲裁）。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">在争议解决期间，除争议事项外，本协议其他条款应继续履行。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">八、其他条款</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">本协议的任何条款被认定为无效或不可执行，不影响其他条款的效力，其他条款仍应继续履行。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">我们未行使或延迟行使本协议项下的权利，不视为放弃该权利；我们行使部分权利，不影响其行使其他权利。</span><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\"></span></p></li><li><p><span style=\"-webkit-font-smoothing: antialiased; box-sizing: border-box; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); outline: none; border: 0px solid; margin: 0px; padding: 0px;\">您若对本协议或本服务有任何疑问，可通过【联系方式，如：客服电话、邮箱、在线客服入口】与我们沟通，我们将在合理期限内回复。</span></p></li></ol><ol class=\"list-number1 r-list r-list-number list-paddingleft-2\" style=\"list-style-type: none;\"></ol><p><br/></p>', 1756173956, 1760433913);
