INSERT INTO `goods` VALUES (22, '【午市】烤鱼2-3人餐', 1, '实物商品', 0, '', 28, '鱼见你（云集店）', 'upload/28/common/images/20250829/20250829104154175643531429111.png', 25, 0, '', '<p><span style=\"text-wrap-mode: nowrap;\">团购详情</span></p><p><span style=\"text-wrap-mode: nowrap;\">烤鱼</span></p><p><span style=\"text-wrap-mode: nowrap;\">鱼见你烤鱼(活鱼)(2.6~2.8斤) &gt;	(1份) ￥158	</span></p><p><span style=\"text-wrap-mode: nowrap;\">辅菜</span></p><p><span style=\"text-wrap-mode: nowrap;\">土豆片&gt;&nbsp; (1份)	￥5	</span></p><p><span style=\"text-wrap-mode: nowrap;\">木耳&gt;	(1份)	￥6	</span></p><p><span style=\"text-wrap-mode: nowrap;\">鱼豆腐 &gt;	(1份)	￥8	</span></p><p><span style=\"text-wrap-mode: nowrap;\">气泡豆干&gt;	(1份)	￥8</span></p><p><span style=\"text-wrap-mode: nowrap;\">手工黑豆花&gt; (1份)	￥10	</span></p><p><span style=\"text-wrap-mode: nowrap;\">饮料</span></p><p><span style=\"text-wrap-mode: nowrap;\">酸梅汤&gt;	(1份)	￥18	</span></p><p><span style=\"text-wrap-mode: nowrap;\">主食</span></p><p><span style=\"text-wrap-mode: nowrap;\">方便面&gt;	(1份)	￥5	</span></p><p><span style=\"text-wrap-mode: nowrap;\">备注：</span></p><p><span style=\"text-wrap-mode: nowrap;\">此套餐在哪个门店购买在哪个门店核销，云集店和中央花城店晚上9点后可用</span></p><p><span style=\"text-wrap-mode: nowrap;\">其他门店晚上不可以用</span></p><p><span style=\"text-wrap-mode: nowrap;\">鱼见你炭烤鱼6种口味任选:黑椒耗油，怪味，麻辣，酱香口味，青花椒，香辣。</span></p><p><img src=\"https://fuzhuangjifen.xing-peng.com/upload/28/common/images/20250829/20250829104353175643543318490.jpg\"/><img src=\"https://fuzhuangjifen.xing-peng.com/upload/28/common/images/20250829/20250829104353175643543316616.jpg\"/><img src=\"https://fuzhuangjifen.xing-peng.com/upload/28/common/images/20250829/20250829104353175643543304971.jpg\"/><img src=\"https://fuzhuangjifen.xing-peng.com/upload/28/common/images/20250829/20250829104352175643543297452.jpg\"/><img src=\"https://fuzhuangjifen.xing-peng.com/upload/28/common/images/20250829/20250829104352175643543295674.jpg\"/></p>', 1, 1, ',15,', '[\"15\"]', 1, '', 131.00, 218.00, 0.00, 5, 0, 0, 1, 1, 0,